def _compute_app_version():
    commit = os.environ.get("RENDER_GIT_COMMIT") or os.environ.get("SOURCE_VERSION")
    if commit:
        return commit[:12]
    try:
        return hashlib.sha256(Path(__file__).read_bytes()).hexdigest()[:12]
    except OSError:
        return "dev"


