# programma"), per restare visivamente identici al resto del gestionale
# invece di introdurre una nuova palette. Un tipo non elencato qui ricade
# su un'etichetta ed icona generiche.
REMINDER_GROUP_LABELS={
    "manual": ("pencil","state-pink","{n} promemoria manuale","{n} promemoria manuali"),
    "practice_incomplete": ("clipboard","state-purple","{n} pratica con dati da completare","{n} pratiche con dati da completare"),
    "product_reorder": ("receipt","state-blue","{n} prodotto da ordinare","{n} prodotti da ordinare"),
    "delivered_unpaid": ("calendar","state-red","{n} pratica consegnata ma non pagata","{n} pratiche consegnate ma non pagate"),
    "cremation_pending": ("paw","state-green","{n} cremazione singola in attesa","{n} cremazioni singole in attesa"),
    "assisted_notify_pending": ("phone","state-red","{n} assistita da avvisare","{n} assistite da avvisare"),
}
REMINDER_GROUP_FALLBACK=("bell","state-blue","{n} promemoria attivo","{n} promemoria attivi")
# Barra colorata laterale su ogni voce del Centro Promemoria (richiesta
# esplicita dell'utente, mockup di riferimento fornito): un colore coerente
# e distinguibile per tipo. I tipi automatici non elencati esplicitamente nel
# mockup sono stati assegnati al colore piu' vicino per significato
# (product_reorder e' un compito amministrativo -> viola come le pratiche
# incomplete; assisted_notify_pending riguarda le cremazioni -> stesso verde).
REMINDER_BAR_COLORS={
    "manual":"#ff4d6d",
    "practice_incomplete":"#9b5cf6",
    "product_reorder":"#9b5cf6",
    "delivered_unpaid":"#facc15",
    "cremation_pending":"#22c55e",
    "assisted_notify_pending":"#22c55e",
}
