def layout(title, body, user=None):
    body=body.replace("<th>Veterinario</th><th>Sede</th>","<th>Veterinario</th><th>Provenienza</th><th>Sede</th>")
    body=collapse_advanced_search(body)
    nav = ""; app_header=""; mobile_nav=""; body_class=""; body_attrs=""
    if user:
        with db() as conn:
            unread=conn.execute("SELECT count(*) n FROM notifications WHERE user_id=? AND is_read=0",(user["id"],)).fetchone()["n"]
            open_reminders_count=conn.execute("SELECT count(*) n FROM reminders WHERE completed_at IS NULL AND read_at IS NULL AND (snoozed_until IS NULL OR snoozed_until<=?)",(now(),)).fetchone()["n"]
        unread_badge=f'<span class="notification-badge">{unread if unread < 100 else "99+"}</span>' if unread else ''
        reminder_badge=f'<span class="notification-badge">{open_reminders_count if open_reminders_count < 100 else "99+"}</span>' if open_reminders_count else ''
        prefs=load_preferences(user["id"])
        if prefs.get("theme")=="light": body_class=" light-theme"
        body_attrs=f' data-has-session="1"{" data-server-theme=\"1\"" if "theme" in prefs else ""}'
        links=list(SIDEBAR_LINKS)
        sidebar_order=parse_preference_list(prefs.get("sidebar_order",""))
        if sidebar_order:
            links=reorder_by_saved(links,sidebar_order,lambda item:item[2])
        nav_links=''.join(f'<a href="{href}" class="{"nav-notification" if href in ("/notifiche","/") else ""}">{lucide(icon)}<span>{label}</span>{unread_badge if href=="/notifiche" else (reminder_badge if href=="/" else "")}</a>' for href,icon,label in links)
        nav=f'''<nav class="nav" aria-label="Menu principale">{nav_links}<button class="btn ghost install-btn" type="button" onclick="installPetParadise()">{lucide("plus")}<span>Installa App</span></button><a class="logout" href="/logout">{lucide("menu")}<span>Esci</span></a></nav>'''
        today=rome_now(); date_label=today.strftime("%d/%m/%Y"); weekday=["Lunedì","Martedì","Mercoledì","Giovedì","Venerdì","Sabato","Domenica"][today.weekday()]
        app_header=f'''<header class="app-header"><div class="header-actions"><form class="header-search lookup" action="/archivio/pratiche" method="get" role="search">{lucide("search")}<label class="sr-only" for="globalSearch">Ricerca rapida per animale o proprietario</label><input id="globalSearch" name="rapida" placeholder="Animale o proprietario..." autocomplete="off"><div id="globalSearchResults" class="lookup-results hidden"></div></form><a class="icon-btn nav-notification" href="/notifiche" aria-label="Notifiche, {unread} non lette">{lucide("bell")}{unread_badge}</a><button class="icon-btn" type="button" onclick="toggleTheme()" aria-label="Cambia tema">{lucide("sun")}</button><button class="btn header-new" type="button" onclick="toggleCreateMenu()" aria-label="Crea pratica o evento">{lucide("plus")}<span>Crea</span></button><time datetime="{today.date().isoformat()}">{date_label}<small>{weekday}</small></time></div></header>'''
        def more_card(href,icon,label):
            color,subtitle=MENU_CARD_META.get(label,("gray",""))
            accent=MENU_ACCENT_COLORS.get(color,"#64748b")
            badge=unread_badge if href=="/notifiche" else (reminder_badge if href=="/" else "")
            notif_cls=" nav-notification" if href in ("/notifiche","/") else ""
            return f'''<a href="{href}" class="more-card drag-item{notif_cls}" data-drag-key="{esc(label)}" draggable="false" style="--accent:{accent}"><span class="drag-handle" aria-label="Trascina per riordinare {esc(label)}">::</span><span class="more-card-icon">{lucide(icon)}</span><span class="more-card-copy"><b>{esc(label)}</b>{f"<small>{esc(subtitle)}</small>" if subtitle else ""}</span>{badge}<span class="more-card-chevron">{lucide("chevron-right")}</span></a>'''
        drawer_links=''.join(more_card(href,icon,label) for href,icon,label in links)
        drawer_order_json=esc(json.dumps([label for _,_,label in links],ensure_ascii=False))
        mobile_nav=f'''<nav class="bottom-nav" aria-label="Navigazione mobile"><a href="/">{lucide("home")}<span>Dashboard</span></a><a href="/calendario">{lucide("calendar")}<span>Calendario</span></a><button class="bottom-new" type="button" onclick="toggleCreateMenu()" aria-label="Crea">{lucide("plus")}</button><a href="/programma-cremazioni">{lucide("paw-soft")}<span>Cremazioni</span></a><button type="button" onclick="toggleMoreMenu()">{lucide("more-horizontal")}<span>Altro</span></button></nav><div class="create-sheet-backdrop" onclick="toggleCreateMenu(false)"></div><aside class="create-sheet" aria-label="Crea"><a href="/nuova">{lucide("plus")}<span>Nuova pratica</span></a><a href="/calendario/nuovo" data-calendar-new-event>{lucide("calendar")}<span>Nuovo evento</span></a><a href="/turni/pianifica">{lucide("clock")}<span>Nuovo turno</span></a></aside><div class="more-backdrop" onclick="toggleMoreMenu(false)"></div><aside class="more-menu" aria-label="Altre funzioni"><div class="more-title"><div><b>Menu</b><small>Tutto a portata di mano</small></div><div class="more-title-actions"><button class="more-edit-btn" type="button" onclick="toggleMoreMenuEdit()" aria-label="Riordina le voci del menu"><span class="more-edit-icon more-edit-icon-pencil">{lucide("pencil")}</span><span class="more-edit-icon more-edit-icon-check">{lucide("check")}</span><span class="more-edit-label">Modifica</span></button><button class="more-close-btn" onclick="toggleMoreMenu(false)" aria-label="Chiudi">×</button></div></div><form id="moreMenuOrderForm" data-drag-group action="/il-mio-profilo/salva" method="post"><input type="hidden" name="return_to" value="/il-mio-profilo"><input type="hidden" name="sidebar_order_json" data-drag-order value="{drawer_order_json}"><div class="more-card-list" data-drag-root>{drawer_links}</div></form><button class="btn ghost install-btn" type="button" onclick="installPetParadise()">Installa App</button></aside>'''
    vapid_public=esc(os.environ.get("VAPID_PUBLIC_KEY",""))
    return f'''<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#e9475b"><meta name="mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><meta name="apple-mobile-web-app-title" content="PP Manager"><meta name="application-name" content="Pet Paradise Manager"><meta name="format-detection" content="telephone=no"><link rel="manifest" href="/manifest.json"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="icon" type="image/png" sizes="32x32" href="/assets/favicon-32.png"><title>{esc(title)} - Pet Paradise Manager</title><style>{CSS}</style></head><body class="{body_class.strip()}"{body_attrs} data-vapid-public-key="{vapid_public}"><a class="skip-link" href="#main-content">Vai al contenuto</a><div class="ppm-pull-refresh" id="ppmPullRefresh" aria-hidden="true"><span class="ppm-pull-refresh-spinner"></span></div><aside class="top"><a class="brand" href="/"><img class="brand-logo brand-logo-dark" src="/assets/company_logo.png" alt="Pet Paradise"><img class="brand-logo brand-logo-light" src="/assets/company_logo_light.png" alt="Pet Paradise"><span class="brand-copy">Pet Paradise <small>MANAGER</small></span></a>{nav}</aside>{app_header}<div id="main-content">{body}</div>{mobile_nav}{APP_JS}</body></html>'''


class App(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        print(f"[{self.log_date_time_string()}] {fmt % args}")

    def send_html(self, content, status=200):
        data = content.encode("utf-8")
        self.send_response(status); self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(data))); self.end_headers(); self.wfile.write(data)

    def send_text(self, content, status=200):
        data = content.encode("utf-8")
        self.send_response(status); self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(data))); self.end_headers(); self.wfile.write(data)

    def send_json(self, obj, status=200):
        data = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(status); self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(data))); self.end_headers(); self.wfile.write(data)

    def send_png(self, path):
        data = path.read_bytes()
        self.send_response(200); self.send_header("Content-Type", "image/png")
        self.send_header("Content-Length", str(len(data))); self.end_headers(); self.wfile.write(data)

    def send_static(self,path,content_type,cache="public, max-age=86400"):
        data=path.read_bytes()
        self.send_response(200); self.send_header("Content-Type",content_type)
        self.send_header("Cache-Control",cache); self.send_header("Content-Length",str(len(data)))
        self.end_headers(); self.wfile.write(data)

    def service_worker(self):
        script=(ASSETS / "sw.js").read_text(encoding="utf-8").replace("__SW_VERSION__",APP_VERSION)
        data=script.encode("utf-8")
        self.send_response(200); self.send_header("Content-Type","application/javascript; charset=utf-8")
        self.send_header("Cache-Control","no-cache"); self.send_header("Content-Length",str(len(data)))
        self.end_headers(); self.wfile.write(data)

    def error_page(self, title, message, back="/"):
        body=f'''<main class="wrap"><section class="section"><h1>{esc(title)}</h1><p class="sub">{esc(message)}</p><div class="actions" style="margin-top:18px"><a class="btn" href="{esc(back)}">Torna indietro</a></div></section></main>'''
        self.send_html(layout(title,body,self.user()),500)

    def pdf_error_page(self, exc, back):
        print(traceback.format_exc())
        detail = f"{type(exc).__name__}: {exc}"
        asset_status = []
        for name in ("DCS_NUOVO.pdf", "DCS_LIVORNO.pdf", "DCS_EMPOLI.pdf"):
            path = ASSETS / name
            if path.exists():
                asset_status.append(f"{name}: OK ({path.stat().st_size} byte)")
            else:
                asset_status.append(f"{name}: MANCANTE")
        message = (
            f"Errore tecnico: {detail}\n"
            f"Cartella assets: {ASSETS}\n"
            f"Modelli: {' | '.join(asset_status)}\n"
            f"Cartella dati: {DATA}\n"
            f"Cartella DDT: {DDT_DIR}"
        )
        return self.error_page("PDF non generato", message, back)

    def redirect(self, path):
        self.send_response(303); self.send_header("Location", path); self.end_headers()

    def form(self):
        size = int(self.headers.get("Content-Length", 0))
        return {k: v[-1] for k, v in parse_qs(self.rfile.read(size).decode()).items()}

    def user(self):
        jar = cookies.SimpleCookie(self.headers.get("Cookie", "")); morsel = jar.get("ppm_session")
        if not morsel: return None
        with db() as c:
            return c.execute("SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND u.active=1", (morsel.value,)).fetchone()

    def require_user(self):
        user = self.user()
        if not user: self.redirect("/login")
        return user

    def handle_client_disconnect(self):
        """The client (browser) closed or lost the connection before the
        response could be written — e.g. the phone backgrounded the tab, or
        a slow mobile connection dropped mid-request. There is no client
        left to send anything to, so unlike handle_uncaught_error this must
        NOT attempt error_page/send_html: doing so just raises the exact
        same BrokenPipeError a second time while writing the error page
        itself, which used to escape uncaught and get logged as if it were
        a real bug. Log it quietly at low severity and stop — nothing more
        can or should be done for a connection that is already gone."""
        print(f"[CLIENT_DISCONNESSO] {getattr(self,'command','')} {self.path}",flush=True)

    def handle_uncaught_error(self,exc):
        """A route handler raised something that isn't already turned into a
        visible error page (BalanceError, sqlite3.Error, etc. are already
        caught closer to where they happen). Without this, do_GET/do_POST had
        no top-level exception handling at all: socketserver's default
        handle_error just prints the traceback and drops the connection with
        zero HTTP response — from the browser this looks exactly like
        "clicked the button, nothing happened, no error", which is very
        likely why some failures in this app have been so hard to pin down."""
        print(f"[UNCAUGHT] {getattr(self,'command','')} {self.path}\n{traceback.format_exc()}",flush=True)
        try:
            self.error_page(
                "Errore imprevisto",
                f"Si è verificato un errore tecnico e l'operazione non è stata completata "
                f"({type(exc).__name__}: {exc}). Riprova; se il problema persiste, segnala "
                f"questo messaggio così possiamo trovare la causa esatta nei log.",
            )
        except Exception:
            pass

    def do_GET(self):
        try:
            return self._route_get()
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            return self.handle_client_disconnect()
        except Exception as exc:
            return self.handle_uncaught_error(exc)

    def _route_get(self):
        path = urlparse(self.path).path
        if path == "/health": return self.send_text("ok")
        if path == "/cron/whatsapp": return self.whatsapp_cron()
        if path == "/webhook/whatsapp": return self.whatsapp_webhook_verify()
        if path == "/manifest.json": return self.send_static(ASSETS / "manifest.json","application/manifest+json; charset=utf-8", "no-cache")
        if path == "/sw.js": return self.service_worker()
        static_assets={
            "/assets/company_logo.png":"company_logo.png",
            "/assets/company_logo_light.png":"company_logo_light.png",
            "/assets/pwa-192.png":"pwa-192.png",
            "/assets/pwa-512.png":"pwa-512.png",
            "/assets/apple-touch-icon.png":"apple-touch-icon.png",
            "/assets/favicon-32.png":"favicon-32.png",
        }
        if path in static_assets and (ASSETS / static_assets[path]).exists(): return self.send_static(ASSETS / static_assets[path],"image/png")
        match = re.fullmatch(r"/pubblici/ddt/([A-Za-z0-9_-]+)\.pdf", path)
        if match: return self.public_ddt(match.group(1))
        if path == "/login": return self.login_page()
        if path == "/logout": return self.logout()
        user = self.require_user()
        if not user: return
        if user["must_change_password"] and path != "/imposta-password" and not path.startswith("/api/"):
            return self.redirect("/imposta-password")
        if path == "/imposta-password": return self.change_password_page(user)
        match = re.fullmatch(r"/uploads/urns/([A-Za-z0-9_.-]+)", path)
        if match:
            image=(DATA / "urn_images" / match.group(1)).resolve()
            root=(DATA / "urn_images").resolve()
            if not str(image).startswith(str(root)) or not image.exists(): return self.send_error(404)
            content_type={".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".webp":"image/webp"}.get(image.suffix.lower(),"application/octet-stream")
            return self.send_static(image,content_type)
        if path == "/": return self.dashboard(user)
        if path == "/calendario": return self.calendar_page(user)
        if path == "/turni": return self.shifts_page(user)
        if path == "/turni/pianifica": return self.shifts_plan_page(user)
        if path == "/turni/ferie": return self.shifts_vacations_page(user)
        if path == "/turni/reperibilita": return self.shifts_oncall_page(user)
        if path == "/bilanci": return self.balances_page(user)
        match = re.fullmatch(r"/bilanci/movimenti/(\d+)/elimina",path)
        if match: return self.confirm_balance_movement_delete(user,int(match.group(1)))
        if path == "/bilanci/movimenti/elimina-storico": return self.confirm_balance_legacy_movement_delete(user)
        if path == "/calendario/nuovo": return self.calendar_event_form(user)
        if path == "/calendario/impostazioni": return self.calendar_settings(user)
        if path == "/calendario/cestino": return self.calendar_trash(user)
        match = re.fullmatch(r"/calendario/(\d+)/modifica",path)
        if match: return self.calendar_event_form(user,int(match.group(1)))
        match = re.fullmatch(r"/calendario/(\d+)",path)
        if match: return self.calendar_event_detail(user,int(match.group(1)))
        if path == "/smaltimenti": return self.disposal_page(user)
        match = re.fullmatch(r"/smaltimenti/storico/(\d+)",path)
        if match: return self.disposal_batch_detail(user,int(match.group(1)))
        if path == "/programma-cremazioni": return self.cremation_schedule(user)
        if path == "/calendario/percorso-rapido": return self.calendar_route_quick(user)
        if path == "/percorso-giornaliero": return self.route_plan_page(user)
        if path == "/percorso-giornaliero/sedi": return self.route_locations_page(user)
        match = re.fullmatch(r"/percorso-giornaliero/(\d+)",path)
        if match: return self.route_plan_page(user,int(match.group(1)))
        match = re.fullmatch(r"/pagamenti/(da-saldare|acconti|pagati|totale-incassato)", path)
        if match: return self.payment_overview(user,match.group(1))
        if path == "/conversazioni-whatsapp": return self.whatsapp_conversations(user)
        if path == "/notifiche": return self.notifications(user)
        if path in ("/prodotti","/articoli"): return self.articles_page(user)
        if path == "/ordini": return self.orders_page(user)
        if path == "/ordini/storico": return self.orders_history_page(user)
        if path == "/ordini/impostazioni": return self.order_settings_page(user)
        match = re.fullmatch(r"/ordini/(\d+)", path)
        if match: return self.order_detail_page(user,int(match.group(1)))
        if path == "/fatture": return self.invoices_page(user)
        if path == "/catalogo-urne": return self.urn_catalog_page(user)
        if path == "/catalogo-urne/nuova": return self.urn_edit_page(user)
        if path in ("/diagnostica","/impostazioni"): return self.settings_page(user)
        if path == "/il-mio-profilo": return self.profile_page(user)
        if path == "/whatsapp-diagnostica": return self.whatsapp_diagnostics(user)
        if path == "/api/clienti/search": return self.api_clients_search(user)
        if path == "/api/cap": return self.api_zip_lookup(user)
        if path == "/api/geocode/indirizzo": return self.api_address_suggestions(user)
        if path == "/api/veterinari/search": return self.api_veterinarians_search(user)
        if path == "/api/calendario/animali/search": return self.api_calendar_animals_search(user)
        if path == "/api/calendario/pratiche/search": return self.api_calendar_practices_search(user)
        if path == "/api/programma-cremazioni/prossimo-slot": return self.api_cremation_next_slot(user)
        if path == "/api/notifiche/stato": return self.notification_status(user)
        match = re.fullmatch(r"/api/veterinari/(\d+)/buoni", path)
        if match: return self.api_veterinarian_vouchers(user, int(match.group(1)))
        if path == "/nuova": return self.new_page(user)
        if path == "/pratiche": return self.archive_home(user)
        if path == "/archivio/pratiche": return self.archive(user)
        if path == "/archivio/clienti": return self.clients_archive(user)
        if path == "/cestino": return self.trash_page(user)
        if path == "/database-mesi": return self.redirect("/pratiche")
        if path == "/veterinari": return self.veterinarians_page(user)
        if path == "/clienti": return self.clients_page(user)
        match = re.fullmatch(r"/clienti/(\d+)", path)
        if match: return self.client_detail(user, int(match.group(1)))
        if path == "/collaboratori": return self.collaborators_page(user)
        match = re.fullmatch(r"/collaboratori/(\d+)", path)
        if match: return self.collaborator_detail(user, int(match.group(1)))
        if path == "/api/collaboratori/search": return self.api_collaborators_search(user)
        match = re.fullmatch(r"/api/collaboratori/(\d+)/listino", path)
        if match: return self.api_collaborator_price_tiers(user, int(match.group(1)))
        match = re.fullmatch(r"/catalogo-urne/(\d+)/modifica", path)
        if match: return self.urn_edit_page(user, int(match.group(1)))
        match = re.fullmatch(r"/catalogo-urne/(\d+)", path)
        if match: return self.urn_detail_page(user, int(match.group(1)))
        match = re.fullmatch(r"/veterinari/(\d+)", path)
        if match: return self.veterinarian_detail(user, int(match.group(1)))
        match = re.fullmatch(r"/pratiche/(\d+)/diagnostica-pagamenti", path)
        if match: return self.practice_payment_diagnostics(user, int(match.group(1)))
        match = re.fullmatch(r"/pratiche/(\d+)", path)
        if match: return self.practice(user, int(match.group(1)))
        match = re.fullmatch(r"/notifiche/(\d+)/apri", path)
        if match: return self.open_notification(user, int(match.group(1)))
        match = re.fullmatch(r"/pratiche/(\d+)/modifica", path)
        if match: return self.edit_page(user, int(match.group(1)))
        match = re.fullmatch(r"/pratiche/(\d+)/elimina", path)
        if match: return self.delete_warning_page(user, int(match.group(1)))
        match = re.fullmatch(r"/pratiche/(\d+)/ddt\.pdf", path)
        if match: return self.download_ddt(user, int(match.group(1)))
