    def balance_expense_submit(self,user):
        form=self.form()
        return_to=safe_return_path(form.get("return_to"),"/bilanci")
        try:
            amount_cents=euros_to_cents(form.get("amount",""))
            if amount_cents<=0:raise BalanceError("L'importo deve essere maggiore di zero.")
            token=(form.get("balance_idempotency_key") or "").strip()
            if not token:raise BalanceError("Richiesta non valida: ricarica la pagina e riprova.")
            with db() as c:
                create_balance_expense(
                    c,
                    amount_cents=amount_cents,
                    movement_date=form.get("movement_date",""),
                    category=form.get("category",""),
                    description=form.get("description",""),
                    idempotency_key=f"manual-expense:{token}",
                    created_by=user["id"],
                )
        except BalanceError as exc:
            return self.balances_page(user,error=str(exc),expense_draft=form)
        separator="&" if "?" in return_to else "?"
        self.redirect(f"{return_to}{separator}uscita_creata=1")

    def balance_income_submit(self,user):
        form=self.form()
        return_to=safe_return_path(form.get("return_to"),"/bilanci")
        try:
            amount_cents=euros_to_cents(form.get("amount",""))
            if amount_cents<=0:
                raise BalanceError("L'importo deve essere maggiore di zero.")
            token=(form.get("balance_idempotency_key") or "").strip()
            if not token:
                raise BalanceError("Richiesta non valida: ricarica la pagina e riprova.")
            category=form.get("category","")
            collaborator_raw=form.get("collaborator_id","").strip()
            collaborator_id=(
                int(collaborator_raw)
                if collaborator_raw.isdigit() and int(collaborator_raw)>0 else None
            )
            description=form.get("description","").strip()
            notes=form.get("notes","").strip()
            full_description=description+(f" · {notes}" if notes else "")
            with db() as c:
                create_balance_income(
                    c,
                    amount_cents=amount_cents,
                    movement_date=form.get("movement_date",""),
                    category=category,
                    payment_method=form.get("payment_method",""),
                    description=full_description,
                    idempotency_key=f"manual-income:{token}",
                    collaborator_id=collaborator_id,
                    created_by=user["id"],
                )
        except BalanceError as exc:
            return self.balances_page(user,error=str(exc),expense_draft=form)
        separator="&" if "?" in return_to else "?"
        self.redirect(f"{return_to}{separator}entrata_creata=1")

    def confirm_balance_movement_delete(self,user,movement_id):
        query=parse_qs(urlparse(getattr(self,"path","")).query)
        value=lambda key,default="":(query.get(key) or [default])[-1].strip()
        return_to=safe_return_path(value("return_to"),"/bilanci")
        with db() as c:
            movement=c.execute("SELECT * FROM balance_movements WHERE id=?",(movement_id,)).fetchone()
        if not movement or movement["movement_type"] in ("Storno","Rettifica"):
            return self.balances_page(user,error="Movimento non trovato.")
        body=f'''<section class="section" style="max-width:520px;margin:0 auto">
          <h1>Eliminare il movimento?</h1>
          <p class="sub">Sei sicuro di voler eliminare questo movimento? L'operazione è definitiva e non reversibile.</p>
          <p class="sub">Il {esc(date_it(movement["movement_date"]))} · {esc(movement["movement_type"])} · {esc(movement["category"])} · <b>{money_cents_it(movement["amount_cents"])}</b>{f' · {esc(movement["description"])}' if movement["description"] else ""}</p>
          <div class="actions" style="display:flex;gap:10px;margin-top:20px">
            <form method="post" action="/bilanci/movimenti/{movement_id}/elimina-conferma"><input type="hidden" name="return_to" value="{esc(return_to)}"><button class="btn danger-btn" type="submit">Sì, elimina definitivamente</button></form>
            <a class="btn ghost" href="{esc(return_to)}">Annulla</a>
          </div>
        </section>'''
        return self.send_html(layout("Eliminare movimento",body,user))

    def confirm_balance_legacy_movement_delete(self,user):
        query=parse_qs(urlparse(getattr(self,"path","")).query)
        value=lambda key,default="":(query.get(key) or [default])[-1].strip()
        return_to=safe_return_path(value("return_to"),"/bilanci")
        legacy_key=value("legacy_key")
        with db() as c:
            practice_id=practice_id_for_legacy_key(c,legacy_key)
            filters=normalize_balance_filters(include_technical=True)
            movement=next(
                (m for m in get_balance_movements(c,filters=filters,restrict_practice_id=practice_id) if m.id<0 and m.idempotency_key==legacy_key),
                None,
            ) if practice_id else None
        if not movement:
            return self.balances_page(user,error="Movimento non trovato.")
        body=f'''<section class="section" style="max-width:520px;margin:0 auto">
          <h1>Eliminare il movimento?</h1>
          <p class="sub">Sei sicuro di voler eliminare questo movimento? L'operazione è definitiva e non reversibile.</p>
          <p class="sub">Il {esc(date_it(movement.movement_date))} · {esc(movement.movement_type)} · {esc(movement.category)} · <b>{money_cents_it(movement.amount_cents)}</b>{f' · {esc(movement.description)}' if movement.description else ""}</p>
          <div class="actions" style="display:flex;gap:10px;margin-top:20px">
            <form method="post" action="/bilanci/movimenti/elimina-conferma-storico"><input type="hidden" name="return_to" value="{esc(return_to)}"><input type="hidden" name="legacy_key" value="{esc(legacy_key)}"><button class="btn danger-btn" type="submit">Sì, elimina definitivamente</button></form>
            <a class="btn ghost" href="{esc(return_to)}">Annulla</a>
          </div>
        </section>'''
        return self.send_html(layout("Eliminare movimento",body,user))

    def delete_legacy_practice_column_movement(self,c,practice,kind,user_id):
        """Clear the raw practices columns that a 'historical-practice:<id>:
        deposit|balance' Bilanci row (a practice old enough to predate the
        payment_movements table entirely — its acconto/saldo only ever lived
        as plain columns on practices) was synthesized from.

        create_legacy_reversal on its own only appends an offsetting Storno
        to balance_movements, which hides the row from Bilanci's own ledger
        view — it never touches the practices row. Left alone, that means:
        the practice's own Riepilogo/Modifica dati keep showing the "deleted"
        acconto/saldo as if still registered (they read deposit/deposit_final/
        payment_status directly), and get_outstanding_balances (which falls
        back to those exact columns whenever a practice has zero
        balance_movements/payment_movements rows) keeps computing the
        deleted amount as still received — so Bilanci's own totals drift
        out of sync with what it just "deleted". This mirrors the same
        has_acconto/has_saldo recompute delete_practice_payment_movement
        already uses for the payment_movements-backed case, just reading
        the surviving side from raw columns instead of a payment_movements
        query, so both legacy vintages behave identically. Returns
        {"practice_before": {...}} for Bilanci's restore-deletion snapshot.
        """
        pid=practice["id"]
        valid_date=lambda value:bool(c.execute("SELECT date(?) AS d",(value,)).fetchone()["d"])
        snapshot={key:practice[key] for key in ("payment_status","deposit","deposit_final","deposit_paid_at","remaining_balance","remaining_final","paid_at")}
        has_acconto_before=channel_deposit(practice)>0 and valid_date(practice["deposit_paid_at"])
        has_saldo_before=(practice["payment_status"] or "")=="Pagato" and valid_date(practice["paid_at"])
        if kind=="deposit":
            has_acconto_after=False;has_saldo_after=has_saldo_before
        else:
            has_acconto_after=has_acconto_before;has_saldo_after=False
        new_status="Pagato" if has_saldo_after else ("Acconto" if has_acconto_after else "Da saldare")
        due=effective_total(practice)
        due_d=uses_total_d(practice)
        if kind=="deposit":
            deposit_paid_at=""
            deposit_final="" if due_d else practice["deposit_final"]
            deposit=practice["deposit"] if due_d else ""
        else:
            paid_at=""
            deposit_paid_at=practice["deposit_paid_at"];deposit=practice["deposit"];deposit_final=practice["deposit_final"]
        if kind=="deposit":
            paid_at=practice["paid_at"]
        deposit_amount=channel_deposit(practice) if has_acconto_after else 0.0
        remaining=max(0.0,due-deposit_amount)
        if new_status=="Pagato":
            remaining_balance="0.00";remaining_final="0.00" if due_d else ""
        elif due_d:
            remaining_balance=practice["remaining_balance"];remaining_final=f"{remaining:.2f}"
        else:
            remaining_balance=f"{remaining:.2f}";remaining_final=practice["remaining_final"]
        stamp=now()
        c.execute(
            "UPDATE practices SET payment_status=?,deposit=?,deposit_final=?,deposit_paid_at=?,remaining_balance=?,remaining_final=?,paid_at=?,updated_at=? WHERE id=?",
            (new_status,deposit,deposit_final,deposit_paid_at,remaining_balance,remaining_final,paid_at,stamp,pid),
        )
        old_status=snapshot["payment_status"] or "Da saldare"
        if old_status!=new_status:
            c.execute(
                "INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",
                (pid,"Pagamento",old_status,f"{new_status} · movimento storico eliminato",user_id,stamp),
            )
        return {"practice_before":snapshot}

    def delete_practice_payment_movement(self,c,pm,user_id):
        """Permanently delete one payment_movements row: drops its invoice
        link (and the invoice itself if nothing else references it), removes
        the row for real, then recomputes payment_status/deposit/
        remaining_balance/remaining_final on its practice from whatever
        payment_movements remain — same recompute already used when a
        macroarea payment is removed from the Pagamento popover. Returns a
        snapshot of everything removed/changed so the caller can log it for
        Bilanci's undo-delete panel."""
        pid=pm["practice_id"]
        practice=c.execute("SELECT * FROM practices WHERE id=?",(pid,)).fetchone()
        snapshot={
            "payment_movement":{key:pm[key] for key in pm.keys() if key!="id"},
            "invoice":None,"invoice_id":None,
            "practice_before":(
                {key:practice[key] for key in ("payment_status","deposit","deposit_final","remaining_balance","remaining_final")}
                if practice else None
            ),
        }
        invoice_link=c.execute("SELECT invoice_id FROM movement_invoice_links WHERE payment_movement_id=?",(pm["id"],)).fetchone()
        c.execute("DELETE FROM movement_invoice_links WHERE payment_movement_id=?",(pm["id"],))
        if invoice_link:
            remaining_links=c.execute("SELECT COUNT(*) n FROM movement_invoice_links WHERE invoice_id=?",(invoice_link["invoice_id"],)).fetchone()["n"]
            if remaining_links==0:
                invoice_row=c.execute("SELECT * FROM movement_invoices WHERE id=?",(invoice_link["invoice_id"],)).fetchone()
                if invoice_row:
                    snapshot["invoice"]={key:invoice_row[key] for key in invoice_row.keys() if key!="id"}
                c.execute("DELETE FROM movement_invoices WHERE id=?",(invoice_link["invoice_id"],))
            else:
                snapshot["invoice_id"]=invoice_link["invoice_id"]
        c.execute("DELETE FROM payment_movements WHERE id=?",(pm["id"],))
        if not practice:
            return snapshot
        old_status=practice["payment_status"] or "Da saldare"
        has_acconto=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
        has_saldo=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' LIMIT 1",(pid,)).fetchone())
        new_status="Pagato" if has_saldo else ("Acconto" if has_acconto else "Da saldare")
        deposit,remaining_balance,deposit_final,remaining_final=recompute_practice_channel_balances(c,pid,practice)
        stamp=now()
        c.execute(
            "UPDATE practices SET payment_status=?,deposit=?,remaining_balance=?,deposit_final=?,remaining_final=?,updated_at=? WHERE id=?",
            (new_status,deposit,remaining_balance,deposit_final,remaining_final,stamp,pid),
        )
        if old_status!=new_status:
            c.execute(
                "INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",
                (pid,"Pagamento",old_status,f"{new_status} · movimento eliminato",user_id,stamp),
            )
        return snapshot

    def balance_movement_delete(self,user,movement_id):
        """Permanently delete a real balance_movements row (a genuine SQL
        DELETE): if it originated from a practice's Pagamento popover, also
        hard-deletes the matching payment_movements row and its invoice, then
        recomputes the practice's payment status/totals from what remains."""
        return_to=safe_return_path(self.form().get("return_to"),"/bilanci")
        try:
            with db() as c:
                movement=c.execute("SELECT * FROM balance_movements WHERE id=?",(movement_id,)).fetchone()
                if not movement:
                    raise BalanceError("Movimento non trovato.")
                macroarea={"Acconto":"acconto","Saldo":"saldo","Incasso completo":"saldo"}.get(movement["movement_type"])
                pm_snapshot={}
                if movement["practice_id"] and macroarea:
                    pm=c.execute(
                        "SELECT * FROM payment_movements WHERE practice_id=? AND payment_type LIKE ? ORDER BY id DESC LIMIT 1",
                        (movement["practice_id"],f"{macroarea}%"),
                    ).fetchone()
                    if pm:
                        pm_snapshot=self.delete_practice_payment_movement(c,pm,user["id"]) or {}
                snapshot={"movement":{key:movement[key] for key in movement.keys() if key!="id"},**pm_snapshot}
                log_balance_movement_deletion(
                    c,movement_date=movement["movement_date"],category=movement["category"],
                    ledger_section=movement["ledger_section"],movement_type=movement["movement_type"],
                    amount_cents=movement["amount_cents"],payment_method=movement["payment_method"],
                    description=movement["description"],practice_id=movement["practice_id"],
                    practice_number_snapshot=movement["practice_number_snapshot"],deleted_by=user["id"],
                    deletion_kind="movement",snapshot=snapshot,
                )
                delete_balance_movement(c,movement_id=movement_id)
        except BalanceError as exc:
            return self.balances_page(user,error=str(exc))
        separator="&" if "?" in return_to else "?"
        self.redirect(f"{return_to}{separator}movimento_stornato=1")

    def balance_legacy_movement_delete(self,user):
        """Permanently delete a legacy row synthesized from payment_movements
        (or, for practices that predate that table, straight from the
        practices row). The row's own idempotency_key already fully
        identifies it; re-derive everything from get_movements() itself
        (never from the submitted form) so the delete can never be spoofed."""
        return_to=safe_return_path(self.form().get("return_to"),"/bilanci")
        legacy_key=self.form().get("legacy_key","").strip()
        try:
            with db() as c:
                practice_id=practice_id_for_legacy_key(c,legacy_key)
                filters=normalize_balance_filters(include_technical=True)
                movement=next(
                    (m for m in get_balance_movements(c,filters=filters,restrict_practice_id=practice_id) if m.id<0 and m.idempotency_key==legacy_key),
                    None,
                ) if practice_id else None
                if not movement:
                    raise BalanceError("Movimento non trovato.")
                if movement.id>-1000000000:
                    # backed by a real payment_movements row: its id is -movement.id
                    pm=c.execute("SELECT * FROM payment_movements WHERE id=?",(-movement.id,)).fetchone()
                    if not pm:
                        raise BalanceError("Movimento non trovato.")
                    snapshot=self.delete_practice_payment_movement(c,pm,user["id"]) or {}
                    deletion_kind="payment_movement"
                else:
                    # practice predates payment_movements entirely (its deposit/
                    # saldo is stored directly on the practices row, with no
                    # separate movement record to delete): the legacy-void
                    # reversal removes it from the ledger view and totals, but
                    # the raw practices columns it was synthesized from must
                    # also be cleared here — otherwise the practice's own
                    # pages and get_outstanding_balances keep treating the
                    # "deleted" amount as still received (it predates any
                    # payment_movements row, so there is nothing else to
                    # recompute the practice's state from).
                    kind=legacy_key.rsplit(":",1)[1] if legacy_key.startswith("historical-practice:") else None
                    practice_row=c.execute("SELECT * FROM practices WHERE id=?",(movement.practice_id,)).fetchone() if movement.practice_id else None
                    column_snapshot=(
                        self.delete_legacy_practice_column_movement(c,practice_row,kind,user["id"])
                        if practice_row and kind in ("deposit","balance") else {}
                    )
                    snapshot={"legacy_key":legacy_key,**column_snapshot}
                    deletion_kind="legacy_void"
                    create_balance_legacy_reversal(
                        c,
                        legacy_key=legacy_key,
                        amount_cents=movement.amount_cents,
                        category=movement.category,
                        ledger_section=movement.ledger_section,
                        movement_date=movement.movement_date,
                        practice_id=movement.practice_id,
                        practice_number_snapshot=movement.practice_number_snapshot,
                        payment_method=movement.payment_method,
                        description=f"Eliminazione manuale: {movement.description or movement.movement_type}",
                        source="manual_void",
                        created_by=user["id"],
                    )
                log_balance_movement_deletion(
                    c,movement_date=movement.movement_date,category=movement.category,
                    ledger_section=movement.ledger_section,movement_type=movement.movement_type,
                    amount_cents=movement.amount_cents,payment_method=movement.payment_method,
                    description=movement.description,practice_id=movement.practice_id,
                    practice_number_snapshot=movement.practice_number_snapshot,deleted_by=user["id"],
                    deletion_kind=deletion_kind,snapshot=snapshot,
                )
        except BalanceError as exc:
            return self.balances_page(user,error=str(exc))
        separator="&" if "?" in return_to else "?"
        self.redirect(f"{return_to}{separator}movimento_stornato=1")

    def balance_movement_deletion_restore(self,user,deletion_id):
        """Undo one entry from Bilanci's 'movimenti eliminati di recente'
        panel: puts the movement (and any linked payment_movements/invoice
        rows and practice payment columns) back exactly as they were before,
        via restore_movement_deletion's saved snapshot."""
        return_to=safe_return_path(self.form().get("return_to"),"/bilanci")
        separator="&" if "?" in return_to else "?"
        try:
            with db() as c:
                restore_balance_movement_deletion(c,deletion_id=deletion_id,restored_by=user["id"])
        except (MovementNotFoundError,InvalidMovementError) as exc:
            return self.balances_page(user,error=str(exc))
        self.redirect(f"{return_to}{separator}movimento_ripristinato=1")

    def calendar_operator_avatar(self,operator_name,size="md",color_hex=None):
        if not operator_name:return ''
        slug=CALENDAR_OPERATOR_SLUGS.get(operator_name,"other")
        initial=esc(operator_name.strip()[:1].upper())
        style=f' style="background:{esc(color_hex)}"' if color_hex else ''
        return f'<span class="calendar-avatar calendar-avatar-{size} calendar-avatar-{slug}"{style} title="{esc(operator_name)}">{initial}</span>'

    def calendar_event_base_form(self,event):
        """Dizionario equivalente ai campi del form del wizard, ricostruito
        dai valori gia' salvati su un evento esistente: permette alle
        modifiche rapide dal riepilogo di riusare integralmente
        normalize_event (stessa validazione del wizard) cambiando solo i
        campi che l'utente ha davvero toccato, senza duplicare la logica."""
        return {
            "event_type":event["event_type"],"title":event["title"] or "","zone":event["zone"] or "",
            "location_type":event["location_type"] or "","venue_name":event["venue_name"] or "",
            "address":event["address"] or "","phone":event["phone"] or "",
            "veterinarian_id":str(event["veterinarian_id"] or ""),"veterinarian_name":event["veterinarian_name"] or "",
            "veterinarian_phone":event["veterinarian_phone"] or "","veterinarian_address":event["veterinarian_address"] or "",
            "veterinarian_hours":event["veterinarian_hours"] or "","veterinarian_contact":event["veterinarian_contact"] or "",
            "client_id":str(event["client_id"] or ""),"client_first_name":event["client_first_name"] or "",
            "client_last_name":event["client_last_name"] or "","client_phone":event["client_phone"] or "",
            "destination_site":event["destination_site"] or "","animal_name":event["animal_name"] or "",
            "category":event["category"] or "","operator_name":event["operator_name"] or "",
            "event_status":event["event_status"] or "","payment_status":event["payment_status"] or "",
            "payment_amount":str(event["payment_amount"] or 0),"notes":event["notes"] or "",
            "delivery_clinic_id":str(event["delivery_clinic_id"] or ""),"delivery_clinic_name":event["delivery_clinic_name"] or "",
            "delivery_clinic_address":event["delivery_clinic_address"] or "","delivery_clinic_phone":event["delivery_clinic_phone"] or "",
            "all_day":"1" if event["all_day"] else "0",
            "start_date":(event["start_at"] or "")[:10],"start_time":(event["start_at"] or "")[11:16],
            "end_date":(event["end_at"] or "")[:10],"end_time":(event["end_at"] or "")[11:16],
        }

    def calendar_event_client_name(self,row,client_names=None,practice_owner_names=None):
        client_names=client_names or {};practice_owner_names=practice_owner_names or {}
        if row["client_id"] and client_names.get(row["client_id"]):return client_names[row["client_id"]]
        if row["linked_practice_id"] and practice_owner_names.get(row["linked_practice_id"]):return practice_owner_names[row["linked_practice_id"]]
        manual=" ".join(x for x in (row["client_first_name"],row["client_last_name"]) if x).strip()
        if manual:return manual
        if row["person_company"]:return row["person_company"]
        return ""

    def calendar_event_display_title(self,row):
        title=row["title"]
        if row["event_type"]=="Appuntamento":title=re.sub(r"^APPUNTAMENTO\b","PROMEMORIA",title,flags=re.I)
        return title

    def calendar_appointment_pending(self,row):
        if row["event_type"] in ("Ritiro","Ritiro in sede"):return row["event_status"] not in ("Ritirato","Annullato")
        if row["event_type"] in ("Riconsegna","Riconsegna in sede"):return row["event_status"]!="Completato"
        return False

    def calendar_appointment_done(self,row):
        if row["event_type"] in ("Ritiro","Ritiro in sede"):return row["event_status"]=="Ritirato"
        if row["event_type"] in ("Riconsegna","Riconsegna in sede"):return row["event_status"]=="Completato"
        return False

    def calendar_appointment_phone(self,row):
        return row["client_phone"] or row["phone"] or row["veterinarian_phone"] or row["delivery_clinic_phone"] or ""

    def calendar_appointment_address(self,row):
        return row["address"] or row["veterinarian_address"] or row["delivery_clinic_address"] or row["venue_name"] or ""

    def calendar_appointment_card(self,row,client_names=None,practice_owner_names=None,color_settings=None,animal_names_by_event=None,cremation_type_by_event=None):
        """Card ricca usata sia dalla vista Giorno sia dalla vista Settimana
        (stesso identico markup, per restare fedeli a quanto richiesto:
        'Le card devono essere praticamente identiche alla vista Giorno').
        Gerarchia delle informazioni (richiesta esplicita dell'utente): il
        titolo dell'evento e' l'informazione principale, l'animale (peso,
        tipo di cremazione, eventuale nome) e' secondario, poi il cliente
        (nome e telefono), poi il luogo — il nome del veterinario quando
        presente, non il suo indirizzo (quello si vede aprendo la card)."""
        color_settings=color_settings or DEFAULT_CALENDAR_COLOR_SETTINGS
        hex_=event_color_hex(row,color_settings)
        is_pickup=row["event_type"] in ("Ritiro","Ritiro in sede")
        is_delivery=row["event_type"] in ("Riconsegna","Riconsegna in sede")
        type_label="RITIRO" if is_pickup else ("RICONSEGNA" if is_delivery else "PROMEMORIA")
        type_cls="calendar-appt-type-pickup" if is_pickup else ("calendar-appt-type-delivery" if is_delivery else "calendar-appt-type-reminder")
        start=row["start_at"] or ""
        end_at=row["end_at"] or ""
        start_time_text=start[11:16] if start else ""
        end_time_text=end_at[11:16] if end_at else ""
        show_time_range=bool(not row["all_day"] and end_time_text and end_time_text!=start_time_text)
        time_text="Tutto il giorno" if row["all_day"] else start_time_text
        title_line=esc(self.calendar_event_display_title(row))
        names=(animal_names_by_event or {}).get(row["id"],"") or row["animal_name"] or ""
        cremation_types=(cremation_type_by_event or {}).get(row["id"],"")
        avatar_emoji="🐾"
        species_label=""
        if row.get("animal_species"):
            species_first=str(row["animal_species"]).split(",")[0].strip()
            species_lower=species_first.lower()
            avatar_emoji="🐶" if species_lower=="cane" else ("🐱" if species_lower=="gatto" else "🐾")
            species_label=species_first
        animal_bits=[]
        if species_label:animal_bits.append(species_label)
        if row["animal_weight_total"]:animal_bits.append(f'{float(row["animal_weight_total"]):g} kg')
        if cremation_types:animal_bits.append(cremation_types)
        if names:animal_bits.append(names)
        name_line=f'{avatar_emoji} {esc(" · ".join(animal_bits))}' if animal_bits else ''
        client_display=self.calendar_event_client_name(row,client_names,practice_owner_names)
        client_phone=row["client_phone"] or row["phone"] or ""
        client_line=f'{esc(client_display)}{" · "+esc(client_phone) if client_phone else ""}' if client_display else ''
        vet_label=row["veterinarian_name"] or row["delivery_clinic_name"] or ""
        location_line=esc(vet_label) if vet_label else esc(self.calendar_appointment_address(row))
        notes_text=re.sub(r"\s+"," ",str(row["notes"] or "")).strip()
        notes_preview=notes_text if len(notes_text)<=90 else notes_text[:89].rstrip()+"…"
        notes_line=f'{lucide("clipboard")}<span>{esc(notes_preview)}</span>' if notes_preview else ''
        payment_status_text=row["payment_status"] or ""
        if payment_status_text=="Pagato":
            payment_line=f'{lucide("check-circle")}<span>Pagato · {money_it(row["payment_amount"])}</span>'
        elif payment_status_text:
            channel=row.get("payment_channel") or ""
            payment_line=f'{lucide("wallet")}<span>{esc(payment_status_text)} · {money_it(row["payment_amount"])}{f" {esc(channel)}" if channel else ""}</span>'
        else:
            payment_line=''
        operator_name=row['operator_name'] or row['assigned_name'] or row['creator_name']
        avatar=self.calendar_operator_avatar(operator_name,"sm",color_settings["operators"].get(operator_name))
        status_text=row["event_status"] or ""
        status_html=f'<span class="calendar-appt-status" style="background:{hex_}22;color:{hex_}">{esc(status_text.upper())}</span>' if status_text else ''
        phone=self.calendar_appointment_phone(row)
        tel=re.sub(r"[^0-9+]","",phone) if phone else ""
        wa=self.wa_digits(phone) if phone else ""
        address=self.calendar_appointment_address(row)
        phone_btn=f'<a class="calendar-appt-action" href="tel:{esc(tel)}" aria-label="Chiama" onclick="event.stopPropagation()">{lucide("phone")}</a>' if tel else ''
        wa_btn=f'<a class="calendar-appt-action calendar-appt-action-wa" href="https://wa.me/{wa}" target="_blank" rel="noopener noreferrer" aria-label="WhatsApp" onclick="event.stopPropagation()">{lucide("message")}</a>' if wa else ''
        nav_btn=f'<a class="calendar-appt-action" href="https://www.google.com/maps/dir/?api=1&destination={quote(address)}" target="_blank" rel="noopener noreferrer" aria-label="Naviga" onclick="event.stopPropagation()">{lucide("navigation")}</a>' if address else ''
        menu_btn=f'''<div class="calendar-appt-menu-wrap" onclick="event.stopPropagation()">
          <button type="button" class="calendar-appt-action" aria-label="Altre azioni" onclick="calendarToggleApptMenu(this)">{lucide("more-vertical")}</button>
          <div class="calendar-appt-menu-popover" hidden>
            <a href="/calendario/{row['id']}">Apri dettaglio</a>
            <a href="/calendario/{row['id']}/modifica">Modifica</a>
            <form method="post" action="/calendario/{row['id']}/elimina" onsubmit="return confirm('Eliminare questo evento?')"><button type="submit">Elimina</button></form>
          </div>
        </div>'''
        filter_keys=["tutte"]
        filter_keys.append("ritiri" if is_pickup else ("riconsegne" if is_delivery else "promemoria"))
        if self.calendar_appointment_pending(row):filter_keys.append("pending")
        if self.calendar_appointment_done(row):filter_keys.append("done")
        if not row["assigned_user_id"]:filter_keys.append("unassigned")
        operator_attr=esc((operator_name or "").lower())
        return f'''<article class="calendar-appt-card" data-event-id="{row['id']}" data-filter="{esc(' '.join(filter_keys))}" data-operator="{operator_attr}" style="border-left-color:{hex_}" onclick="location.href='/calendario/{row['id']}'">
          <div class="calendar-appt-time-col"><span class="calendar-appt-time-dot" style="background:{hex_}"></span><span class="calendar-appt-time">{esc(time_text)}</span>{f'<span class="calendar-appt-time-end">→ {esc(end_time_text)}</span>' if show_time_range else ''}</div>
          <div class="calendar-appt-main">
            <div class="calendar-appt-top"><span class="calendar-appt-type {type_cls}">{type_label}</span>{avatar}</div>
            <div class="calendar-appt-title">{title_line}</div>
            {f'<div class="calendar-appt-name">{name_line}</div>' if name_line else ''}
            {f'<div class="calendar-appt-owner">{client_line}</div>' if client_line else ''}
            {f'<div class="calendar-appt-location">{location_line}</div>' if location_line else ''}
            {f'<div class="calendar-appt-payment">{payment_line}</div>' if payment_line else ''}
            {f'<div class="calendar-appt-notes">{notes_line}</div>' if notes_line else ''}
            <div class="calendar-appt-bottom">{status_html}<div class="calendar-appt-actions">{phone_btn}{wa_btn}{nav_btn}{menu_btn}</div></div>
          </div>
        </article>'''

    def calendar_legend_html(self,color_settings):
        legend_default_class={"Da confermare":"calendar-yellow","Da ritirare":"calendar-red","Ritirato":"calendar-green","Annullato":"calendar-dark","Riconsegna":"calendar-blue","Appuntamento":"calendar-purple"}
        legend_operator_items=''.join(f'<span class="calendar-legend-item">{self.calendar_operator_avatar(name,"xs",color_settings["operators"].get(name))}{esc(name)}</span>' for name in CALENDAR_OPERATORS)
        legend_status_items=''.join(f'<span class="calendar-legend-item"><span class="calendar-legend-dot {legend_default_class[key]}" style="color:{esc(color_settings["types"][key])}"></span>{esc(key)}</span>' for key in ("Da confermare","Da ritirare","Ritirato","Annullato"))
        legend_type_items=''.join(f'<span class="calendar-legend-item"><span class="calendar-legend-dot {legend_default_class[key]}" style="color:{esc(color_settings["types"][key])}"></span>{esc(key)}</span>' for key in ("Riconsegna","Appuntamento"))
        return f'<section class="calendar-legend-section"><div class="calendar-operator-legend">{legend_operator_items}</div><div class="calendar-day-legend"><div class="calendar-day-legend-group"><span class="calendar-day-legend-title">Colore = stato del ritiro</span>{legend_status_items}</div><div class="calendar-day-legend-group"><span class="calendar-day-legend-title">Colore fisso = altri tipi</span>{legend_type_items}</div></div></section>'

    def route_quick_body_html(self,selected):
        # Contenuto del popup "Parti subito": estratto in un metodo a se'
        # stante cosi' da poter essere sia renderizzato nella pagina
        # Calendario al primo caricamento, sia rigenerato via AJAX quando
        # l'utente cambia giorno nella daybar senza ricaricare la pagina
        # (calendarSelectDay/lo swipe sono puramente client-side: senza
        # questo endpoint "Percorso" restava ancorato al giorno con cui la
        # pagina era stata caricata, non a quello effettivamente visualizzato).
        with db() as c:
            route_locations=c.execute("SELECT * FROM company_locations WHERE active=1 ORDER BY name").fetchall()
            route_stops_today=route_eligible_events(c,selected)
        route_location_options=''.join(f'<option value="{loc["id"]}">{esc(loc["name"])}</option>' for loc in route_locations)
        def route_stop_label(row):
            time_label=row["start_at"][11:16] if len(row["start_at"] or "")>=16 else ""
            client=" ".join(x for x in (row["client_first_name"],row["client_last_name"]) if x).strip()
            who=row["animal_name"] or client or "Da definire"
            place=row["address"] or row["zone"] or ""
            place_html=f' <small>{esc(place)}</small>' if place else ""
            return f'<li><b>{esc(row["event_type"])}</b> {esc(time_label)} · {esc(who)}{place_html}</li>'
        has_route_stops=bool(route_stops_today)
        route_stops_summary_html=(
            f'<ul class="route-quick-stops">{"".join(route_stop_label(row) for row in route_stops_today)}</ul>'
            if has_route_stops else ""
        )
        return (
            f'''<p class="sub">Tappe di oggi ({len(route_stops_today)}): conferma per avviare il percorso.</p>
              {route_stops_summary_html}
              <form method="post" action="/percorso-giornaliero/calcola" id="routeQuickForm">
                <input type="hidden" name="quick" value="1">
                <input type="hidden" name="data" id="routeQuickDate" value="{selected}">
                <input type="hidden" name="start_lat" data-route-geoloc="start_lat"><input type="hidden" name="start_lng" data-route-geoloc="start_lng">
                <div class="route-quick-field">
                  <label>Punto di partenza</label>
                  <select name="start_location_type" onchange="routeToggleLocationFields(this,'start')">
                    <option value="sede">Sede aziendale</option>
                    <option value="attuale">Posizione attuale</option>
                  </select>
                </div>
                <select name="start_location_id" class="route-quick-field-select" data-route-field="start-sede">{route_location_options}</select>
                <button type="button" class="btn ghost route-quick-field-select" data-route-field="start-attuale" hidden onclick="routeRequestGeolocation('start',this.form)" style="width:100%">{lucide("navigation")} Usa posizione attuale</button>
                <div class="route-quick-field">
                  <label>Punto di arrivo</label>
                  <select name="end_location_type" onchange="routeToggleLocationFields(this,'end')">
                    <option value="stessa_partenza">Stessa sede di partenza</option>
                    <option value="sede">Altra sede</option>
                  </select>
                </div>
                <select name="end_location_id" class="route-quick-field-select" data-route-field="end-sede" hidden>{route_location_options}</select>
                <button class="btn" type="submit" style="width:100%;margin-top:4px">{lucide("check")} Conferma tappe e avvia percorso</button>
              </form>'''
            if has_route_stops else
            f'''<div class="flash warning">Non ci sono eventi programmati fuori sede per il {esc(date_it(selected))}. Il percorso serve solo per organizzare le tappe quando si esce dalla sede: con soli eventi in sede (o nessun evento) non serve impostarne uno.</div>
              <button type="button" class="btn ghost" style="width:100%;margin-top:12px" onclick="routeCloseQuickPopup()">Chiudi</button>'''
        )

    def calendar_route_quick(self,user):
        q=parse_qs(urlparse(self.path).query)
        selected=(q.get("data") or [rome_now().date().isoformat()])[0]
        try:date.fromisoformat(selected)
        except ValueError:selected=rome_now().date().isoformat()
        return self.send_json({"ok":True,"html":self.route_quick_body_html(selected)})

    def calendar_page(self,user):
        q=parse_qs(urlparse(self.path).query);selected=(q.get("data") or [rome_now().date().isoformat()])[0]
        route_error=(q.get("percorso_errore") or [""])[0]
        route_error_html=f'<div class="flash warning">{esc(route_error)}</div>' if route_error else ''
        try:date.fromisoformat(selected)
        except ValueError:selected=rome_now().date().isoformat()
        view=(q.get("vista") or ["giorno"])[0]
        if view not in ("giorno","settimana","mese","mista_settimana","mista_mese","compatto"):view="giorno"
        back_view=(q.get("da") or [""])[0]
        if back_view not in ("mese","settimana"):back_view=""
        selected_date=date.fromisoformat(selected)
        if view in ("giorno","settimana","mista_settimana"):
            # La vista Giorno mostra comunque la barra dei 7 giorni della settimana
            # corrente (stesso stile della vista Settimana): serve quindi
            # l'intervallo dati dell'intera settimana anche in vista Giorno.
            start=selected_date-timedelta(days=selected_date.weekday());end=start+timedelta(days=6)
        else:
            start,end=calendar_period_bounds(view,selected)
        filters={key:(q.get(key) or [""])[0] for key in ("q","event_type","event_status","operator_name","veterinarian_id","location_type","zone","venue_scope","date_from","date_to")}
        with db() as c:
            rows=overlap_rows(c,start.isoformat(),end.isoformat(),filters)
            event_ids=[row["id"] for row in rows]
            species_by_event={};animal_names_by_event={};cremation_type_by_event={}
            if event_ids:
                placeholders=','.join('?' for _ in event_ids)
                for species_row in c.execute(f"SELECT event_id,group_concat(DISTINCT species) species FROM calendar_event_animals WHERE event_id IN ({placeholders}) AND trim(COALESCE(species,''))<>'' GROUP BY event_id",event_ids):
                    species_by_event[species_row["event_id"]]=species_row["species"] or ""
                for name_row in c.execute(f"SELECT event_id,group_concat(name,', ') names FROM calendar_event_animals WHERE event_id IN ({placeholders}) AND trim(COALESCE(name,''))<>'' GROUP BY event_id",event_ids):
                    animal_names_by_event[name_row["event_id"]]=name_row["names"] or ""
                for ctype_row in c.execute(f"SELECT event_id,group_concat(DISTINCT cremation_type) ctypes FROM calendar_event_animals WHERE event_id IN ({placeholders}) AND trim(COALESCE(cremation_type,''))<>'' GROUP BY event_id",event_ids):
                    cremation_type_by_event[ctype_row["event_id"]]=ctype_row["ctypes"] or ""
            linked_ids={int(row["linked_practice_id"]) for row in rows if row["linked_practice_id"]}
            payment_channels={};practice_owner_names={}
            if linked_ids:
                linked_marks=','.join('?' for _ in linked_ids)
                for practice_row in c.execute(f"SELECT id,total_text,owner_first_name,owner_last_name,owner_company FROM practices WHERE id IN ({linked_marks})",tuple(linked_ids)):
                    payment_channels[practice_row["id"]]=payment_channel(practice_row)
                    owner=" ".join(x for x in (practice_row["owner_first_name"],practice_row["owner_last_name"]) if x).strip() or practice_row["owner_company"] or ""
                    if owner:practice_owner_names[practice_row["id"]]=owner
            client_ids={int(row["client_id"]) for row in rows if row["client_id"]}
            client_names={}
            if client_ids:
                client_marks=','.join('?' for _ in client_ids)
                for client_row in c.execute(f"SELECT id,first_name,last_name,company_name FROM clients WHERE id IN ({client_marks})",tuple(client_ids)):
                    name=" ".join(x for x in (client_row["first_name"],client_row["last_name"]) if x).strip() or client_row["company_name"] or ""
                    if name:client_names[client_row["id"]]=name
            rows=[dict(row,animal_species=species_by_event.get(row["id"],""),payment_channel=payment_channels.get(row["linked_practice_id"],"")) for row in rows]
            vets=c.execute("SELECT id,COALESCE(short_name,clinic_name) name FROM veterinarians WHERE active=1 ORDER BY name").fetchall()
            color_settings=calendar_color_settings(c)
        by_day={}
        for row in rows:
            cursor=max(start,date.fromisoformat(row["start_at"][:10]));last=min(end,date.fromisoformat(row["end_at"][:10]))
            while cursor<=last:by_day.setdefault(cursor.isoformat(),[]).append(row);cursor+=timedelta(days=1)
        today_date=rome_now().date()
        month_names=("Gennaio","Febbraio","Marzo","Aprile","Maggio","Giugno","Luglio","Agosto","Settembre","Ottobre","Novembre","Dicembre")
        day_names=("Lun","Mar","Mer","Gio","Ven","Sab","Dom")
        day_names_full=("Lunedì","Martedì","Mercoledì","Giovedì","Venerdì","Sabato","Domenica")
        def italian_long_date(value):return f"{day_names_full[value.weekday()]} {value.day} {month_names[value.month-1]}"
        if view=="giorno":
            prev_target,next_target=selected_date-timedelta(days=1),selected_date+timedelta(days=1)
        elif view in ("settimana","mista_settimana"):
            prev_target,next_target=selected_date-timedelta(days=7),selected_date+timedelta(days=7)
        else:
            previous_month_last=selected_date.replace(day=1)-timedelta(days=1)
            next_month_first=(selected_date.replace(day=28)+timedelta(days=4)).replace(day=1)
            prev_target=previous_month_last.replace(day=min(selected_date.day,previous_month_last.day))
            next_month_last=(next_month_first.replace(day=28)+timedelta(days=4)).replace(day=1)-timedelta(days=1)
            next_target=next_month_first.replace(day=min(selected_date.day,next_month_last.day))
        def view_url(target,current_view=view):
            params={"vista":current_view,"data":target.isoformat(),**{k:v for k,v in filters.items() if v}}
            return "/calendario?"+urlencode(params)
        switch_active={"mista_settimana":"settimana","mista_mese":"mese","compatto":"mese"}.get(view,view)
        switch=''.join(f'<a data-calendar-view="{key}" class="{"active" if switch_active==key else ""}" href="{view_url(selected_date,key)}">{label}</a>' for key,label in (("giorno","Giorno"),("settimana","Settimana"),("mese","Mese")))
        selected_rows=by_day.get(selected,[])
        def week_day_sort_key(row):return (0 if row["all_day"] else 1,row["start_at"] or "")
        week_days=[start+timedelta(days=i) for i in range(7)]
        selected_index=next((i for i,d in enumerate(week_days) if d.isoformat()==selected),0)
        # Calendario condiviso: tutti gli utenti (admin e non) vedono di
        # default gli eventi inseriti da chiunque, con l'avatar dell'operatore
        # su ogni card a indicare chi l'ha in carico. La tendina Incaricato
        # resta disponibile per tutti come filtro manuale opzionale, non piu'
        # precompilata forzatamente col nome dell'utente loggato.
        operator_filter_html=f'''<select class="calendar-filter-operator" onchange="calendarApplyFilters()" aria-label="Filtra per incaricato">
            <option value="">Incaricato</option>{''.join(f'<option value="{esc(name.lower())}">{esc(name)}</option>' for name in CALENDAR_OPERATORS)}
          </select>'''
        filter_pills_html=f'''<div class="calendar-appt-filters">
          <button type="button" class="calendar-filter-pill active" data-filter-value="tutte" onclick="calendarSetFilter(this)">Tutti</button>
          <button type="button" class="calendar-filter-pill" data-filter-value="ritiri" onclick="calendarSetFilter(this)">Ritiri</button>
          <button type="button" class="calendar-filter-pill" data-filter-value="riconsegne" onclick="calendarSetFilter(this)">Riconsegne</button>
          {operator_filter_html}
        </div>'''
        daybar_cards=[];day_pages=[]
        # Sentinelle invisibili prima/dopo i 7 giorni della settimana: senza
        # queste lo swipe si fermava semplicemente al bordo (lunedi'/domenica)
        # senza fare nulla, perche' non esisteva una pagina successiva su cui
        # "agganciarsi" (bug segnalato dall'utente in vista Settimana, ma
        # identico anche in vista Giorno essendo lo stesso carosello). Stessa
        # tecnica gia' usata per il carosello mesi di Turni: la sentinella
        # occupa uno slot dello scroll-snap e, quando lo swipe si ferma su
        # di essa, ricarica la pagina sul giorno adiacente (che sposta anche
        # la finestra "start..end" della settimana visualizzata).
        day_pages.append(f'<div class="calendar-day-page calendar-day-page-edge" data-href="{view_url(start-timedelta(days=1),view)}"></div>')
        for i,day in enumerate(week_days):
            day_rows=by_day.get(day.isoformat(),[])
            active_cls=" active" if day.isoformat()==selected else ""
            today_cls=" is-today" if day==today_date else ""
            count=len(day_rows)
            daybar_cards.append(f'''<button type="button" class="calendar-daybar-card{active_cls}{today_cls}" data-day-index="{i}" data-date="{day.isoformat()}" onclick="calendarSelectDay({i})">
              <span class="calendar-daybar-dow">{day_names[i].upper()}</span>
              <span class="calendar-daybar-num">{day.day:02d}</span>
              <span class="calendar-daybar-count">{count} app.</span>
            </button>''')
            pending=sum(1 for r in day_rows if self.calendar_appointment_pending(r))
            done=sum(1 for r in day_rows if self.calendar_appointment_done(r))
            stats_html=f'''<div class="calendar-appt-stats calendar-appt-stats-2col">
              <div class="calendar-appt-stat calendar-appt-stat-pending"><span class="calendar-appt-stat-icon">{lucide("clock")}</span><b>{pending}</b><small>Da effettuare</small></div>
              <div class="calendar-appt-stat calendar-appt-stat-done"><span class="calendar-appt-stat-icon">{lucide("check-circle")}</span><b>{done}</b><small>Completati</small></div>
            </div>'''
            sorted_rows=sorted(day_rows,key=week_day_sort_key)
            list_html=''.join(self.calendar_appointment_card(row,client_names=client_names,practice_owner_names=practice_owner_names,color_settings=color_settings,animal_names_by_event=animal_names_by_event,cremation_type_by_event=cremation_type_by_event) for row in sorted_rows) or '<p class="calendar-appt-empty">Nessun appuntamento in programma.</p>'
            day_pages.append(f'''<div class="calendar-day-page" data-day-index="{i}" data-date="{day.isoformat()}">
              {stats_html}
              <div class="calendar-appt-list">{list_html}</div>
              <a class="calendar-add-appt-btn" href="/calendario/nuovo?data={day.isoformat()}">{lucide("plus")}<span>Aggiungi ritiro / riconsegna</span></a>
            </div>''')
        day_pages.append(f'<div class="calendar-day-page calendar-day-page-edge" data-href="{view_url(start+timedelta(days=7),view)}"></div>')
        daybar_html=f'''<div id="calendarDayboard">
          <div class="calendar-daybar-wrap">
            <button type="button" class="calendar-daybar-nav" onclick="calendarDaybarNav(-1)" aria-label="Barra giorni precedente">‹</button>
            <div class="calendar-daybar" id="calendarDaybar">{''.join(daybar_cards)}</div>
            <button type="button" class="calendar-daybar-nav" onclick="calendarDaybarNav(1)" aria-label="Barra giorni successiva">›</button>
          </div>
          <div class="calendar-route-edge-row"><button type="button" class="route-fab-edge" aria-label="Percorso giornaliero" title="Percorso giornaliero" onclick="routeOpenSheet('{selected}')">{lucide("truck")}<span>Percorso</span></button></div>
          {filter_pills_html}
          <div class="calendar-day-pages" id="calendarDayPages" data-initial-day-index="{selected_index}">{''.join(day_pages)}</div>
        </div>'''
        day_view=daybar_html
        week_view=daybar_html
        month_start=start;offset=month_start.weekday();grid_start=month_start-timedelta(days=offset);month_days=[grid_start+timedelta(days=i) for i in range(42)]
        def month_cell(day):
            day_rows=by_day.get(day.isoformat(),[])
            pickups=sum(1 for r in day_rows if r["event_type"] in ("Ritiro","Ritiro in sede"))
            deliveries=sum(1 for r in day_rows if r["event_type"] in ("Riconsegna","Riconsegna in sede"))
            counts_html=''.join([
                f'<span class="calendar-month-v2-count calendar-month-v2-count-pickup">{pickups}</span>' if pickups else '',
                f'<span class="calendar-month-v2-count calendar-month-v2-count-delivery">{deliveries}</span>' if deliveries else '',
            ])
            classes=['calendar-month-v2-cell']
            if day==today_date:classes.append('is-today')
            if day.month!=selected_date.month:classes.append('is-other-month')
            is_selected=day.isoformat()==selected
            if is_selected:classes.append('selected')
            # First click on a day selects it (stays in month view, updates the summary
            # card below and shows the red outline); a second click -- now that the
            # day is already selected -- opens its Day view.
            cell_href=f"{view_url(day,'giorno')}&da=mese" if is_selected else view_url(day,'mese')
            return f'<a class="{" ".join(classes)}" href="{cell_href}"><span class="calendar-month-v2-num">{day.day}</span><div class="calendar-month-v2-counts">{counts_html}</div></a>'
        month_dow_header=''.join(f'<div class="calendar-month-v2-dow">{name}</div>' for name in day_names)
        month_legend='<div class="calendar-month-v2-legend"><span><span class="calendar-month-v2-count calendar-month-v2-count-pickup"></span>Ritiri</span><span><span class="calendar-month-v2-count calendar-month-v2-count-delivery"></span>Riconsegne</span></div>'
        month_grid=f'<section class="calendar-month-v2"><div class="calendar-month-v2-dow-row">{month_dow_header}</div><div class="calendar-month-v2-grid">'+''.join(month_cell(day) for day in month_days)+f'</div>{month_legend}</section>'
        month_pickups=sum(1 for r in selected_rows if r["event_type"] in ("Ritiro","Ritiro in sede"))
        month_deliveries=sum(1 for r in selected_rows if r["event_type"] in ("Riconsegna","Riconsegna in sede"))
        month_done=sum(1 for r in selected_rows if self.calendar_appointment_done(r))
        month_unassigned=sum(1 for r in selected_rows if not r["assigned_user_id"])
        month_view=f'''<div class="calendar-month-composition">{month_grid}
          <section class="calendar-month-daycard">
            <header><h2>{italian_long_date(selected_date)}</h2><span class="badge">{len(selected_rows)} appuntamenti</span></header>
            <div class="calendar-appt-stats">
              <div class="calendar-appt-stat calendar-appt-stat-pickup"><b>{month_pickups}</b><small>Ritiri</small></div>
              <div class="calendar-appt-stat calendar-appt-stat-delivery"><b>{month_deliveries}</b><small>Riconsegne</small></div>
              <div class="calendar-appt-stat calendar-appt-stat-done"><b>{month_done}</b><small>Completati</small></div>
              <div class="calendar-appt-stat calendar-appt-stat-unassigned"><b>{month_unassigned}</b><small>Senza incaricato</small></div>
            </div>
            <div class="calendar-month-daycard-actions">
              <a class="btn ghost calendar-month-new-btn" href="/calendario/nuovo?data={selected_date.isoformat()}">{lucide("plus")}<span>Nuovo evento</span></a>
              <a class="btn calendar-month-detail-btn" href="{view_url(selected_date,'giorno')}&da=mese">Vai al dettaglio del giorno {lucide("chevron-right")}</a>
            </div>
          </section>
        </div>'''
        if view=="giorno":content=day_view
        elif view=="settimana":content=week_view
        elif view in ("mese","compatto"):content=month_view
        elif view=="mista_settimana":content=day_view
        else:content=f'<div class="calendar-mixed"><div>{month_view}</div><div><h2>Eventi del {selected_date.strftime("%d/%m/%Y")}</h2>{day_view}</div></div>'
        type_options='<option value="">Tutti i tipi</option>'+''.join(f'<option value="{x}" {"selected" if filters["event_type"]==x else ""}>{"Promemoria" if x=="Appuntamento" else x}</option>' for x in EVENT_TYPES)
        status_options='<option value="">Tutti gli stati dei ritiri</option>'+''.join(f'<option {"selected" if filters["event_status"]==x else ""}>{x}</option>' for x in PICKUP_STATUSES)
        operator_options='<option value="">Tutti gli operatori</option>'+''.join(f'<option {"selected" if filters["operator_name"]==name else ""}>{name}</option>' for name in CALENDAR_OPERATORS)
        vet_options='<option value="">Tutti i veterinari</option>'+''.join(f'<option value="{row["id"]}" {"selected" if filters["veterinarian_id"]==str(row["id"]) else ""}>{esc(row["name"])}</option>' for row in vets)
        filters_html=f'''<details class="advanced-search"><summary>Ricerca e filtri</summary><form class="section advanced-search-form" method="get"><input type="hidden" name="vista" value="{view}"><input type="hidden" name="data" value="{selected}"><div class="fields"><div class="field full"><label>Parole chiave</label><input name="q" value="{esc(filters['q'])}" placeholder="Titolo, animale, cliente, veterinario, luogo, note"></div><div class="field"><label>Tipo</label><select name="event_type">{type_options}</select></div><div class="field"><label>Stato</label><select name="event_status">{status_options}</select></div><div class="field"><label>Operatore</label><select name="operator_name">{operator_options}</select></div><div class="field"><label>Veterinario</label><select name="veterinarian_id">{vet_options}</select></div><div class="field"><label>Luogo</label><select name="location_type"><option value="">Tutti</option>{''.join(f'<option {"selected" if filters["location_type"]==x else ""}>{x}</option>' for x in ("Veterinario","Privato","Sede Livorno","Sede Empoli","Altro indirizzo"))}</select></div><div class="field"><label>Zona</label><input name="zone" value="{esc(filters['zone'])}"></div><div class="field"><label>Sede o fuori sede</label><select name="venue_scope"><option value="">Tutti</option><option value="sede" {"selected" if filters["venue_scope"]=="sede" else ""}>In sede</option><option value="fuori" {"selected" if filters["venue_scope"]=="fuori" else ""}>Fuori sede</option></select></div><div class="field"><label>Dal</label><input type="date" name="date_from" value="{esc(filters['date_from'])}"></div><div class="field"><label>Al</label><input type="date" name="date_to" value="{esc(filters['date_to'])}"></div></div><button class="btn" style="margin-top:12px">Applica</button></form></details>'''
        preference_script=f'''<script>(function(){{const url=new URL(location.href);const saved=localStorage.getItem('ppm_calendar_view');const allowed=['giorno','settimana','mese','mista_settimana','mista_mese','compatto'];if(!url.searchParams.has('vista')&&allowed.includes(saved)&&saved!=='giorno'){{url.searchParams.set('vista',saved);location.replace(url);}}}})();</script>'''
        if view in ("settimana","mista_settimana"):
            if start.month==end.month:date_title=f"{start.day} – {end.day} {month_names[end.month-1]} {end.year}"
            elif start.year==end.year:date_title=f"{start.day} {month_names[start.month-1]} – {end.day} {month_names[end.month-1]} {end.year}"
            else:date_title=f"{start.day} {month_names[start.month-1]} {start.year} – {end.day} {month_names[end.month-1]} {end.year}"
        elif view in ("mese","mista_mese","compatto"):date_title=f"{month_names[selected_date.month-1]} {selected_date.year}"
        else:date_title=f"{selected_date.day} {month_names[selected_date.month-1]} {selected_date.year}"
        back_button=f'<a class="btn ghost calendar-back-btn" href="{view_url(selected_date,back_view)}">← Torna a {"Mese" if back_view=="mese" else "Settimana"}</a>' if view=="giorno" and back_view else ''
        # richiesta esplicita dell'utente: prima di avviare un percorso
        # mostrare un riepilogo delle tappe del giorno visualizzato e
        # chiedere conferma; se quel giorno ha solo eventi "in sede"
        # (route_eligible_events li esclude gia' a monte, per definizione
        # non richiedono uno spostamento fisico) non ha senso impostare un
        # percorso, quindi si avvisa invece di proporre un percorso vuoto.
        # Il contenuto e' anche rigenerabile via AJAX (routeRefreshQuickBody
        # in APP_JS, endpoint /calendario/percorso-rapido) perche' il giorno
        # mostrato nella daybar puo' cambiare via swipe/tap senza ricaricare
        # la pagina: senza il refresh, "Parti subito" restava ancorato al
        # giorno con cui la pagina era stata caricata inizialmente.
        route_quick_body=self.route_quick_body_html(selected)
        route_sheet_html=f'''<div class="route-sheet-backdrop" onclick="routeCloseSheet()"></div>
          <aside class="route-sheet" aria-label="Percorso giornaliero" role="dialog" aria-modal="true">
            <div class="route-sheet-handle"></div>
            <h2 class="route-sheet-title">Percorso giornaliero</h2>
            <button type="button" class="route-sheet-item" onclick="routeOpenQuickPopup()">
              <span class="route-sheet-item-icon route-sheet-item-icon-red">{lucide("play")}</span>
              <span class="route-sheet-item-copy"><b>Parti subito</b><small>Avvia rapidamente il percorso</small></span>
            </button>
            <a class="route-sheet-item" id="routeSettingsLink" href="/percorso-giornaliero?data={selected}">
              <span class="route-sheet-item-icon route-sheet-item-icon-gray">{lucide("settings")}</span>
              <span class="route-sheet-item-copy"><b>Impostazioni percorso</b><small>Personalizza percorso e ordine delle tappe</small></span>
            </a>
          </aside>
          <div class="route-quick-backdrop" onclick="if(event.target===this)routeCloseQuickPopup()">
            <aside class="route-quick-popup" aria-label="Parti subito" role="dialog" aria-modal="true">
              <div class="route-quick-head"><h2>Parti subito</h2><button type="button" class="icon-btn" onclick="routeCloseQuickPopup()" aria-label="Chiudi">{lucide("x")}</button></div>
              <div id="routeQuickBody">{route_quick_body}</div>
            </aside>
          </div>'''
        body=f'''<main class="wrap calendar-wrap">{route_error_html}<div class="titlebar calendar-main-title"><div>{back_button}<h1>Calendario operativo</h1><p class="sub">Ritiri, riconsegne e promemoria</p></div><div class="calendar-quick-actions"><a class="icon-btn" href="/calendario/cestino" aria-label="Cestino" title="Cestino">{lucide("trash-2")}</a><a class="icon-btn calendar-settings-link" href="/calendario/impostazioni" aria-label="Impostazioni" title="Impostazioni">{lucide("settings")}</a></div></div><div id="calendarDraftsBanner" hidden></div><nav class="calendar-date-nav"><a class="btn ghost" data-calendar-prev href="{view_url(prev_target)}" aria-label="Periodo precedente">←</a><label class="calendar-date-title"><span>{date_title}</span><input type="date" value="{selected}" onchange="const u=new URL(location.href);u.searchParams.set('data',this.value);location.href=u"></label><a class="btn ghost" data-calendar-next href="{view_url(next_target)}" aria-label="Periodo successivo">→</a><a class="btn ghost calendar-today" href="{view_url(rome_now().date())}">OGGI</a></nav><div class="calendar-toolbar"><nav class="calendar-view-switch">{switch}</nav></div>{content}{filters_html}{preference_script}{route_sheet_html}</main>'''
        self.send_html(layout("Calendario operativo",body,user))

    def calendar_settings(self,user):
        choices=''.join(f'''<label class="calendar-type-option"><input type="radio" name="calendar_view" value="{key}"><span><b>{label}</b></span></label>''' for key,label in (("giorno","Giorno"),("settimana","Settimana"),("mese","Mese"),("mista_settimana","Mista Giorno + Settimana"),("mista_mese","Mista Mese + Elenco"),("compatto","Mese compatto")))
        with db() as c:legend_color_settings=calendar_color_settings(c)
        legend_section=f'<div style="height:14px"></div><section class="section"><h2>Legenda colori</h2><p class="sub">Significato dei colori usati nel calendario, per operatore e per stato/tipo evento.</p>{self.calendar_legend_html(legend_color_settings)}</section>'
        colors_section=''
        if user["role"]=="admin":
            color_settings=legend_color_settings
            def swatch_row(field_name,current_hex):
                return ''.join(f'<label class="calendar-color-swatch{" is-selected" if hexval==current_hex else ""}" style="background:{hexval}"><input type="radio" name="{field_name}" value="{hexval}" {"checked" if hexval==current_hex else ""}></label>' for hexval in CALENDAR_COLOR_PALETTE)
            operator_rows=''.join(f'<div class="calendar-color-row"><span class="calendar-color-row-label">{esc(name)}</span><div class="calendar-color-swatches">{swatch_row(f"operator_{name}",color_settings["operators"][name])}</div></div>' for name in CALENDAR_OPERATORS)
            type_rows=''.join(f'<div class="calendar-color-row"><span class="calendar-color-row-label">{esc(key)}</span><div class="calendar-color-swatches">{swatch_row(f"type_{key.replace(chr(32),chr(95))}",color_settings["types"][key])}</div></div>' for key in DEFAULT_CALENDAR_TYPE_COLORS)
            colors_section=f'''<div style="height:14px"></div><section class="section"><h2>Colori Calendario</h2><p class="sub">Personalizza i colori assegnati agli operatori e ai tipi/stati evento nel calendario.</p><form method="post" action="/calendario/impostazioni"><h3>Operatori</h3>{operator_rows}<h3>Stato / tipo evento</h3>{type_rows}<button class="btn" style="margin-top:16px">Salva colori</button></form></section>'''
        body=f'''<main class="wrap calendar-form"><div class="titlebar"><div><h1>Impostazioni Calendario</h1><p class="sub">Scegli la visualizzazione predefinita su questo dispositivo.</p></div><a class="btn ghost" href="/calendario">×</a></div><form class="section" onsubmit="event.preventDefault();localStorage.setItem('ppm_calendar_view',this.calendar_view.value);location.href='/calendario?vista='+encodeURIComponent(this.calendar_view.value)"><div class="calendar-type-grid">{choices}</div><button class="btn" style="margin-top:16px">Salva preferenza</button></form>{legend_section}{colors_section}<script>document.addEventListener('DOMContentLoaded',()=>{{const saved=localStorage.getItem('ppm_calendar_view')||'giorno';const choice=document.querySelector('[name=calendar_view][value="'+saved+'"]');if(choice)choice.checked=true;}});</script></main>'''
        self.send_html(layout("Impostazioni Calendario",body,user))

    def shifts_page(self,user):
        q=parse_qs(urlparse(self.path).query)
        view=(q.get("vista") or ["mese"])[0]
        if view not in ("giorno","mese"):view="mese"
        selected=(q.get("data") or [rome_now().date().isoformat()])[0]
        try:date.fromisoformat(selected)
        except ValueError:selected=rome_now().date().isoformat()
        selected_date=date.fromisoformat(selected)
        today_date=rome_now().date()
        day_names=("Lun","Mar","Mer","Gio","Ven","Sab","Dom")
        monday=shift_week_monday(selected_date)
        today_monday=shift_week_monday(today_date)
        week_days=[monday+timedelta(days=i) for i in range(7)]
        def add_months(d,n):
            total=(d.month-1)+n
            year=d.year+total//12
            month=total%12+1
            return date(year,month,1)
        def month_grid_start(anchor):
            return anchor-timedelta(days=anchor.weekday())
        if view=="giorno":
            range_start,range_end=monday,monday+timedelta(days=6)
            grid_start=monday
        else:
            # Il range dati copre mese precedente/corrente/successivo: la
            # vista mensile usa un carosello a scroll-snap di 3 mesi
            # pre-renderizzati (stesso meccanismo dello swipe fluido tra
            # giorni), quindi servono i dati di tutti e tre in anticipo.
            current_month_start=selected_date.replace(day=1)
            prev_month_start=add_months(current_month_start,-1)
            next_month_start=add_months(current_month_start,1)
            grid_start=month_grid_start(current_month_start)
            prev_grid_start=month_grid_start(prev_month_start)
            next_grid_start=month_grid_start(next_month_start)
            range_start,range_end=prev_grid_start,next_grid_start+timedelta(days=41)
        oncall_window_start=monday-timedelta(weeks=1)
        oncall_weeks=[oncall_window_start+timedelta(weeks=i) for i in range(6)]
        with db() as c:
            color_settings=calendar_color_settings(c)
            shifts_by_day=shifts_for_range(c,range_start,range_end)
            vacations=vacations_overlapping(c,range_start,range_end)
            banner_operator,banner_manual=oncall_operator_for_week(c,today_monday,list(SHIFT_OPERATORS))
            oncall_rotation=[(wk,)+oncall_operator_for_week(c,wk,list(SHIFT_OPERATORS)) for wk in oncall_weeks]
        def vacation_operators_on(day):
            return [v["operator_name"] for v in vacations if date.fromisoformat(v["start_date"])<=day<=date.fromisoformat(v["end_date"])]
        today_sunday=today_monday+timedelta(days=6)
        if today_monday.month==today_sunday.month:
            week_label=f"Settimana {today_monday.isocalendar()[1]} ({today_monday.day} – {today_sunday.day} {MONTH_NAMES_IT[today_sunday.month-1][:3]})"
        else:
            week_label=f"Settimana {today_monday.isocalendar()[1]} ({today_monday.day} {MONTH_NAMES_IT[today_monday.month-1][:3]} – {today_sunday.day} {MONTH_NAMES_IT[today_sunday.month-1][:3]})"
        banner_avatar=self.calendar_operator_avatar(banner_operator,"sm",color_settings["operators"].get(banner_operator)) if banner_operator else ""
        oncall_banner_html=f'''<a class="section shift-oncall-banner" href="/turni/reperibilita">
          <span class="shift-oncall-icon">{lucide("moon")}</span>
          <span class="shift-oncall-body"><b>REPERIBILITÀ NOTTURNA</b><span>{esc(week_label)} — {esc(banner_operator or "Da assegnare")}</span></span>
          {banner_avatar}
          <span class="icon-btn" aria-hidden="true">{lucide("chevron-right")}</span>
        </a>'''
        switch_html=f'''<div class="shift-view-switch">
          <a class="btn {"" if view=="giorno" else "ghost"}" href="/turni?vista=giorno&data={selected}">Giorno</a>
          <a class="btn {"" if view=="mese" else "ghost"}" href="/turni?vista=mese&data={selected}">Mese</a>
          <a class="btn ghost tint-blue" style="margin-left:auto" href="/turni/ferie?ritorno_vista={view}&ritorno_data={selected}">{lucide("plus")} Ferie</a>
        </div>'''
        if view=="giorno":
            selected_index=(selected_date-monday).days
            daybar_cards=[]
            for i,day in enumerate(week_days):
                active_cls=" active" if day==selected_date else ""
                today_cls=" is-today" if day==today_date else ""
                day_total=sum(len(rows) for rows in shifts_by_day.get(day.isoformat(),{}).values())
                daybar_cards.append(f'''<button type="button" class="calendar-daybar-card{active_cls}{today_cls}" data-day-index="{i}" data-date="{day.isoformat()}" onclick="calendarSelectDay({i})">
                  <span class="calendar-daybar-dow">{day_names[day.weekday()].upper()}</span>
                  <span class="calendar-daybar-num">{day.day:02d}</span>
                  <span class="calendar-daybar-count">{day_total} turni</span>
                </button>''')
            daybar_html=f'''<div class="calendar-daybar-wrap">
              <button type="button" class="calendar-daybar-nav" onclick="location.href='/turni?vista=giorno&data={(monday-timedelta(days=7)).isoformat()}'" aria-label="Settimana precedente">‹</button>
              <div class="calendar-daybar" id="calendarDaybar">{''.join(daybar_cards)}</div>
              <button type="button" class="calendar-daybar-nav" onclick="location.href='/turni?vista=giorno&data={(monday+timedelta(days=7)).isoformat()}'" aria-label="Settimana successiva">›</button>
            </div>'''
            def sede_card_html(day,branch):
                day_shifts=shifts_by_day.get(day.isoformat(),{}).get(branch,[])
                branch_cls="branch-livorno" if branch=="Livorno" else "branch-empoli"
                rows_html=[]
                for row in day_shifts:
                    operator_color=color_settings["operators"].get(row["operator_name"])
                    avatar=self.calendar_operator_avatar(row["operator_name"],"sm",operator_color)
                    # Pill orario elegante (non piu' una barra proporzionale
                    # sulle 24h): l'informazione e' l'orario stesso, non una
                    # visualizzazione a Gantt — richiesta esplicita dell'utente.
                    if row["all_day"]:
                        time_text="Tutto il giorno"
                    else:
                        time_text=f'{esc(row["start_time"] or "")} – {esc(row["end_time"] or "")}'
                    accent_style=f' style="border-left-color:{esc(operator_color)}"' if operator_color else ""
                    pill_html=f'<span class="shift-time-pill"{accent_style}>{lucide("clock")}<span>{time_text}</span></span>'
                    # La matita apre lo stesso popup di Pianifica turni come
                    # overlay su questa pagina (non naviga altrove): chiudendo
                    # il popup si resta sulla vista Orari da cui si e' partiti.
                    row_data_shift=esc(json.dumps({
                        "branch":row["branch"],
                        "start_time":row["start_time"] if not row["all_day"] else "",
                        "end_time":row["end_time"] if not row["all_day"] else "",
                        "all_day":bool(row["all_day"]),
                    }))
                    rows_html.append(f'''<div class="shift-operator-row">
                      <div class="shift-operator-name">{avatar}<div><b>{esc(row["operator_name"])}</b><small>{esc(branch)}</small></div></div>
                      {pill_html}
                      <button type="button" class="icon-btn" data-operator="{esc(row['operator_name'])}" data-date="{day.isoformat()}" data-shift="{row_data_shift}" data-locked-branch="{esc(row['branch'])}" onclick="turniOpenCellEditor(this)" aria-label="Modifica turno di {esc(row['operator_name'])}">{lucide("pencil")}</button>
                    </div>''')
                body_html=''.join(rows_html) or f'<div class="shift-empty-state"><span class="shift-empty-state-icon">{lucide("users")}</span><span>Nessun turno assegnato.</span></div>'
                # "Aggiungi operatore" trasmette la sede della sezione da cui
                # e' stato premuto: la pagina di pianificazione la blocca per
                # ogni cella vuota aperta in questa sessione (niente tendina
                # "Seleziona sede", richiesta esplicita dell'utente).
                add_href=f"/turni/pianifica?settimana={monday.isoformat()}&sede={quote(branch)}&ritorno_vista={view}&ritorno_data={day.isoformat()}"
                return f'''<section class="section shift-sede-card {branch_cls}">
                  <div class="shift-sede-head">
                    <span class="shift-sede-title {branch_cls}">{lucide("map-pin")} {esc(branch.upper())}</span>
                    <a class="shift-add-btn {branch_cls}" href="{add_href}">{lucide("plus")} Aggiungi operatore</a>
                  </div>
                  {body_html}
                </section>'''
            # Carosello fluido a swipe nativo (scroll-snap), stessa identica
            # tecnica gia' usata da Calendario/Cremazioni per lo swipe tra
            # giorni (.calendar-day-pages/.calendar-day-page, calendarSelectDay
            # e calendarInitDayPages sono riusati cosi' come sono — nessuna
            # duplicazione di logica, nessun reload di pagina durante lo swipe).
            day_pages=''.join(f'<div class="calendar-day-page" data-day-index="{i}" data-date="{day.isoformat()}">{sede_card_html(day,"Livorno")}{sede_card_html(day,"Empoli")}</div>' for i,day in enumerate(week_days))
            content=daybar_html+f'<div class="calendar-day-pages" id="calendarDayPages" data-initial-day-index="{selected_index}">{day_pages}</div>'
        else:
            # Striscia mesi orizzontale scorrevole, stesso identico
            # comportamento (classi/scroll) del daybar giorni di Calendario
            # operativo/Cremazioni, richiesta esplicita dell'utente — "Oggi"
            # resta un pulsante separato, non parte della striscia. Serve
            # per saltare a un mese lontano (tap diretto); lo swipe fluido
            # tra mesi adiacenti e' gestito dal carosello sotto.
            month_window=[add_months(selected_date.replace(day=1),n) for n in range(-5,7)]
            month_cards=[]
            for m in month_window:
                active_cls=" active" if (m.month==selected_date.month and m.year==selected_date.year) else ""
                today_cls=" is-today" if (m.month==today_date.month and m.year==today_date.year) else ""
                month_cards.append(f'''<a class="calendar-daybar-card{active_cls}{today_cls}" href="/turni?vista=mese&data={m.isoformat()}">
                  <span class="calendar-daybar-dow">{MONTH_NAMES_IT[m.month-1]}</span>
                  <span class="calendar-daybar-num" style="font-size:15px">{m.year}</span>
                </a>''')
            month_nav_html=f'''<div class="calendar-daybar-wrap">
              <button type="button" class="calendar-daybar-nav" onclick="location.href='/turni?vista=mese&data={prev_month_start.isoformat()}'" aria-label="Mese precedente">‹</button>
              <div class="calendar-daybar">{''.join(month_cards)}</div>
              <button type="button" class="calendar-daybar-nav" onclick="location.href='/turni?vista=mese&data={next_month_start.isoformat()}'" aria-label="Mese successivo">›</button>
            </div>
            <div class="shift-month-nav-today"><a class="btn ghost" href="/turni?vista=mese">{lucide("calendar")} Oggi</a></div>'''
            def month_cell_html(day,month_anchor):
                # Vista mensile = solo panoramica: mai orari, mai più di due
                # nomi per sede (altrimenti "N operatori"), cella sempre
                # della stessa dimensione — requisito esplicito dell'utente
                # dopo aver visto celle deformate/testo illeggibile. Il
                # dettaglio completo (orari inclusi) resta nella vista
                # giornaliera, a un tap di distanza.
                day_iso=day.isoformat()
                day_data=shifts_by_day.get(day_iso,{})
                classes=["shift-month-cell"]
                if day==today_date:classes.append("is-today")
                if day.month!=month_anchor.month:classes.append("is-other-month")
                blocks=[]
                for branch in SHIFT_BRANCHES:
                    branch_rows=day_data.get(branch,[])
                    if branch_rows:
                        branch_cls="branch-livorno" if branch=="Livorno" else "branch-empoli"
                        if len(branch_rows)<=2:
                            names_html="".join(f"<div>{esc(r['operator_name'])}</div>" for r in branch_rows)
                        else:
                            names_html=f"<div>{len(branch_rows)} operatori</div>"
                        blocks.append(f'<div class="shift-month-cell-branch {branch_cls}"><div class="shift-month-cell-branch-label"><span class="shift-month-cell-dot"></span>{esc(branch[:3].upper())}</div><div class="shift-month-cell-names">{names_html}</div></div>')
                href=f"/turni?vista=giorno&data={day_iso}"
                return f'<a class="{" ".join(classes)}" href="{href}"><b>{day.day}</b>{"".join(blocks)}</a>'
            dow_row='<div class="shift-month-dow-row">'+''.join(f'<div class="shift-month-dow">{n}</div>' for n in day_names)+'</div>'
            def vacation_bars_html(anchor_grid_start):
                # Barra continua per ogni operatore in ferie, stesso colore
                # usato per la sua sigla/avatar altrove — una sola striscia
                # che attraversa i giorni consecutivi invece di un'etichetta
                # per cella, ottenuta posizionando ogni barra su piu' colonne
                # della stessa griglia CSS (attraversa naturalmente lo spazio
                # tra le celle, nessuna interruzione visiva).
                bars=[]
                for row in range(6):
                    row_days=[anchor_grid_start+timedelta(days=row*7+col) for col in range(7)]
                    day_ops=[set(vacation_operators_on(d)) for d in row_days]
                    active_ops=sorted(
                        set.union(*day_ops) if day_ops else set(),
                        key=lambda name: SHIFT_OPERATORS.index(name) if name in SHIFT_OPERATORS else 99,
                    )
                    for slot,op in enumerate(active_ops[:2]):
                        col=0
                        while col<7:
                            if op not in day_ops[col]:
                                col+=1;continue
                            start_col=col
                            while col<7 and op in day_ops[col]:col+=1
                            end_col=col-1
                            color=color_settings["operators"].get(op) or "var(--muted)"
                            bars.append(f'<div class="shift-vacation-bar" style="grid-column:{start_col+1}/{end_col+2};grid-row:{row+1};background:{esc(color)};margin-bottom:{3+slot*20}px" title="{esc(op)}">FERIE {esc(op.upper())}</div>')
                return ''.join(bars)
            def month_grid_html(anchor,anchor_grid_start):
                # Le barre ferie sono su una griglia separata sovrapposta
                # esattamente a quella dei giorni (stesse colonne/righe/gap),
                # non dentro la stessa griglia: un elemento posizionato in
                # modo esplicito (grid-column/grid-row) "riserva" quella
                # cella per l'algoritmo di posizionamento automatico, e
                # spostava le celle giorno auto-posizionate che ci finivano
                # sopra — bug reale, non solo estetico.
                cells_html=''.join(month_cell_html(anchor_grid_start+timedelta(days=i),anchor) for i in range(42))
                bars_html=vacation_bars_html(anchor_grid_start)
                return f'<div class="shift-month-grid-wrap"><div class="shift-month-grid">{cells_html}</div><div class="shift-month-overlay">{bars_html}</div></div>'
            # Carosello fluido a swipe nativo (scroll-snap) tra mese
            # precedente/corrente/successivo, stessa tecnica dello swipe
            # giorni: si preferisce ricaricare la pagina quando lo swipe si
            # ferma su un mese adiacente (nessuna paginazione infinita) —
            # il gesto di trascinamento resta comunque nativo e fluido.
            month_pages=''.join(
                f'<div class="calendar-day-page" data-page-index="{i}" data-href="/turni?vista=mese&data={anchor.isoformat()}">{month_grid_html(anchor,gstart)}</div>'
                for i,(anchor,gstart) in enumerate((
                    (prev_month_start,prev_grid_start),
                    (current_month_start,grid_start),
                    (next_month_start,next_grid_start),
                ))
            )
            grid=f'<div class="calendar-day-pages" id="shiftMonthPages">{month_pages}</div>'
            legend_html=f'''<div class="shift-month-legend">
              <span><span class="dot" style="background:var(--brand)"></span>Livorno</span>
              <span><span class="dot" style="background:var(--green)"></span>Empoli</span>
              <span><span class="dot" style="background:#c084fc"></span>Reperibilità notturna</span>
              <span><span class="dot" style="background:var(--muted)"></span>Nessun turno</span>
            </div>'''
            oncall_cards=[]
            for wk,op_name,is_manual in oncall_rotation:
                wk_sunday=wk+timedelta(days=6)
                is_current=wk==today_monday
                oncall_cards.append(f'''<div class="shift-oncall-week{" current" if is_current else ""}">
                  <span>Sett. {wk.isocalendar()[1]}</span>
                  <span>{wk.day} {MONTH_NAMES_IT[wk.month-1][:3]} – {wk_sunday.day} {MONTH_NAMES_IT[wk_sunday.month-1][:3]}</span>
                  <b>{esc(op_name or "—")}</b>{f' {lucide("moon")}' if is_current else ''}
                </div>''')
            oncall_strip_html=f'''<div class="shift-oncall-strip">{''.join(oncall_cards)}</div>
              <a class="btn ghost" style="margin-top:12px" href="/turni/reperibilita">{lucide("moon")} Gestisci rotazione</a>'''
            content=month_nav_html+dow_row+grid+legend_html+f'<section class="section" style="margin-top:16px"><h2>Reperibilità notturna <small class="sub">(rotazione settimanale)</small></h2>{oncall_strip_html}</section>'
        # Sia la vista giorno che quella mese usano un carosello a
        # scroll-snap (swipe nativo e fluido, gestito dal browser) per
        # cambiare periodo: nessuno swipe custom via JS resta necessario.
        body=f'''<main class="wrap calendar-wrap">
          <div class="titlebar calendar-main-title"><div><h1>Orari</h1><p class="sub">Pianificazione e reperibilità</p></div></div>
          {oncall_banner_html}
          {switch_html}
          {content}
          {self.shift_cell_editor_html() if view=="giorno" else ""}
        </main>'''
        self.send_html(layout("Orari",body,user))

    def shifts_plan_page(self,user):
        q=parse_qs(urlparse(self.path).query)
        settimana=(q.get("settimana") or [rome_now().date().isoformat()])[0]
        try:date.fromisoformat(settimana)
        except ValueError:settimana=rome_now().date().isoformat()
        monday=shift_week_monday(date.fromisoformat(settimana))
        sunday=monday+timedelta(days=6)
        week_days=[monday+timedelta(days=i) for i in range(7)]
        evidenzia=(q.get("evidenzia") or [""])[0]
        highlight_operator,highlight_date="",""
        if ":" in evidenzia:
            highlight_operator,highlight_date=evidenzia.rsplit(":",1)
        # Contesto sede: arriva da "Aggiungi operatore" (una sezione sede
        # precisa nella vista giornaliera) o dalla matita di modifica (sede
        # del turno stesso). Se presente e valido resta bloccato per tutta
        # la sessione di pianificazione (propagato nei link di navigazione
        # sotto); se assente non si assegna nulla di arbitrario — resta "",
        # e ogni cella vuota apre normalmente la scelta sede come prima.
        sede_raw=(q.get("sede") or [""])[0]
        sede_error=""
        if sede_raw and sede_raw not in SHIFT_BRANCHES:
            sede_error=f'Sede "{esc(sede_raw)}" non valida: nessuna sede è stata impostata automaticamente.'
        locked_sede=sede_raw if sede_raw in SHIFT_BRANCHES else ""
        sede_qs=f"&sede={quote(locked_sede)}" if locked_sede else ""
        sede_error_html=f'<div class="flash warning">{sede_error}</div>' if sede_error else ""
        # "Torna a Orari": riporta esattamente alla vista (giorno/mese) e
        # data da cui e' partito "Aggiungi operatore" o la matita di
        # modifica, propagato invariato attraverso i cambi di settimana.
        ritorno_vista=(q.get("ritorno_vista") or [""])[0]
        if ritorno_vista not in ("giorno","mese"):ritorno_vista="giorno"
        ritorno_data=(q.get("ritorno_data") or [""])[0]
        try:date.fromisoformat(ritorno_data)
        except ValueError:ritorno_data=""
        ritorno_qs=f"&ritorno_vista={ritorno_vista}&ritorno_data={ritorno_data}" if ritorno_data else ""
        day_names=("Lun","Mar","Mer","Gio","Ven","Sab","Dom")
        if monday.month==sunday.month:
            week_label=f"{monday.day} – {sunday.day} {MONTH_NAMES_IT[sunday.month-1]} {sunday.year}"
        else:
            week_label=f"{monday.day} {MONTH_NAMES_IT[monday.month-1]} – {sunday.day} {MONTH_NAMES_IT[sunday.month-1]} {sunday.year}"
        prev_week=(monday-timedelta(days=7)).isoformat()
        next_week=(monday+timedelta(days=7)).isoformat()
        today_date=rome_now().date()
        week_dates_iso=[d.isoformat() for d in week_days]
        with db() as c:
            color_settings=calendar_color_settings(c)
            shifts_by_day=shifts_for_range(c,monday,sunday)
        oggi_qs="&".join(p for p in (f"sede={quote(locked_sede)}" if locked_sede else "",ritorno_qs.lstrip("&")) if p)
        date_nav_html=f'''<div class="cremation-date-nav">
          <a class="cremation-nav-btn tint-slate" href="/turni/pianifica?settimana={prev_week}{sede_qs}{ritorno_qs}" aria-label="Settimana precedente">‹</a>
          <div class="cremation-date-label">{lucide("calendar")}<span>{esc(week_label)}</span></div>
          <a class="cremation-nav-btn tint-slate" href="/turni/pianifica?settimana={next_week}{sede_qs}{ritorno_qs}" aria-label="Settimana successiva">›</a>
          <a class="cremation-today-btn {"active" if today_date.isoformat() in week_dates_iso else ""}" href="/turni/pianifica?{oggi_qs}">Oggi</a>
        </div>'''
        head_cells='<div class="shift-plan-corner"></div>'+''.join(f'<div class="shift-plan-head-cell{" is-today" if d==today_date else ""}">{day_names[d.weekday()]}<br>{d.day:02d}/{d.month:02d}</div>' for d in week_days)
        branch_options=''.join(f'<option value="{b}">{b}</option>' for b in SHIFT_BRANCHES)
        def cell_html(operator,day):
            day_iso=day.isoformat()
            shift_row=None
            for branch_rows in shifts_by_day.get(day_iso,{}).values():
                for row in branch_rows:
                    if row["operator_name"]==operator:
                        shift_row=row;break
                if shift_row:break
            if shift_row:
                branch_cls="branch-livorno" if shift_row["branch"]=="Livorno" else "branch-empoli"
                has_cls=" has-shift"
                time_label="Tutto il giorno" if shift_row["all_day"] else f'{esc(shift_row["start_time"] or "")}–{esc(shift_row["end_time"] or "")}'
                cell_content=f'<span class="shift-cell-branch">{esc(shift_row["branch"].upper())}</span><span>{time_label}</span>'
            else:
                branch_cls="";has_cls=""
                cell_content='<span class="shift-cell-empty">+</span>'
            data_shift=esc(json.dumps({
                "branch":shift_row["branch"] if shift_row else "",
                "start_time":shift_row["start_time"] if shift_row and not shift_row["all_day"] else "",
                "end_time":shift_row["end_time"] if shift_row and not shift_row["all_day"] else "",
                "all_day":bool(shift_row["all_day"]) if shift_row else False,
            }))
            evidenziata_cls=" evidenziata" if operator==highlight_operator and day_iso==highlight_date else ""
            # La sede di un turno gia' esistente vince sempre (non si cambia
            # sede da questo popup); su una cella vuota si usa la sede
            # bloccata dal contesto di pagina, se presente.
            locked_branch_for_cell=shift_row["branch"] if shift_row else locked_sede
            return f'<button type="button" class="shift-cell{" " if branch_cls else ""}{branch_cls}{has_cls}{evidenziata_cls}" data-operator="{esc(operator)}" data-date="{day_iso}" data-shift="{data_shift}" data-locked-branch="{esc(locked_branch_for_cell)}" onclick="turniOpenCellEditor(this)">{cell_content}</button>'
        rows_html=[]
        for operator in SHIFT_OPERATORS:
            avatar=self.calendar_operator_avatar(operator,"sm",color_settings["operators"].get(operator))
            rows_html.append(f'<div class="shift-plan-operator">{avatar}<span>{esc(operator)}</span></div>'+''.join(cell_html(operator,day) for day in week_days))
        grid_html=f'<div class="shift-plan-scroll"><div class="shift-plan-grid">{head_cells}{"".join(rows_html)}</div></div>'
        auto_open_js=""
        if highlight_operator and highlight_date:
            auto_open_js="var target=document.querySelector('.shift-cell.evidenziata');if(target){target.scrollIntoView({block:'center'});turniOpenCellEditor(target);}"
        editor_html=self.shift_cell_editor_html(auto_open_js)
        back_href=f"/turni?vista={ritorno_vista}&data={ritorno_data}" if ritorno_data else "/turni"
        body=f'''<main class="wrap calendar-wrap">
          <div class="titlebar calendar-main-title"><div><h1>Pianifica turni</h1><p class="sub">Seleziona una settimana e compila le celle per ogni operatore.</p></div><a class="btn ghost tint-slate" href="{back_href}">← Torna a Orari</a></div>
          {sede_error_html}
          {date_nav_html}
          {grid_html}
          {editor_html}
        </main>'''
        self.send_html(layout("Pianifica turni",body,user))

    def shift_cell_editor_html(self,auto_open_js=""):
        # Popup condiviso: usato sia dalla griglia di Pianifica turni sia
        # (come overlay, senza navigare via) dalla vista giornaliera di
        # Orari — stessa identica logica in entrambi i casi, mai duplicata.
        branch_options=''.join(f'<option value="{b}">{b}</option>' for b in SHIFT_BRANCHES)
        return f'''<div class="shift-cell-editor-backdrop" id="shiftCellEditorBackdrop" hidden onclick="if(event.target===this)turniCloseCellEditor()">
          <form class="shift-cell-editor" id="shiftCellEditorForm" onsubmit="turniSaveCell(event)">
            <h3 id="shiftCellEditorTitle">Turno</h3>
            <input type="hidden" id="shiftCellOperator">
            <input type="hidden" id="shiftCellDate">
            <div class="fields">
              <div class="field" id="shiftCellBranchField"><label>Sede</label><select id="shiftCellBranch"><option value="">Seleziona sede</option>{branch_options}</select></div>
              <p class="sub" id="shiftCellSedeInfo" hidden></p>
              <div class="shift-view-switch">
                <button type="button" class="btn ghost tint-blue" onclick="turniSetPreset('primo')">Primo turno</button>
                <button type="button" class="btn ghost tint-violet" onclick="turniSetPreset('secondo')">Secondo turno</button>
              </div>
              <div class="shift-view-switch">
                <button type="button" class="btn ghost tint-amber" onclick="turniSetPreset('mattina')">Mattina</button>
                <button type="button" class="btn ghost tint-teal" onclick="turniSetPreset('pomeriggio')">Pomeriggio</button>
              </div>
              <label style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="shiftCellAllDay" onchange="turniToggleAllDay(this)"> Tutto il giorno</label>
              <div id="shiftCellStartField">{calendar_time_wheel_field("Orario inizio","shiftCellStart")}</div>
              <div id="shiftCellEndField">{calendar_time_wheel_field("Orario fine","shiftCellEnd")}</div>
            </div>
            <p class="shift-cell-editor-note" id="shiftCellEditorNote"></p>
            <div class="actions">
              <button type="button" class="btn ghost tint-slate" onclick="turniCloseCellEditor()">Annulla</button>
              <button type="button" class="btn danger-btn" onclick="turniRemoveCell()">Rimuovi turno</button>
              <button type="submit" class="btn">Salva turno</button>
            </div>
          </form>
        </div>
        <script>(function(){{
          var backdrop=document.getElementById('shiftCellEditorBackdrop');
          var currentBtn=null;
          function isGridCell(btn){{return !!(btn&&btn.classList.contains('shift-cell'));}}
          function applyCellResult(btn,cell){{
            btn.dataset.shift=JSON.stringify(cell);
            var branchCls=cell.branch?(cell.branch==='Livorno'?' branch-livorno has-shift':' branch-empoli has-shift'):'';
            btn.className='shift-cell'+branchCls;
            if(cell.branch){{
              var timeLabel=cell.all_day?'Tutto il giorno':((cell.start_time||'')+'–'+(cell.end_time||''));
              btn.innerHTML='<span class="shift-cell-branch">'+cell.branch.toUpperCase()+'</span><span>'+timeLabel+'</span>';
            }}else{{
              btn.innerHTML='<span class="shift-cell-empty">+</span>';
            }}
          }}
          window.turniOpenCellEditor=function(btn){{
            currentBtn=btn;
            var data=JSON.parse(btn.dataset.shift||'{{}}');
            var lockedBranch=btn.dataset.lockedBranch||'';
            var effectiveBranch=data.branch||lockedBranch||'';
            document.getElementById('shiftCellOperator').value=btn.dataset.operator;
            document.getElementById('shiftCellDate').value=btn.dataset.date;
            document.getElementById('shiftCellEditorTitle').textContent=btn.dataset.operator+' · '+btn.dataset.date;
            var branchSelect=document.getElementById('shiftCellBranch');
            var branchField=document.getElementById('shiftCellBranchField');
            var sedeInfo=document.getElementById('shiftCellSedeInfo');
            branchSelect.value=effectiveBranch;
            if(effectiveBranch){{
              branchField.hidden=true;
              sedeInfo.hidden=false;
              sedeInfo.textContent=btn.dataset.operator+' · '+effectiveBranch;
            }}else{{
              branchField.hidden=false;
              sedeInfo.hidden=true;
            }}
            document.getElementById('shiftCellAllDay').checked=!!data.all_day;
            document.getElementById('shiftCellStart').value=data.start_time||'';
            document.getElementById('shiftCellEnd').value=data.end_time||'';
            turniToggleAllDay(document.getElementById('shiftCellAllDay'));
            document.getElementById('shiftCellEditorNote').textContent='';
            backdrop.hidden=false;
          }};
          window.turniCloseCellEditor=function(){{backdrop.hidden=true;currentBtn=null;}};
          window.turniToggleAllDay=function(checkbox){{
            var on=checkbox.checked;
            document.getElementById('shiftCellStartField').style.display=on?'none':'';
            document.getElementById('shiftCellEndField').style.display=on?'none':'';
          }};
          window.turniSetPreset=function(kind){{
            var presets={{mattina:['08:30','13:00'],pomeriggio:['14:30','19:30'],primo:['08:30','17:30'],secondo:['10:30','19:30']}};
            var range=presets[kind]||presets.mattina;
            var allDay=document.getElementById('shiftCellAllDay');
            allDay.checked=false;
            turniToggleAllDay(allDay);
            document.getElementById('shiftCellStart').value=range[0];
            document.getElementById('shiftCellEnd').value=range[1];
          }};
          function afterCellChange(cell){{
            if(currentBtn&&isGridCell(currentBtn)){{applyCellResult(currentBtn,cell);turniCloseCellEditor();}}
            else{{location.reload();}}
          }}
          window.turniSaveCell=function(ev){{
            ev.preventDefault();
            var note=document.getElementById('shiftCellEditorNote');
            var branch=document.getElementById('shiftCellBranch').value;
            if(!branch){{note.textContent='La sede è obbligatoria.';return;}}
            var allDay=document.getElementById('shiftCellAllDay').checked;
            var startVal=document.getElementById('shiftCellStart').value;
            var endVal=document.getElementById('shiftCellEnd').value;
            if(!allDay&&startVal&&endVal&&endVal<=startVal){{note.textContent="L'orario fine deve essere successivo all'orario inizio.";return;}}
            var payload={{operator:document.getElementById('shiftCellOperator').value,data:document.getElementById('shiftCellDate').value,branch:branch,all_day:allDay?'1':'0',start_time:allDay?'':startVal,end_time:allDay?'':endVal,azione:'salva'}};
            fetch('/turni/pianifica/cella',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:new URLSearchParams(payload)}})
              .then(function(r){{return r.json();}}).then(function(res){{
                if(!res.ok){{note.textContent=res.error||'Errore nel salvataggio.';return;}}
                afterCellChange(res.cell);
              }}).catch(function(){{note.textContent='Errore di rete.';}});
          }};
          window.turniRemoveCell=function(){{
            var payload={{operator:document.getElementById('shiftCellOperator').value,data:document.getElementById('shiftCellDate').value,azione:'rimuovi'}};
            fetch('/turni/pianifica/cella',{{method:'POST',headers:{{'Content-Type':'application/x-www-form-urlencoded'}},body:new URLSearchParams(payload)}})
              .then(function(r){{return r.json();}}).then(function(res){{
                if(!res.ok){{document.getElementById('shiftCellEditorNote').textContent=res.error||'Errore.';return;}}
                afterCellChange(res.cell);
              }});
          }};
          {auto_open_js}
        }})();</script>'''

    def save_shift_cell(self,user):
        form=self.form()
        operator=(form.get("operator") or "").strip()
        work_date=(form.get("data") or "").strip()
        azione=form.get("azione") or "salva"
        if operator not in SHIFT_OPERATORS or not work_date:
            return self.send_json({"ok":False,"error":"Dati non validi."},400)
        try:date.fromisoformat(work_date)
        except ValueError:
            return self.send_json({"ok":False,"error":"Data non valida."},400)
        stamp=rome_now().isoformat(timespec="seconds")
        with db() as c:
            if azione=="rimuovi":
                delete_shift_row(c,operator,work_date)
                cell={"branch":"","start_time":"","end_time":"","all_day":False}
            else:
                branch=(form.get("branch") or "").strip()
                if branch not in SHIFT_BRANCHES:
                    return self.send_json({"ok":False,"error":"La sede è obbligatoria."},400)
                all_day=form.get("all_day")=="1"
                start_time=(form.get("start_time") or "").strip() or None
                end_time=(form.get("end_time") or "").strip() or None
                if not all_day and (not start_time or not end_time):
                    return self.send_json({"ok":False,"error":"Indica orario inizio e fine, oppure seleziona Tutto il giorno."},400)
                if all_day:
                    start_time=None;end_time=None
                upsert_shift(c,operator,work_date,branch,start_time,end_time,all_day,user["id"],stamp)
                cell={"branch":branch,"start_time":start_time or "","end_time":end_time or "","all_day":all_day}
        self.send_json({"ok":True,"cell":cell})

