    def cremation_create_cycle(self,user):
        f=self.form()
        cycle_date_raw=(f.get("data") or "").strip()[:10]
        if cycle_date_raw:
            try:date.fromisoformat(cycle_date_raw)
            except ValueError:return self.send_json({"ok":False,"error":"Data non valida."},400)
            cycle_date=cycle_date_raw
        else:
            cycle_date=rome_now().date().isoformat()
        practice_id=(f.get("practice_id") or "").strip()
        planned_start_raw=(f.get("planned_start") or "").strip()[:5]
        planned_end_raw=(f.get("planned_end") or "").strip()[:5]
        stamp=now()
        with db() as c:
            if practice_id:
                practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(practice_id,)).fetchone()
                if not practice or practice["status"]=="Consegnato" or practice["service_type"]!="Cremazione singola" or practice["cremation_cycle_id"]:
                    return self.send_json({"ok":False,"error":"Animale non più disponibile. Ricarica la pagina."},409)
            if planned_start_raw or planned_end_raw:
                if not re.fullmatch(r"\d{2}:\d{2}",planned_start_raw) or not re.fullmatch(r"\d{2}:\d{2}",planned_end_raw):
                    return self.send_json({"ok":False,"error":"Orario non valido."},400)
                if cremation_minutes_between(planned_start_raw,planned_end_raw)<0:
                    return self.send_json({"ok":False,"error":"L'orario di fine non può essere prima dell'orario di inizio."},400)
                start,end=planned_start_raw,planned_end_raw
            else:
                start,end=cremation_cycle_next_slot(c,cycle_date)
            status="in_attesa" if practice_id else "pianificato"
            cycle_id=c.execute("INSERT INTO cremation_cycles(cycle_date,status,planned_start,planned_end,created_at,updated_at) VALUES(?,?,?,?,?,?)",
                                (cycle_date,status,start,end,stamp,stamp)).lastrowid
            if practice_id:
                c.execute("UPDATE practices SET cremation_cycle_id=?,updated_at=? WHERE id=?",(cycle_id,stamp,practice_id))
                cremation_log_status_change(c,practice_id,practice["status"],"In programma",user["id"],stamp)
                if assisted_cremation_label(practice):
                    c.execute("UPDATE practices SET owner_notified_status='da_avvisare',owner_notified_at=NULL,owner_notified_by=NULL WHERE id=?",(practice_id,))
                cremation_notify_cycle_waiting(c,user["id"],cycle_id,cycle_date,start,end)
        return self.send_json({"ok":True,"cycle_id":cycle_id})

    def api_cremation_next_slot(self,user):
        q=parse_qs(urlparse(self.path).query)
        cycle_date=(q.get("data",[""])[0] or "").strip()[:10]
        try:date.fromisoformat(cycle_date)
        except ValueError:return self.send_json({"ok":False,"error":"Data non valida."},400)
        with db() as c:
            start,end=cremation_cycle_next_slot(c,cycle_date)
        return self.send_json({"ok":True,"start":start,"end":end})

    def cremation_assign_to_cycle(self,user,cycle_id):
        f=self.form()
        practice_id=(f.get("practice_id") or "").strip()
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status,cycle_date,planned_start,planned_end FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            if cycle["status"]=="completato":
                return self.send_json({"ok":False,"error":"Il ciclo è già completato."},409)
            count=c.execute("SELECT COUNT(*) n FROM practices WHERE cremation_cycle_id=? AND (deleted_at IS NULL OR deleted_at='')",(cycle_id,)).fetchone()["n"]
            if count>=2:
                return self.send_json({"ok":False,"error":"Il ciclo contiene già 2 animali."},409)
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(practice_id,)).fetchone()
            if not practice or practice["status"]=="Consegnato" or practice["service_type"]!="Cremazione singola" or practice["cremation_cycle_id"]:
                return self.send_json({"ok":False,"error":"Animale non più disponibile. Ricarica la pagina."},409)
            c.execute("UPDATE practices SET cremation_cycle_id=?,updated_at=? WHERE id=?",(cycle_id,stamp,practice_id))
            cremation_log_status_change(c,practice_id,practice["status"],"In programma",user["id"],stamp)
            if assisted_cremation_label(practice):
                c.execute("UPDATE practices SET owner_notified_status='da_avvisare',owner_notified_at=NULL,owner_notified_by=NULL WHERE id=?",(practice_id,))
            if cycle["status"]=="pianificato":
                c.execute("UPDATE cremation_cycles SET status='in_attesa',updated_at=? WHERE id=?",(stamp,cycle_id))
                cremation_notify_cycle_waiting(c,user["id"],cycle_id,cycle["cycle_date"],cycle["planned_start"],cycle["planned_end"])
        return self.send_json({"ok":True})

    def cremation_start_cycle(self,user,cycle_id):
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            if cycle["status"]!="in_attesa":
                return self.send_json({"ok":False,"error":"Il ciclo non è in attesa di avvio."},409)
            c.execute("UPDATE cremation_cycles SET status='in_corso',actual_start=?,updated_at=? WHERE id=?",(stamp,stamp,cycle_id))
        return self.send_json({"ok":True})

    def cremation_complete_cycle(self,user,cycle_id):
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            if cycle["status"]!="in_corso":
                return self.send_json({"ok":False,"error":"Il ciclo non è in corso."},409)
            c.execute("UPDATE cremation_cycles SET status='completato',actual_end=?,updated_at=? WHERE id=?",(stamp,stamp,cycle_id))
            practices=c.execute("SELECT * FROM practices WHERE cremation_cycle_id=? AND (deleted_at IS NULL OR deleted_at='')",(cycle_id,)).fetchall()
            for row in practices:
                if row["status"]=="Da consegnare":continue
                c.execute("UPDATE practices SET cremation_registered='Si',updated_at=? WHERE id=?",(stamp,row["id"]))
                cremation_log_status_change(c,row["id"],row["status"] or "Ritirato","Da consegnare",user["id"],stamp)
        return self.send_json({"ok":True})

    def cremation_revert_start(self,user,cycle_id):
        """Annulla un avvio per errore: torna in_attesa, nessun'altra
        conseguenza da disfare (avviare un ciclo non tocca le pratiche)."""
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            if cycle["status"]!="in_corso":
                return self.send_json({"ok":False,"error":"Il ciclo non è in corso."},409)
            c.execute("UPDATE cremation_cycles SET status='in_attesa',actual_start=NULL,updated_at=? WHERE id=?",(stamp,cycle_id))
        return self.send_json({"ok":True})

    def cremation_revert_complete(self,user,cycle_id):
        """Annulla un completamento per errore: torna in_corso e riporta ogni
        pratica collegata allo stato che aveva PRIMA del completamento (letto
        dalla stessa riga di practice_history scritta da cremation_complete_cycle),
        mai un valore fisso indovinato — cosi' resta corretto anche per pratiche
        che partivano da stati diversi da 'Ritirato'."""
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            if cycle["status"]!="completato":
                return self.send_json({"ok":False,"error":"Il ciclo non è completato."},409)
            c.execute("UPDATE cremation_cycles SET status='in_corso',actual_end=NULL,updated_at=? WHERE id=?",(stamp,cycle_id))
            practices=c.execute("SELECT * FROM practices WHERE cremation_cycle_id=? AND (deleted_at IS NULL OR deleted_at='')",(cycle_id,)).fetchall()
            for row in practices:
                if row["status"]!="Da consegnare":continue
                last_change=c.execute(
                    "SELECT old_value FROM practice_history WHERE practice_id=? AND event_type='Cambio stato rapido' AND new_value='Da consegnare' ORDER BY id DESC LIMIT 1",
                    (row["id"],),
                ).fetchone()
                if not last_change:continue
                previous_status=last_change["old_value"] or "Ritirato"
                c.execute("UPDATE practices SET cremation_registered='',updated_at=? WHERE id=?",(stamp,row["id"]))
                cremation_log_status_change(c,row["id"],"Da consegnare",previous_status,user["id"],stamp)
        return self.send_json({"ok":True})

    def cremation_edit_cycle(self,user,cycle_id):
        f=self.form()
        start=(f.get("planned_start") or "").strip()[:5]
        end=(f.get("planned_end") or "").strip()[:5]
        cycle_date_raw=(f.get("cycle_date") or "").strip()[:10]
        if not re.fullmatch(r"\d{2}:\d{2}",start) or not re.fullmatch(r"\d{2}:\d{2}",end):
            return self.send_json({"ok":False,"error":"Orario non valido."},400)
        if cremation_minutes_between(start,end)<0:
            return self.send_json({"ok":False,"error":"L'orario di fine non può essere prima dell'orario di inizio."},400)
        if cycle_date_raw:
            try:date.fromisoformat(cycle_date_raw)
            except ValueError:return self.send_json({"ok":False,"error":"Data non valida."},400)
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,cycle_date FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            target_date=cycle_date_raw or cycle["cycle_date"]
            c.execute("UPDATE cremation_cycles SET cycle_date=?,planned_start=?,planned_end=?,updated_at=? WHERE id=?",(target_date,start,end,stamp,cycle_id))
            # se necessario, sposta in avanti i cicli successivi della stessa giornata (quella nuova, se il ciclo e' stato spostato) che ora si sovrappongono
            rows=c.execute("SELECT id,planned_start,planned_end FROM cremation_cycles WHERE cycle_date=? ORDER BY planned_start ASC,id ASC",(target_date,)).fetchall()
            prev_end=None
            for row in rows:
                row_start,row_end=(start,end) if row["id"]==cycle_id else (row["planned_start"],row["planned_end"])
                if prev_end is not None:
                    min_start=cremation_time_add(prev_end,CREMATION_CYCLE_GAP_MIN)
                    if row_start<min_start and row["id"]!=cycle_id:
                        duration=cremation_minutes_between(row["planned_start"],row["planned_end"])
                        row_start=min_start;row_end=cremation_time_add(row_start,duration)
                        c.execute("UPDATE cremation_cycles SET planned_start=?,planned_end=?,updated_at=? WHERE id=?",(row_start,row_end,stamp,row["id"]))
                prev_end=row_end
        return self.send_json({"ok":True})

    def cremation_delete_cycle(self,user,cycle_id):
        stamp=now()
        with db() as c:
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            if not cycle:return self.send_json({"ok":False,"error":"Ciclo non trovato"},404)
            practices=c.execute("SELECT id,status FROM practices WHERE cremation_cycle_id=? AND (deleted_at IS NULL OR deleted_at='')",(cycle_id,)).fetchall()
            for p in practices:
                c.execute("UPDATE practices SET cremation_cycle_id=NULL,updated_at=? WHERE id=?",(stamp,p["id"]))
                if p["status"]=="In programma":
                    cremation_log_status_change(c,p["id"],"In programma","Ritirato",user["id"],stamp)
            c.execute("DELETE FROM cremation_cycles WHERE id=?",(cycle_id,))
        return self.send_json({"ok":True})

    def cremation_remove_from_cycle(self,user,pid):
        stamp=now()
        with db() as c:
            practice=c.execute("SELECT id,status,cremation_cycle_id FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice or not practice["cremation_cycle_id"]:
                return self.send_json({"ok":False,"error":"Animale non assegnato a nessun ciclo."},404)
            cycle_id=practice["cremation_cycle_id"]
            cycle=c.execute("SELECT id,status FROM cremation_cycles WHERE id=?",(cycle_id,)).fetchone()
            c.execute("UPDATE practices SET cremation_cycle_id=NULL,updated_at=? WHERE id=?",(stamp,pid))
            if practice["status"]=="In programma":
                cremation_log_status_change(c,pid,"In programma","Ritirato",user["id"],stamp)
            if cycle and cycle["status"]=="in_attesa":
                remaining=c.execute("SELECT COUNT(*) n FROM practices WHERE cremation_cycle_id=? AND (deleted_at IS NULL OR deleted_at='')",(cycle_id,)).fetchone()["n"]
                if remaining==0:
                    c.execute("UPDATE cremation_cycles SET status='pianificato',updated_at=? WHERE id=?",(stamp,cycle_id))
        return self.send_json({"ok":True})

    def owner_notified_toggle(self,user,pid):
        f=self.form()
        new_status=(f.get("status") or "").strip()
        if new_status not in ("da_avvisare","avvisato"):
            return self.send_json({"ok":False,"error":"Stato non valido."},400)
        stamp=now()
        with db() as c:
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice:return self.send_json({"ok":False,"error":"Pratica non trovata"},404)
            if not assisted_cremation_label(practice):
                return self.send_json({"ok":False,"error":"Questa pratica non è una cremazione assistita."},409)
            if new_status=="avvisato":
                c.execute("UPDATE practices SET owner_notified_status='avvisato',owner_notified_at=?,owner_notified_by=?,updated_at=? WHERE id=?",
                          (stamp,user["id"],stamp,pid))
            else:
                c.execute("UPDATE practices SET owner_notified_status='da_avvisare',owner_notified_at=NULL,owner_notified_by=NULL,updated_at=? WHERE id=?",
                          (stamp,pid))
        return self.send_json({"ok":True,"status":new_status})












    def disposal_contact_for(self,row):
        owner=((row["owner_first_name"] or "")+" "+(row["owner_last_name"] or "")).strip()
        return owner or row["clinic_name"] or row["veterinarian_name"] or "-"

    def disposal_eligible_practices(self,c,date_from,date_to):
        return c.execute("""SELECT * FROM practices WHERE (deleted_at IS NULL OR deleted_at='')
                            AND service_type='Cremazione collettiva' AND status!='Smaltito'
                            AND date(COALESCE(NULLIF(pickup_date,''),created_at)) BETWEEN date(?) AND date(?)
                            ORDER BY destination_branch,date(COALESCE(NULLIF(pickup_date,''),created_at))""",(date_from,date_to)).fetchall()

    def disposal_already_done_practices(self,c,date_from,date_to):
        return c.execute("""SELECT * FROM practices WHERE (deleted_at IS NULL OR deleted_at='')
                            AND service_type='Cremazione collettiva' AND status='Smaltito'
                            AND date(COALESCE(NULLIF(pickup_date,''),created_at)) BETWEEN date(?) AND date(?)
                            ORDER BY destination_branch,date(COALESCE(NULLIF(pickup_date,''),created_at))""",(date_from,date_to)).fetchall()

    def disposal_page(self,user,error=""):
        q=parse_qs(urlparse(self.path).query)
        today=rome_now().date(); default_from=today-timedelta(days=28)
        date_from=(q.get("dal") or [default_from.isoformat()])[0].strip()
        date_to=(q.get("al") or [today.isoformat()])[0].strip()
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from): date_from=default_from.isoformat()
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to): date_to=today.isoformat()
        stato_filter=(q.get("stato") or [""])[0].strip()
        if stato_filter not in ("","da_confermare","smaltito"): stato_filter=""
        with db() as c:
            eligible=self.disposal_eligible_practices(c,date_from,date_to)
            already_done=self.disposal_already_done_practices(c,date_from,date_to)
            history=c.execute("""SELECT b.*,u.display_name FROM disposal_batches b LEFT JOIN users u ON u.id=b.confirmed_by
                                 ORDER BY b.confirmed_at DESC""").fetchall()
        def build_groups(pending_rows,done_rows):
            groups={}
            for row in pending_rows:
                branch=row["destination_branch"] or "Non indicata"
                channel=payment_channel(row)
                groups.setdefault((branch,channel),{"pending":[],"done":[]})["pending"].append(row)
            for row in done_rows:
                branch=row["destination_branch"] or "Non indicata"
                channel=payment_channel(row)
                groups.setdefault((branch,channel),{"pending":[],"done":[]})["done"].append(row)
            return groups
        full_groups=build_groups(eligible,already_done)
        show_pending=stato_filter!="smaltito"
        show_done=stato_filter!="da_confermare"
        display_groups=build_groups(eligible if show_pending else [],already_done if show_done else [])
        def disposal_row_html(r,status_label,status_class):
            weight=money_value(r["estimated_weight"]) if r["estimated_weight"] else 0.0
            weight_cell=kg_it(weight) if weight else '<span class="sub">-</span>'
            url=f'/pratiche/{r["id"]}?return_to={quote(getattr(self,"path",""),safe="")}'
            animal_cell=esc(r["species"]) if r["species"] else '<span class="sub">-</span>'
            return f'''<tr class="practice-row-link" {row_open_attrs(url,f'Apri pratica {r["practice_number"]}')}><td>{animal_cell}</td><td>{weight_cell}</td><td>{esc(self.disposal_contact_for(r))}</td><td>{esc(date_it(r["pickup_date"] or r["created_at"]))}</td><td><a href="{url}">{esc(r["practice_number"])}</a></td><td><span class="badge {status_class}">{status_label}</span></td></tr>'''
        group_sections=[]
        for (branch,channel),data in sorted(display_groups.items(),key=lambda item:(item[0][0],item[0][1])):
            rows_html=''.join(disposal_row_html(r,"Da confermare","tag-orange") for r in data["pending"])+''.join(disposal_row_html(r,"Già smaltita","tag-green") for r in data["done"])
            group_total=len(data["pending"])+len(data["done"])
            group_kg=sum(money_value(r["estimated_weight"]) for r in data["pending"]+data["done"] if r["estimated_weight"])
            total_row=f'<tr class="disposal-group-total"><td><b>Totale</b></td><td><b>{kg_it(group_kg)}</b></td><td colspan="4"></td></tr>'
            group_sections.append(f'''<section class="tablebox disposal-group"><div class="section-collapse-head"><h2>{esc(branch)} · Circuito {esc(channel)}</h2><span class="badge">{group_total} animali</span><button type="button" class="collapse-toggle" aria-expanded="true" onclick="toggleCollapsibleSection(this)">−</button></div><div class="collapsible-body"><table><thead><tr><th>Animale</th><th>Peso</th><th>Proprietario/Veterinario</th><th>Data recupero</th><th>Pratica</th><th>Stato</th></tr></thead><tbody>{rows_html}{total_row}</tbody></table></div></section>''')
        filter_note='<p class="sub">Nessuna pratica corrisponde al filtro di stato selezionato per questo periodo.</p>' if not display_groups and full_groups else ''
        total_count=len(eligible)
        total_already=len(already_done)
        breakdown_summary=''.join(f'<div class="kv"><small>{esc(branch)} · Circuito {esc(channel)}</small><b>{len(data["pending"])+len(data["done"])}</b><small>{len(data["pending"])} da confermare · {len(data["done"])} già smaltite</small></div>' for (branch,channel),data in sorted(full_groups.items(),key=lambda item:(item[0][0],item[0][1])))
        error_html=f'<div class="flash warning">{esc(error)}</div>' if error else ''
        if total_count:
            confirm_form=f'''<form method="post" action="/smaltimenti/conferma" onsubmit="return confirm('Sei sicuro? Questa azione cambierà lo stato di {total_count} pratiche in Smaltito')"><input type="hidden" name="dal" value="{esc(date_from)}"><input type="hidden" name="al" value="{esc(date_to)}"><button class="btn">Conferma scarico</button></form>'''
        elif total_already:
            confirm_form='<p class="sub">Nessuna pratica da confermare nel periodo selezionato: quelle elencate sopra risultano già smaltite.</p>'
        else:
            confirm_form='<p class="sub">Nessuna pratica di cremazione collettiva da smaltire nel periodo selezionato.</p>'
        history_rows=''.join(f'''<tr><td>{esc(date_it(b["confirmed_at"]))}</td><td>{esc(date_it(b["period_from"]))} → {esc(date_it(b["period_to"]))}</td><td><b>{b["total_count"]}</b></td><td>{esc(b["display_name"] or "-")}</td><td><a class="btn ghost" href="/smaltimenti/storico/{b["id"]}">Apri</a></td></tr>''' for b in history) or '<tr><td colspan="5" class="sub">Nessuno scarico registrato.</td></tr>'
        stato_options=''.join(f'<option value="{esc(value)}"{" selected" if stato_filter==value else ""}>{esc(label)}</option>' for value,label in (("","Tutte"),("da_confermare","Da confermare"),("smaltito","Già smaltite")))
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Smaltimenti</h1><p class="sub">Conferimenti periodici delle cremazioni collettive alla ditta esterna di smaltimento.</p></div></div>{error_html}<section class="section"><h2>Periodo</h2><form method="get"><div class="fields"><div class="field"><label>Dal</label><input type="date" name="dal" value="{esc(date_from)}"></div><div class="field"><label>Al</label><input type="date" name="al" value="{esc(date_to)}"></div><div class="field"><label>Stato pratica</label><select name="stato">{stato_options}</select></div></div><button class="btn" style="margin-top:12px">Applica periodo</button></form></section><section class="section"><h2>Riepilogo periodo {esc(date_it(date_from))} - {esc(date_it(date_to))}</h2><div class="kvs">{breakdown_summary or '<span class="sub">Nessun dato per il periodo selezionato.</span>'}<div class="kv"><small>Totale generale</small><b>{total_count+total_already}</b><small>{total_count} da confermare · {total_already} già smaltite</small></div></div><div class="actions" style="margin-top:14px">{confirm_form}</div></section>{filter_note}{''.join(group_sections)}<section class="tablebox"><div class="section-collapse-head"><h2>Storico scarichi</h2><button type="button" class="collapse-toggle" aria-expanded="true" onclick="toggleCollapsibleSection(this)">−</button></div><div class="collapsible-body"><table><thead><tr><th>Data conferma</th><th>Periodo</th><th>Totale animali</th><th>Confermato da</th><th></th></tr></thead><tbody>{history_rows}</tbody></table></div></section></main>'''
        self.send_html(layout("Smaltimenti",body,user))

    def disposal_confirm(self,user):
        f=self.form()
        date_from=f.get("dal","").strip(); date_to=f.get("al","").strip()
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to):
            return self.disposal_page(user,error="Periodo non valido.")
        with db() as c:
            eligible=self.disposal_eligible_practices(c,date_from,date_to)
            if not eligible:
                return self.disposal_page(user,error="Nessuna pratica di cremazione collettiva da smaltire nel periodo selezionato.")
            breakdown={}
            for row in eligible:
                branch=row["destination_branch"] or "Non indicata"
                channel=payment_channel(row)
                key=f"{branch}|{channel}"
                breakdown[key]=breakdown.get(key,0)+1
            stamp=now()
            cur=c.execute("INSERT INTO disposal_batches(period_from,period_to,confirmed_at,confirmed_by,total_count,breakdown_json) VALUES(?,?,?,?,?,?)",
                          (date_from,date_to,stamp,user["id"],len(eligible),json.dumps(breakdown,ensure_ascii=False)))
            batch_id=cur.lastrowid
            for row in eligible:
                c.execute("INSERT INTO disposal_batch_practices(batch_id,practice_id) VALUES(?,?)",(batch_id,row["id"]))
                c.execute("UPDATE practices SET status='Smaltito',updated_at=? WHERE id=?",(stamp,row["id"]))
                c.execute("INSERT INTO practice_history(practice_id,event_type,old_value,new_value,note,user_id,created_at) VALUES(?,?,?,?,?,?,?)",
                          (row["id"],"Smaltimento",row["status"],"Smaltito",f"Scarico #{batch_id} ({date_from} → {date_to})",user["id"],stamp))
        self.redirect(f"/smaltimenti/storico/{batch_id}")

    def disposal_batch_detail(self,user,batch_id):
        with db() as c:
            batch=c.execute("SELECT b.*,u.display_name FROM disposal_batches b LEFT JOIN users u ON u.id=b.confirmed_by WHERE b.id=?",(batch_id,)).fetchone()
            if not batch:return self.send_error(404)
            practices=c.execute("""SELECT p.* FROM disposal_batch_practices dbp JOIN practices p ON p.id=dbp.practice_id
                                   WHERE dbp.batch_id=? ORDER BY p.destination_branch,p.pickup_date""",(batch_id,)).fetchall()
        try:
            breakdown=json.loads(batch["breakdown_json"] or "{}")
        except (ValueError,TypeError):
            breakdown={}
        breakdown_html=''.join(f'<div class="kv"><small>{esc(key.replace("|"," · Circuito "))}</small><b>{count}</b></div>' for key,count in breakdown.items())
        weight_groups={}
        for r in practices:
            branch=r["destination_branch"] or "Non indicata"
            channel=payment_channel(r)
            weight_groups.setdefault((branch,channel),[]).append(r)
        row_parts=[]; grand_kg=0.0
        for (branch,channel),rows in sorted(weight_groups.items(),key=lambda item:(item[0][0],item[0][1])):
            group_kg=0.0
            for r in rows:
                weight=money_value(r["estimated_weight"]) if r["estimated_weight"] else 0.0
                group_kg+=weight
                weight_cell=kg_it(weight) if weight else '<span class="sub">-</span>'
                url=f'/pratiche/{r["id"]}?return_to={quote(getattr(self,"path",""),safe="")}'
                animal_cell=esc(r["species"]) if r["species"] else '<span class="sub">-</span>'
                row_parts.append(f'''<tr class="practice-row-link" {row_open_attrs(url,f'Apri pratica {r["practice_number"]}')}><td>{esc(r["destination_branch"] or "-")}</td><td>{animal_cell}</td><td>{weight_cell}</td><td>{esc(self.disposal_contact_for(r))}</td><td>{esc(date_it(r["pickup_date"] or r["created_at"]))}</td><td><a href="{url}">{esc(r["practice_number"])}</a></td></tr>''')
            grand_kg+=group_kg
            row_parts.append(f'<tr class="disposal-group-total"><td colspan="2"><b>Totale {esc(branch)} · Circuito {esc(channel)}</b></td><td><b>{kg_it(group_kg)}</b></td><td colspan="3"></td></tr>')
        if practices:
            row_parts.append(f'<tr class="disposal-grand-total"><td colspan="2"><b>Totale generale</b></td><td><b>{kg_it(grand_kg)}</b></td><td colspan="3"></td></tr>')
        rows_html=''.join(row_parts) or '<tr><td colspan="6" class="sub">Nessuna pratica collegata.</td></tr>'
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Scarico del {esc(date_it(batch["confirmed_at"]))}</h1><p class="sub">Periodo {esc(date_it(batch["period_from"]))} → {esc(date_it(batch["period_to"]))} · confermato da {esc(batch["display_name"] or "-")}</p></div><a class="btn ghost" href="/smaltimenti">Torna a Smaltimenti</a></div><section class="section"><h2>Riepilogo</h2><div class="kvs">{breakdown_html}<div class="kv"><small>Totale generale</small><b>{batch["total_count"]}</b></div></div></section><section class="tablebox"><table><thead><tr><th>Sede</th><th>Animale</th><th>Peso</th><th>Proprietario/Veterinario</th><th>Data recupero</th><th>Pratica</th></tr></thead><tbody>{rows_html}</tbody></table></section></main>'''
        self.send_html(layout("Dettaglio scarico",body,user))

    def payment_overview_legacy(self,user,kind):
        specs={
            "da-saldare":("Da saldare",lambda row: outstanding_amount(row)>0,lambda row: outstanding_amount(row)),
            "acconti":("Acconti",lambda row: received_amount(row)>0 and outstanding_amount(row)>0,lambda row: received_amount(row)),
            "pagati":("Pagati",lambda row: (row["payment_status"] or "")=="Pagato",lambda row: received_amount(row)),
        }
        title,include,amount_for=specs[kind]
        with db() as c:
            rows=c.execute("SELECT * FROM practices WHERE deleted_at IS NULL OR deleted_at='' ORDER BY updated_at DESC,id DESC").fetchall()
            collaborator_ids={int(row["collaborator_id"]) for row in rows if "collaborator_id" in row.keys() and row["collaborator_id"]}
            collaborator_codes={}
            if collaborator_ids:
                marks=','.join('?' for _ in collaborator_ids)
                collaborator_codes={r["id"]:(r["code"] or "") for r in c.execute(f"SELECT id,code FROM collaborators WHERE id IN ({marks})",tuple(collaborator_ids))}
        groups=[(False,title,"#3b82f6"),(True,f"{title} D","#f59e0b")]; sections=[]
        for is_d,label,color in groups:
            selected=[row for row in rows if include(row) and uses_total_d(row)==is_d]; total=sum(amount_for(row) for row in selected)
            body=[]
            for row in selected:
                owner=((row["owner_first_name"] or "")+" "+(row["owner_last_name"] or "")).strip()
                if "collaborator_name" in row.keys() and row["collaborator_name"]:
                    owner=row["collaborator_name"]
                collab_code=collaborator_codes.get(int(row["collaborator_id"])) if "collaborator_id" in row.keys() and row["collaborator_id"] else ""
                animal_prefix=f"{esc(collab_code)} " if collab_code else ""
                url=f'/pratiche/{row["id"]}'
                body.append(f'''<tr class="practice-row-link" {row_open_attrs(url,f'Apri pratica {row["practice_number"]}')}><td><a href="{url}"><b>{esc(row["practice_number"])}</b></a></td><td>{animal_prefix}{esc(row["animal_name"] or "")}</td><td>{esc(owner)}</td><td>{money_it(effective_total(row))}</td><td>{money_it(money_value(row["deposit"]))}</td><td><b>{money_it(amount_for(row))}</b></td><td>{esc(row["payment_status"] or "Da saldare")}</td><td><a class="btn ghost" href="{url}">Apri</a></td></tr>''')
            table=''.join(body) or '<tr><td colspan="8" class="sub">Nessuna pratica in questa categoria.</td></tr>'
            sections.append(f'''<section class="dashboard-panel" style="margin-bottom:20px;border-top:4px solid {color}"><header><div><h2>{esc(label)}</h2><p>{len(selected)} pratiche</p></div><strong>{money_it(total)}</strong></header><div class="tablebox"><table><thead><tr><th>Pratica</th><th>Animale</th><th>Cliente</th><th>Totale</th><th>Acconto</th><th>{esc(title)}</th><th>Stato</th><th></th></tr></thead><tbody>{table}</tbody></table></div></section>''')
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Pagamenti · {esc(title)}</h1><p class="sub">Separazione tra Totale W e Totale D (contanti).</p></div><a class="btn ghost" href="/">Dashboard</a></div>{''.join(sections)}</main>'''
        self.send_html(layout(f"Pagamenti · {title}",body,user))

    def payment_overview(self,user,kind):
        titles={"da-saldare":"Da saldare","acconti":"Acconti","pagati":"Pagati","totale-incassato":"Totale incassato"};title=titles[kind]
        q=parse_qs(urlparse(self.path).query);today=rome_now().date()
        period,date_from,date_to=dashboard_period_bounds((q.get("periodo") or ["oggi"])[0],today)
        raw_from=(q.get("dal") or [date_from.isoformat()])[0];raw_to=(q.get("al") or [date_to.isoformat()])[0]
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",raw_from):date_from=datetime.strptime(raw_from,"%Y-%m-%d").date()
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",raw_to):date_to=datetime.strptime(raw_to,"%Y-%m-%d").date()
        if kind=="da-saldare":
            with db() as c:
                rows=c.execute("SELECT * FROM practices WHERE (deleted_at IS NULL OR deleted_at='') AND COALESCE(payment_status,'Da saldare')!='Pagato' ORDER BY updated_at DESC,id DESC").fetchall()
            rows=[row for row in rows if outstanding_amount(row)>0]
            collaborator_ids={int(row["collaborator_id"]) for row in rows if "collaborator_id" in row.keys() and row["collaborator_id"]}
            collaborator_codes={}
            if collaborator_ids:
                marks=','.join('?' for _ in collaborator_ids)
                with db() as c:collaborator_codes={r["id"]:(r["code"] or "") for r in c.execute(f"SELECT id,code FROM collaborators WHERE id IN ({marks})",tuple(collaborator_ids))}
            groups=[(False,title,"#3b82f6"),(True,f"{title} D","#f59e0b")];sections=[]
            for is_d,label,color in groups:
                selected=[row for row in rows if uses_total_d(row)==is_d];total=sum(outstanding_amount(row) for row in selected);table_rows=[]
                for row in selected:
                    owner=((row["owner_first_name"] or "")+" "+(row["owner_last_name"] or "")).strip()
                    if "collaborator_name" in row.keys() and row["collaborator_name"]:
                        owner=row["collaborator_name"]
                    collab_code=collaborator_codes.get(int(row["collaborator_id"])) if "collaborator_id" in row.keys() and row["collaborator_id"] else ""
                    animal_prefix=f"{esc(collab_code)} " if collab_code else ""
                    url=f'/pratiche/{row["id"]}?return_to={quote(self.path,safe="")}'
                    animal_cell=esc(row["species"]) if (row["service_type"] or "")=="Cremazione collettiva" else f'{animal_prefix}{esc(row["animal_name"] or "")}'
                    table_rows.append(f'''<tr class="practice-row-link" {row_open_attrs(url,f'Apri pratica {row["practice_number"]}')}><td>Aperta</td><td><a href="{url}"><b>{esc(row["practice_number"])}</b></a></td><td>{animal_cell}</td><td>{esc(owner)}</td><td>{money_it(effective_total(row))}</td><td>{money_it(channel_deposit(row))}</td><td><b>{money_it(outstanding_amount(row))}</b></td><td>{esc(row["payment_status"] or "Da saldare")}</td><td><a class="btn ghost" href="{url}">Apri</a></td></tr>''')
                table=''.join(table_rows) or '<tr><td colspan="9" class="sub">Nessuna pratica in questa categoria.</td></tr>'
                sections.append(f'''<section class="dashboard-panel" style="margin-bottom:20px;border-top:4px solid {color}"><header><div><h2>{esc(label)}</h2><p>{len(selected)} pratiche</p></div><strong>{money_it(total)}</strong></header><div class="tablebox"><table><thead><tr><th>Data economica</th><th>Pratica</th><th>Animale</th><th>Cliente</th><th>Totale</th><th>Acconto</th><th>{esc(title)}</th><th>Stato</th><th></th></tr></thead><tbody>{table}</tbody></table></div></section>''')
            period_note="Tutte le rimanenze attualmente aperte: non esiste una scadenza di saldo."
            body=f'''<main class="wrap"><div class="titlebar"><div><h1>Pagamenti · {esc(title)}</h1><p class="sub">Separazione tra Totale W e Totale D (contanti). {esc(period_note)}</p></div><a class="btn ghost" href="/?pratiche_periodo=oggi&amp;pagamenti_periodo={period}">Dashboard</a></div>{''.join(sections)}</main>'''
            self.send_html(layout(f"Pagamenti · {title}",body,user))
            return
        # Acconti / Pagati / Totale incassato: stessa fonte, stesso filtro
        # data e stessa esclusione storni della card corrispondente in
        # dashboard() (dashboard_payment_movements) — un movimento per
        # riga, mai il totale/acconto/rimanenza denormalizzato della
        # pratica, cosi' il conteggio e l'importo del dettaglio coincidono
        # sempre esattamente con quelli mostrati sulla card che apre questa
        # pagina.
        with db() as c:
            movements=dashboard_payment_movements(c,date_from,date_to)
        if kind=="acconti":
            movements=[m for m in movements if m["movement_type"]=="Acconto"]
        elif kind=="pagati":
            movements=[m for m in movements if m["movement_type"] in ("Saldo","Incasso completo")]
        # kind=="totale-incassato": nessun filtro aggiuntivo, tutti i movimenti del periodo
        groups=[(False,title,"#3b82f6"),(True,f"{title} D","#f59e0b")];sections=[]
        for is_d,label,color in groups:
            channel="D" if is_d else "W"
            selected=[m for m in movements if m["category"]==channel]
            total=sum(dashboard_payment_row_amount(m) for m in selected)
            table_rows=[]
            for m in selected:
                url=f'/pratiche/{m["practice_id"]}?return_to={quote(self.path,safe="")}'
                animal_cell=esc(m["species"]) if (m["service_type"] or "")=="Cremazione collettiva" else esc(m["animal_name"] or "")
                movement_type_label=m["movement_type"]
                table_rows.append(f'''<tr class="practice-row-link" {row_open_attrs(url,f'Apri pratica {m["practice_number"]}')}><td>{esc(date_it(m["movement_date"]))}</td><td><a href="{url}"><b>{esc(m["practice_number"])}</b></a></td><td>{animal_cell}</td><td>{esc(dashboard_payment_row_owner(m))}</td><td>{esc(movement_type_label)}</td><td>{esc(channel)}</td><td><b>{money_it(dashboard_payment_row_amount(m))}</b></td><td><a class="btn ghost" href="{url}">Apri</a></td></tr>''')
            table=''.join(table_rows) or '<tr><td colspan="8" class="sub">Nessun movimento in questa categoria.</td></tr>'
            sections.append(f'''<section class="dashboard-panel" style="margin-bottom:20px;border-top:4px solid {color}"><header><div><h2>{esc(label)}</h2><p>{len(selected)} movimenti</p></div><strong>{money_it(total)}</strong></header><div class="tablebox"><table><thead><tr><th>Data economica</th><th>Pratica</th><th>Animale</th><th>Cliente</th><th>Tipo movimento</th><th>Circuito</th><th>Importo</th><th></th></tr></thead><tbody>{table}</tbody></table></div></section>''')
        period_note=f"Incassi registrati dal {date_it(date_from.isoformat())} al {date_it(date_to.isoformat())}."
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Pagamenti · {esc(title)}</h1><p class="sub">Separazione tra Totale W e Totale D (contanti). {esc(period_note)}</p></div><a class="btn ghost" href="/?pratiche_periodo=oggi&amp;pagamenti_periodo={period}">Dashboard</a></div>{''.join(sections)}</main>'''
        self.send_html(layout(f"Pagamenti · {title}",body,user))

    def orders_page_legacy(self,user):
        q=parse_qs(urlparse(self.path).query);date_from=(q.get("dal") or [""])[0].strip();date_to=(q.get("al") or [""])[0].strip();status=(q.get("stato") or [""])[0].strip();draft_id=(q.get("bozza") or [""])[0].strip()
        statuses=("Bozza","Invio in corso","Inviato","Fallito")
        if status not in statuses:status=""
        where=["o.archived_at IS NULL"];args=[]
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from):where.append("date(o.created_at)>=date(?)");args.append(date_from)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to):where.append("date(o.created_at)<=date(?)");args.append(date_to)
        if status:where.append("o.status=?");args.append(status)
        with db() as c:
            recipient_row=c.execute("SELECT value FROM settings WHERE key='order_recipient_email'").fetchone();recipient=recipient_row["value"] if recipient_row else ""
            rows=c.execute(f"""SELECT o.*,u.display_name operator_name FROM email_orders o JOIN users u ON u.id=o.operator_id
                               WHERE {' AND '.join(where)} ORDER BY o.created_at DESC,o.id DESC""",args).fetchall()
            draft=c.execute("SELECT * FROM email_orders WHERE id=? AND status='Bozza' AND archived_at IS NULL",(int(draft_id),)).fetchone() if draft_id.isdigit() else None
        quantity=draft["quantity"] if draft else 1;notes=draft["notes"] if draft else "";preview=water_order_body(quantity,notes)
        options='<option value="">Tutti gli esiti</option>'+''.join(f'<option value="{item}" {"selected" if status==item else ""}>{item}</option>' for item in statuses)
        history=[]
        for row in rows:
            badge={"Bozza":"tag-yellow","Invio in corso":"tag-blue","Inviato":"tag-green","Fallito":"tag-red"}.get(row["status"],"")
            history.append(f'''<tr><td>{esc(date_it(row["created_at"]))}<br><small>{esc((row["created_at"] or "")[11:16])}</small></td><td>{esc(row["operator_name"])}</td><td>{row["quantity"]}</td><td>{esc(row["recipient"])}</td><td><span class="badge {badge}">{esc(row["status"])}</span></td><td><a class="btn ghost" href="/ordini/{row["id"]}">Apri</a></td></tr>''')
        table=''.join(history) or '<tr><td colspan="6" class="sub">Nessun ordine trovato.</td></tr>'
        invalid_recipient=not valid_email_address(recipient)
        warning='<div class="flash warning">Configura un indirizzo valido in <a href="/impostazioni"><b>Impostazioni</b></a> prima di inviare.</div>' if invalid_recipient else ''
        body=f'''<main class="wrap orders-wrap"><div class="titlebar"><div><h1>Ordini</h1><p class="sub">Invio ordini tramite l'account email aziendale.</p></div></div>{warning}<section class="section order-compose"><h2>Ordine acqua</h2><form method="post" action="/ordini/invia" data-recipient="{esc(recipient)}" onsubmit="return confirmOrderSubmission(this)"><input type="hidden" name="confirm_send" value=""><input type="hidden" name="source_order_id" value="{draft['id'] if draft else ''}"><div class="fields"><div class="field"><label>Numero boccioni</label><input type="number" name="quantity" min="1" step="1" value="{quantity}" required inputmode="numeric" oninput="updateOrderPreview(this.form)"></div><div class="field"><label>Destinatario attualmente configurato</label><input value="{esc(recipient)}" readonly></div><div class="field full"><label>Note opzionali</label><textarea name="notes" maxlength="2000" oninput="updateOrderPreview(this.form)">{esc(notes)}</textarea></div><div class="field full"><label>Oggetto email</label><input name="subject_preview" value="{esc(ORDER_EMAIL_SUBJECT)}" readonly></div><div class="field full"><label>Anteprima del testo della mail</label><pre class="order-preview" aria-live="polite">{esc(preview)}</pre></div></div><button class="btn" {'disabled' if invalid_recipient else ''}>Invia ordine</button></form></section><section class="search-after-results"><h2>Storico ordini</h2><form class="section" method="get"><div class="fields"><div class="field"><label>Dal</label><input type="date" name="dal" value="{esc(date_from)}"></div><div class="field"><label>Al</label><input type="date" name="al" value="{esc(date_to)}"></div><div class="field"><label>Esito</label><select name="stato">{options}</select></div></div><button class="btn" style="margin-top:12px">Filtra</button><a class="btn ghost" style="margin-top:12px" href="/ordini">Pulisci</a></form></section><div class="tablebox"><table><thead><tr><th>Data e ora</th><th>Operatore</th><th>Quantità</th><th>Destinatario</th><th>Esito</th><th></th></tr></thead><tbody>{table}</tbody></table></div></main>'''
        self.send_html(layout("Ordini",body,user))

    def order_confirmation_modal(self):
        return '''<div class="order-modal" id="orderConfirmModal" hidden role="dialog" aria-modal="true" aria-labelledby="orderConfirmTitle"><div class="order-modal-card"><h2 id="orderConfirmTitle">Conferma ordine</h2><p class="sub">Controlla i dati prima dell'invio.</p><div class="kvs"><div class="kv"><small>Quantità</small><b data-order-confirm="quantity"></b></div><div class="kv"><small>Destinatario</small><b data-order-confirm="recipient"></b></div><div class="kv"><small>Oggetto</small><b data-order-confirm="subject"></b></div></div><h3>Anteprima messaggio</h3><pre class="order-preview" data-order-confirm="preview"></pre><div class="actions"><button class="btn ghost" type="button" onclick="closeOrderConfirmation()">Annulla</button><button class="btn" type="button" data-order-confirm-button onclick="confirmAndSubmitOrder()">Conferma e invia</button></div></div></div>'''

    def orders_page(self,user):
        q=parse_qs(urlparse(self.path).query);draft_id=(q.get("bozza") or [""])[0].strip();result=(q.get("esito") or [""])[0].strip();order_id=(q.get("ordine") or [""])[0].strip()
        with db() as c:
            settings=order_email_settings(c)
            draft=c.execute("SELECT * FROM email_orders WHERE id=? AND status='Bozza' AND archived_at IS NULL",(int(draft_id),)).fetchone() if draft_id.isdigit() else None
            recent=c.execute("""SELECT o.*,u.display_name operator_name FROM email_orders o JOIN users u ON u.id=o.operator_id
                                WHERE o.archived_at IS NULL ORDER BY o.created_at DESC,o.id DESC LIMIT 5""").fetchall()
            last_sent=c.execute("SELECT * FROM email_orders WHERE status='Inviato' AND archived_at IS NULL ORDER BY sent_at DESC,id DESC LIMIT 1").fetchone()
            failed=c.execute("SELECT error_message FROM email_orders WHERE id=? AND status='Fallito'",(int(order_id),)).fetchone() if order_id.isdigit() else None
        requested=(q.get("quantita") or [""])[0]
        try:quantity=int(requested)
        except (TypeError,ValueError):quantity=draft["quantity"] if draft else 1
        quantity=max(1,min(999,quantity));recipient=settings["order_recipient_email"].strip();subject,preview=render_order_email(987654,settings);preview_template=preview.replace("987654","__QUANTITY__")
        invalid=not valid_email_address(recipient);is_admin=user["role"]=="admin"
        if result=="inviato":flash='<div class="flash">Ordine inviato correttamente.</div>'
        elif result=="fallito":flash=f'<div class="flash warning"><b>Invio non riuscito.</b> {esc((failed["error_message"] if failed else "Riprova tra poco."))}</div>'
        else:flash=""
        if invalid:flash+='<div class="flash warning">Il destinatario ordini non è configurato correttamente. '+('<a href="/ordini/impostazioni"><b>Apri le impostazioni</b></a>.' if is_admin else 'Contatta un amministratore.')+'</div>'
        rows=[]
        for row in recent:
            badge={"Bozza":"tag-yellow","Invio in corso":"tag-blue","Inviato":"tag-green","Fallito":"tag-red"}.get(row["status"],"")
            rows.append(f'''<tr><td>{esc(date_it(row["created_at"]))}<br><small>{esc((row["created_at"] or "")[11:16])}</small></td><td>{row["quantity"]}</td><td>{esc(row["recipient"])}</td><td><span class="badge {badge}">{esc(row["status"])}</span></td><td><a class="btn ghost" href="/ordini/{row["id"]}">Apri</a></td></tr>''')
        table=''.join(rows) or '<tr><td colspan="5" class="sub">Nessun ordine registrato.</td></tr>'
        last=(f'Ultimo ordine inviato: <b>{esc(date_it(last_sent["sent_at"]))} alle {esc((last_sent["sent_at"] or "")[11:16])}</b> · {last_sent["quantity"]} boccioni' if last_sent else 'Nessun ordine ancora inviato')
        settings_link='<a class="btn ghost" href="/ordini/impostazioni">Modifica impostazioni</a>' if is_admin else ''
        body=f'''<main class="wrap orders-wrap"><section class="section water-order-card"><h1>Ordina boccioni d’acqua</h1><p class="sub">Seleziona la quantità e invia l’ordine al fornitore</p>{flash}<form method="post" action="/ordini/invia" data-recipient="{esc(recipient)}" data-subject="{esc(subject)}" data-preview="{esc(preview_template)}" onsubmit="return openOrderConfirmation(this,event)"><input type="hidden" name="confirm_send"><input type="hidden" name="source_order_id" value="{draft['id'] if draft else ''}"><div class="quantity-stepper"><button class="btn ghost" type="button" aria-label="Diminuisci quantità" onclick="adjustOrderQuantity(this.form,-1)">−</button><input aria-label="Numero boccioni" type="number" name="quantity" min="1" max="999" step="1" value="{quantity}" inputmode="numeric" required onblur="normalizeOrderQuantity(this,this.value)"><button class="btn ghost" type="button" aria-label="Aumenta quantità" onclick="adjustOrderQuantity(this.form,1)">+</button></div><div class="quick-quantities" aria-label="Quantità rapide"><button class="btn ghost" type="button" onclick="setOrderQuantity(this.form,3)">3 boccioni</button><button class="btn ghost" type="button" onclick="setOrderQuantity(this.form,5)">5 boccioni</button><button class="btn ghost" type="button" onclick="setOrderQuantity(this.form,10)">10 boccioni</button></div><button class="btn order-now" {'disabled' if invalid else ''}>Ordina adesso</button></form><p class="last-order sub">{last}</p><div class="order-secondary-actions">{settings_link}</div></section><section class="recent-orders"><div class="titlebar"><div><h2>Ultimi ordini</h2><p class="sub">Gli ultimi 5 ordini registrati.</p></div><a class="btn ghost" href="/ordini/storico">Vedi tutti gli ordini</a></div><div class="tablebox"><table><thead><tr><th>Data e ora</th><th>Quantità</th><th>Destinatario</th><th>Stato</th><th></th></tr></thead><tbody>{table}</tbody></table></div></section>{self.order_confirmation_modal()}</main>'''
        self.send_html(layout("Ordini",body,user))

    def orders_history_page(self,user):
        q=parse_qs(urlparse(self.path).query);date_from=(q.get("dal") or [""])[0].strip();date_to=(q.get("al") or [""])[0].strip();status=(q.get("stato") or [""])[0].strip();statuses=("Bozza","Invio in corso","Inviato","Fallito")
        if status not in statuses:status=""
        where=["o.archived_at IS NULL"];args=[]
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from):where.append("date(o.created_at)>=date(?)");args.append(date_from)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to):where.append("date(o.created_at)<=date(?)");args.append(date_to)
        if status:where.append("o.status=?");args.append(status)
        with db() as c:
            settings=order_email_settings(c);rows=c.execute(f"""SELECT o.*,u.display_name operator_name FROM email_orders o JOIN users u ON u.id=o.operator_id WHERE {' AND '.join(where)} ORDER BY o.created_at DESC,o.id DESC""",args).fetchall()
        recipient=settings["order_recipient_email"];subject,preview=render_order_email(987654,settings);preview=preview.replace("987654","__QUANTITY__")
        options='<option value="">Tutti gli esiti</option>'+''.join(f'<option value="{item}" {"selected" if status==item else ""}>{item}</option>' for item in statuses);table_rows=[]
        for row in rows:
            badge={"Bozza":"tag-yellow","Invio in corso":"tag-blue","Inviato":"tag-green","Fallito":"tag-red"}.get(row["status"],"");error=esc(row["error_message"] or "-")
            duplicate=f'''<form method="post" action="/ordini/{row['id']}/duplica"><button class="btn ghost">Duplica</button></form>'''
            resend=f'''<form method="post" action="/ordini/{row['id']}/reinvia" data-recipient="{esc(recipient)}" data-subject="{esc(subject)}" data-preview="{esc(preview)}" onsubmit="return openOrderConfirmation(this,event)"><input type="hidden" name="confirm_send"><input type="hidden" name="quantity" value="{row['quantity']}"><button class="btn">Reinvia</button></form>''' if row["status"]=="Fallito" else ""
            table_rows.append(f'''<tr><td>{esc(date_it(row["created_at"]))}<br><small>{esc((row["created_at"] or "")[11:16])}</small></td><td>{row["quantity"]}</td><td>{esc(row["recipient"])}</td><td>{esc(row["subject"])}</td><td>{esc(row["operator_name"])}</td><td><span class="badge {badge}">{esc(row["status"])}</span></td><td>{error}</td><td><div class="actions"><a class="btn ghost" href="/ordini/{row['id']}">Apri</a>{duplicate}{resend}</div></td></tr>''')
        table=''.join(table_rows) or '<tr><td colspan="8" class="sub">Nessun ordine trovato.</td></tr>'
        body=f'''<main class="wrap orders-wrap"><div class="titlebar"><div><h1>Storico ordini</h1><p class="sub">Consulta, duplica o riprova gli ordini falliti.</p></div><a class="btn ghost" href="/ordini">Torna a Ordine acqua</a></div><form class="section" method="get"><div class="fields"><div class="field"><label>Dal</label><input type="date" name="dal" value="{esc(date_from)}"></div><div class="field"><label>Al</label><input type="date" name="al" value="{esc(date_to)}"></div><div class="field"><label>Esito</label><select name="stato">{options}</select></div></div><div class="actions"><button class="btn">Filtra</button><a class="btn ghost" href="/ordini/storico">Pulisci</a></div></form><div class="tablebox"><table><thead><tr><th>Data e ora</th><th>Quantità</th><th>Destinatario</th><th>Oggetto</th><th>Operatore</th><th>Stato</th><th>Errore</th><th></th></tr></thead><tbody>{table}</tbody></table></div>{self.order_confirmation_modal()}</main>'''
        self.send_html(layout("Storico ordini",body,user))

    def order_settings_page(self,user,draft=None,error=""):
        if user["role"]!="admin":return self.send_error(403,"Solo gli amministratori possono modificare le impostazioni degli ordini.")
        with db() as c:settings=order_email_settings(c)
        if draft is not None:settings={**settings,**draft}
        error_html=f'<div class="flash warning">{esc(error)}</div>' if error else ''
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Impostazioni ordine acqua</h1><p class="sub">Questi dati vengono applicati automaticamente a ogni nuovo ordine.</p></div><a class="btn ghost" href="/ordini">Torna agli ordini</a></div>{error_html}<section class="section admin-order-settings"><form method="post" action="/ordini/impostazioni"><div class="fields"><div class="field full"><label>Email destinatario ordini</label><input type="email" name="order_recipient_email" value="{esc(settings['order_recipient_email'])}" required></div><div class="field full"><label>Oggetto email</label><input name="order_email_subject" value="{esc(settings['order_email_subject'])}" maxlength="200" required></div><div class="field full"><label>Testo email</label><textarea name="order_email_template" maxlength="10000" required>{esc(settings['order_email_template'])}</textarea><small class="sub">Inserisci <b>{{{{quantita}}}}</b> nel punto in cui deve apparire la quantità. Sono disponibili anche {{{{note_predefinite}}}}, {{{{firma}}}}, {{{{nome_mittente}}}} e {{{{telefono}}}}.</small></div><div class="field"><label>Firma finale</label><input name="order_email_signature" value="{esc(settings['order_email_signature'])}" maxlength="200" required></div><div class="field"><label>Nome mittente</label><input name="order_sender_name" value="{esc(settings['order_sender_name'])}" maxlength="200" required></div><div class="field"><label>Numero di telefono (opzionale)</label><input name="order_phone" value="{esc(settings['order_phone'])}" maxlength="100"></div><div class="field full"><label>Note predefinite (opzionali)</label><textarea name="order_default_notes" maxlength="2000">{esc(settings['order_default_notes'])}</textarea></div><div class="field full"><label>Mittente tecnico</label><input value="info@petparadisempoli.com" readonly><small class="sub">Le credenziali SMTP restano esclusivamente nelle variabili d’ambiente di Render e non sono mostrate qui.</small></div></div><button class="btn">Salva impostazioni</button></form></section></main>'''
        self.send_html(layout("Impostazioni ordine acqua",body,user))

    def order_detail_page(self,user,order_id):
        with db() as c:
            row=c.execute("SELECT o.*,u.display_name operator_name FROM email_orders o JOIN users u ON u.id=o.operator_id WHERE o.id=?",(order_id,)).fetchone()
            settings=order_email_settings(c)
        if not row:return self.send_error(404)
        result=(f'<div class="flash">Ordine inviato correttamente.</div>' if row["status"]=="Inviato" else f'<div class="flash warning"><b>Invio non riuscito:</b> {esc(row["error_message"] or "Errore non specificato")}</div>' if row["status"]=="Fallito" else "")
        actions=""
        if not row["archived_at"]:
            current_subject,current_preview=render_order_email(987654,settings);current_preview=current_preview.replace("987654","__QUANTITY__")
            resend=f'''<form method="post" action="/ordini/{order_id}/reinvia" data-recipient="{esc(settings['order_recipient_email'])}" data-subject="{esc(current_subject)}" data-preview="{esc(current_preview)}" onsubmit="return openOrderConfirmation(this,event)"><input type="hidden" name="confirm_send"><input type="hidden" name="quantity" value="{row['quantity']}"><button class="btn">Reinvia ordine</button></form>''' if row["status"]=="Fallito" else ""
            duplicate=f'''<form method="post" action="/ordini/{order_id}/duplica"><button class="btn ghost">Duplica ordine</button></form>'''
            archive=f'''<form method="post" action="/ordini/{order_id}/archivia" onsubmit="return confirm('Archiviare questo ordine?')"><button class="btn ghost">Archivia</button></form>'''
            actions=f'<div class="actions">{resend}{duplicate}{archive}</div>'
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Ordine #{row["id"]}</h1><p class="sub">{esc(row["status"])} · {esc(date_it(row["created_at"]))} {esc((row["created_at"] or "")[11:16])}</p></div><a class="btn ghost" href="/ordini/storico">Torna allo storico</a></div>{result}<section class="section"><div class="kvs"><div class="kv"><small>Operatore</small><b>{esc(row["operator_name"])}</b></div><div class="kv"><small>Destinatario</small><b>{esc(row["recipient"])}</b></div><div class="kv"><small>Quantità</small><b>{row["quantity"]} boccioni</b></div><div class="kv"><small>Esito</small><b>{esc(row["status"])}</b></div><div class="kv"><small>Tentativi</small><b>{row["attempt_count"]}</b></div><div class="kv"><small>Inviato il</small><b>{esc((row["sent_at"] or "").replace("T"," ") or "-")}</b></div></div><h2 style="margin-top:20px">{esc(row["subject"])}</h2><pre class="order-preview">{esc(row["body"])}</pre>{actions}</section>{self.order_confirmation_modal()}</main>'''
        self.send_html(layout(f"Ordine #{order_id}",body,user))

    def _create_and_send_order(self,user,quantity,notes,parent_order_id=None):
        with db() as c:
            settings=order_email_settings(c);recipient=settings["order_recipient_email"].strip().lower()
        if not valid_email_address(recipient):return None,"L'indirizzo destinatario ordini è vuoto o non valido. Configuralo nelle Impostazioni."
        subject,body=render_order_email(quantity,settings,notes);stamp=now()
        with db() as c:
            cur=c.execute("""INSERT INTO email_orders(order_type,quantity,notes,recipient,subject,body,status,operator_id,parent_order_id,attempt_count,created_at,updated_at)
                             VALUES('water',?,?,?,?,?,'Invio in corso',?,?,1,?,?)""",(quantity,notes,recipient,subject,body,user["id"],parent_order_id,stamp,stamp));order_id=cur.lastrowid
        try:
            send_email(recipient,subject,body,from_name=settings["order_sender_name"])
        except (EmailConfigurationError,EmailDeliveryError) as exc:
            message=str(exc)[:500]
            print(f"[ORDER_EMAIL] order_id={order_id} status=failed error={message}",flush=True)
            with db() as c:c.execute("UPDATE email_orders SET status='Fallito',error_message=?,updated_at=? WHERE id=?",(message,now(),order_id))
            return order_id,message
        except Exception as exc:
            message=f"Errore imprevisto durante l'invio email: {type(exc).__name__}."
            print(f"[ORDER_EMAIL] order_id={order_id} status=failed error={message}",flush=True)
            with db() as c:c.execute("UPDATE email_orders SET status='Fallito',error_message=?,updated_at=? WHERE id=?",(message,now(),order_id))
            return order_id,message
        sent=now()
        with db() as c:c.execute("UPDATE email_orders SET status='Inviato',sent_at=?,error_message=NULL,updated_at=? WHERE id=?",(sent,sent,order_id))
        return order_id,""

    def send_water_order(self,user):
        form=self.form()
        if form.get("confirm_send")!="SI":return self.error_page("Conferma mancante","L'email non è stata inviata perché manca la conferma esplicita.","/ordini")
        try:quantity=int(form.get("quantity",0))
        except (TypeError,ValueError):quantity=0
        if quantity<1:return self.error_page("Quantità non valida","Il numero di boccioni deve essere almeno 1.","/ordini")
        if quantity>999:return self.error_page("Quantità non valida","Il numero di boccioni è troppo elevato.","/ordini")
        parent=int(form["source_order_id"]) if str(form.get("source_order_id","")).isdigit() else None
        order_id,error=self._create_and_send_order(user,quantity,"",parent)
        if order_id and error:return self.redirect(f"/ordini?esito=fallito&ordine={order_id}&quantita={quantity}")
        if order_id:return self.redirect(f"/ordini?esito=inviato&ordine={order_id}")
        return self.error_page("Invio non disponibile",error,"/ordini")

    def order_action(self,user,order_id,action):
        with db() as c:row=c.execute("SELECT * FROM email_orders WHERE id=? AND archived_at IS NULL",(order_id,)).fetchone()
        if not row:return self.send_error(404)
        if action=="archivia":
            with db() as c:c.execute("UPDATE email_orders SET archived_at=?,updated_at=? WHERE id=?",(now(),now(),order_id))
            return self.redirect("/ordini")
        if action=="duplica":
            stamp=now()
            with db() as c:
                cur=c.execute("""INSERT INTO email_orders(order_type,quantity,notes,recipient,subject,body,status,operator_id,parent_order_id,created_at,updated_at)
                                 VALUES(?,?,?,?,?,?,'Bozza',?,?,?,?)""",(row["order_type"],row["quantity"],row["notes"],row["recipient"],row["subject"],row["body"],user["id"],order_id,stamp,stamp))
            return self.redirect(f"/ordini?bozza={cur.lastrowid}")
        if row["status"]!="Fallito":return self.error_page("Reinvio non disponibile","È possibile reinviare soltanto un ordine fallito.",f"/ordini/{order_id}")
        form=self.form()
        if form.get("confirm_send")!="SI":return self.error_page("Conferma mancante","Il reinvio richiede una conferma esplicita.",f"/ordini/{order_id}")
        new_id,error=self._create_and_send_order(user,row["quantity"],row["notes"] or "",order_id)
        if new_id and error:return self.redirect(f"/ordini?esito=fallito&ordine={new_id}&quantita={row['quantity']}")
        if new_id:return self.redirect(f"/ordini?esito=inviato&ordine={new_id}")
        return self.error_page("Invio non disponibile",error,f"/ordini/{order_id}")

    def articles_page(self,user):
        with db() as c:
            articles=c.execute("SELECT * FROM articles WHERE active=1 ORDER BY id").fetchall()
            recent=c.execute("""SELECT o.created_at,a.name,u.display_name FROM article_orders o
                                JOIN articles a ON a.id=o.article_id JOIN users u ON u.id=o.ordered_by
                                ORDER BY o.created_at DESC,o.id DESC LIMIT 10""").fetchall()
        cards=''.join(f'''<article class="article-card" id="article-{item["id"]}"><div><span class="badge tag-outline-orange">Da ordinare</span><h2>{esc(item["name"])}</h2></div><p>Invia la richiesta di ordine al centro notifiche.</p><form method="post" action="/prodotti/{item["id"]}/ordina" onsubmit="return confirm('Inviare la richiesta per {esc(item["name"])}?')"><button class="btn">Ordina prodotto</button></form></article>''' for item in articles)
        history=''.join(f'<div class="event"><b>{esc(row["name"])}</b><br><small class="sub">Richiesto da {esc(row["display_name"])} · {esc((row["created_at"] or "").replace("T"," "))}</small></div>' for row in recent) or '<p class="sub">Nessuna richiesta inviata.</p>'
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Articoli</h1><p class="sub">Seleziona un articolo sotto la voce “Da ordinare”.</p></div></div><section class="article-grid">{cards}</section><section class="section" style="margin-top:20px"><h2>Ultime richieste</h2><div class="timeline">{history}</div></section></main>'''
        body=body.replace("<h1>Articoli</h1>","<h1>Prodotti</h1>").replace("Seleziona un articolo","Seleziona un prodotto")
        self.send_html(layout("Prodotti",body,user))

    def invoices_page(self,user):
        q=parse_qs(urlparse(self.path).query); term=(q.get("q") or [""])[0].strip(); date_from=(q.get("dal") or [""])[0].strip(); date_to=(q.get("al") or [""])[0].strip()
        where=["(deleted_at IS NULL OR deleted_at='')","COALESCE(invoice_number,'')<>''"]; args=[]
        if term:
            where.append("(UNACCENT(invoice_number) LIKE ? OR UNACCENT(practice_number) LIKE ? OR UNACCENT(owner_first_name) LIKE ? OR UNACCENT(owner_last_name) LIKE ? OR UNACCENT(animal_name) LIKE ?)");args.extend([like_term(term)]*5)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from): where.append("date(invoice_date)>=date(?)");args.append(date_from)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to): where.append("date(invoice_date)<=date(?)");args.append(date_to)
        where_mi=["(p.deleted_at IS NULL OR p.deleted_at='')","COALESCE(mi.invoice_number,'')<>''"]; args_mi=[]
        if term:
            where_mi.append("(UNACCENT(mi.invoice_number) LIKE ? OR UNACCENT(p.practice_number) LIKE ? OR UNACCENT(p.owner_first_name) LIKE ? OR UNACCENT(p.owner_last_name) LIKE ? OR UNACCENT(p.animal_name) LIKE ?)");args_mi.extend([like_term(term)]*5)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_from): where_mi.append("date(mi.invoice_date)>=date(?)");args_mi.append(date_from)
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}",date_to): where_mi.append("date(mi.invoice_date)<=date(?)");args_mi.append(date_to)
        with db() as c:
            rows=c.execute(f"SELECT * FROM practices WHERE {' AND '.join(where)} ORDER BY COALESCE(NULLIF(invoice_date,''),created_at) DESC,id DESC",args).fetchall()
            movement_rows=c.execute(f"""SELECT mi.*,p.practice_number,p.owner_first_name,p.owner_last_name,p.animal_name
                                        FROM movement_invoices mi JOIN practices p ON p.id=mi.practice_id
                                        WHERE {' AND '.join(where_mi)}""",args_mi).fetchall()
            reminders=c.execute("SELECT id,practice_number,owner_first_name,owner_last_name,animal_name FROM practices WHERE (deleted_at IS NULL OR deleted_at='') AND make_invoice='Si' AND COALESCE(invoice_number,'')='' ORDER BY updated_at DESC").fetchall()
        entries=[]
        for row in rows:
            owner=((row["owner_first_name"] or "")+" "+(row["owner_last_name"] or "")).strip()
            invoice_total=money_value(row["invoice_total"]) if "invoice_total" in row.keys() and row["invoice_total"] else money_value(row["total_service"])
            entries.append({"sort_key":row["invoice_date"] or row["created_at"] or "","number":row["invoice_number"],"date":row["invoice_date"],"practice_number":row["practice_number"],"owner":owner,"animal":row["animal_name"] or "","total":invoice_total,"channel":payment_channel(row),"url":f'/pratiche/{row["id"]}?return_to={quote(getattr(self,"path",""),safe="")}'})
        for mrow in movement_rows:
            owner=((mrow["owner_first_name"] or "")+" "+(mrow["owner_last_name"] or "")).strip()
            entries.append({"sort_key":mrow["invoice_date"] or mrow["created_at"] or "","number":mrow["invoice_number"],"date":mrow["invoice_date"],"practice_number":mrow["practice_number"],"owner":owner,"animal":mrow["animal_name"] or "","total":money_value(mrow["invoice_total"]),"channel":mrow["payment_channel"] or "-","url":f'/pratiche/{mrow["practice_id"]}?return_to={quote(getattr(self,"path",""),safe="")}'})
        entries.sort(key=lambda e:e["sort_key"],reverse=True)
        table=[f'''<tr class="practice-row-link" {row_open_attrs(e["url"],f'Apri pratica {e["practice_number"]}')}><td><b>{esc(e["number"])}</b></td><td>{esc(date_it(e["date"]))}</td><td><a href="{e["url"]}">{esc(e["practice_number"])}</a></td><td>{esc(e["owner"])}</td><td>{esc(e["animal"])}</td><td>{esc(e["channel"])}</td><td>{money_it(e["total"])}</td><td><a class="btn ghost" href="{e["url"]}">Apri</a></td></tr>''' for e in entries]
        reminder_html=''.join(f'<a class="event" href="/pratiche/{row["id"]}"><b>{esc(row["practice_number"])}</b> · {esc(((row["owner_first_name"] or "")+" "+(row["owner_last_name"] or "")).strip())} · {esc(row["animal_name"] or "")}</a>' for row in reminders) or '<p class="sub">Nessuna fattura da ricordare.</p>'
        empty='<tr><td colspan="8" class="sub">Nessuna fattura trovata.</td></tr>'
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Fatture</h1><p class="sub">Ogni fattura identifica e apre la pratica collegata. Una pratica con acconto e saldo fatturati separatamente compare come due righe distinte.</p></div></div><form class="section" method="get"><div class="fields"><div class="field full"><label>Numero fattura o pratica</label><input name="q" value="{esc(term)}" placeholder="Cerca per fattura, pratica, cliente o animale"></div><div class="field"><label>Dal</label><input type="date" name="dal" value="{esc(date_from)}"></div><div class="field"><label>Al</label><input type="date" name="al" value="{esc(date_to)}"></div></div><button class="btn" style="margin-top:12px">Cerca</button></form><section class="tablebox"><table><thead><tr><th>Fattura</th><th>Data</th><th>Pratica</th><th>Cliente</th><th>Animale</th><th>Circuito</th><th>Totale</th><th></th></tr></thead><tbody>{''.join(table) or empty}</tbody></table></section><section class="section" style="margin-top:20px"><h2>Da fatturare</h2><div class="timeline">{reminder_html}</div></section></main>'''
        self.send_html(layout("Fatture",body,user))

    def urn_catalog_page(self,user):
        q=parse_qs(urlparse(self.path).query); term=(q.get("q") or [""])[0].strip(); material=(q.get("materiale") or [""])[0].strip(); availability=(q.get("disponibilita") or [""])[0].strip()
        category_options_map={"urne":"Urna","accessori":"Accessorio","calchi":"Calco"}
        category_param=(q.get("categoria") or ["urne"])[0].strip().lower()
        if category_param not in category_options_map:category_param="urne"
        category=category_options_map[category_param]
        where=["active=1","category=?"]; args=[category]
        if term:
            where.append("(UNACCENT(name) LIKE ? OR UNACCENT(material) LIKE ? OR UNACCENT(COALESCE(internal_code,'')) LIKE ?)"); args.extend([like_term(term)]*3)
        if material: where.append("material=?"); args.append(material)
        if availability=="disponibile": where.append("quantity>low_stock_threshold")
        elif availability=="bassa": where.append("quantity>0 AND quantity<=low_stock_threshold")
        elif availability=="esaurita": where.append("quantity<=0")
        with db() as c:
            urns=c.execute(f"SELECT * FROM urns WHERE {' AND '.join(where)} ORDER BY name",args).fetchall()
            all_urns=c.execute("SELECT * FROM urns WHERE active=1 AND category=?",(category,)).fetchall()
            materials=[row["material"] for row in c.execute("SELECT DISTINCT material FROM urns WHERE active=1 AND category=? AND material<>'' ORDER BY material",(category,))]
        tabs_html=''.join(f'<a href="/catalogo-urne?categoria={key}" class="{"active" if key==category_param else ""}">{label}</a>' for key,label in (("urne","Urne"),("accessori","Accessori"),("calchi","Calchi")))
        new_item_label={"Urna":"Nuova urna","Accessorio":"Nuovo accessorio","Calco":"Nuovo calco"}[category]
        stats={"models":len(all_urns),"quantity":sum(max(0,int(u["quantity"] or 0)) for u in all_urns),"out":sum(1 for u in all_urns if int(u["quantity"] or 0)<=0),"low":sum(1 for u in all_urns if 0<int(u["quantity"] or 0)<=int(u["low_stock_threshold"] or 3)),"value":sum(max(0,int(u["quantity"] or 0))*money_value(u["price"]) for u in all_urns)}
        stat_html=''.join(f'<div class="urn-stat"><small>{label}</small><strong>{value}</strong></div>' for label,value in (("Modelli",stats["models"]),("Pezzi disponibili",stats["quantity"]),("Esaurite",stats["out"]),("Scorte basse",stats["low"]),("Valore magazzino",money_it(stats["value"]))))
        cards=[]
        for urn in urns:
            qty=int(urn["quantity"] or 0); threshold=int(urn["low_stock_threshold"] or 3); cls="stock-out" if qty<=0 else "stock-low" if qty<=threshold else "stock-good"; label="Esaurita" if qty<=0 else "Scorta bassa" if qty<=threshold else "Disponibile"
            image=f'<img src="{esc(urn["image_path"])}" alt="{esc(urn["name"])}">' if urn["image_path"] else '<div class="urn-placeholder">Nessuna foto</div>'
            searchable=esc(" ".join((urn["name"] or "",urn["material"] or "",urn["internal_code"] or "")).lower())
            cards.append(f'''<article class="urn-card" data-urn-search="{searchable}">{image}<div><span class="{cls}"><b>{label}</b> · {qty} pz</span><h2>{esc(urn["name"])}</h2><div class="urn-meta">{esc(urn["material"] or "Senza categoria")} {("· "+esc(urn["internal_code"])) if urn["internal_code"] else ""}</div><strong>{money_it(money_value(urn["price"]))}</strong></div><div class="actions"><a class="btn" href="/catalogo-urne/{urn["id"]}">Apri scheda</a></div></article>''')
        no_results=not urns
        display_term="" if no_results else term
        display_material="" if no_results else material
        display_availability="" if no_results else availability
        material_options='<option value="">Tutti i materiali</option>'+''.join(f'<option value="{esc(item)}" {"selected" if item==display_material else ""}>{esc(item)}</option>' for item in materials)
        availability_options=''.join(f'<option value="{value}" {"selected" if display_availability==value else ""}>{label}</option>' for value,label in (("","Tutte le disponibilita"),("disponibile","Disponibili"),("bassa","Scorte basse"),("esaurita","Esaurite")))
        empty='<section id="urnLiveEmpty" class="section empty-state">Nessuna urna corrisponde ai filtri. Puoi aggiungerne una nuova.</section>'
        content=f'<section id="urnCatalogGrid" class="urn-grid">{"".join(cards)}</section><section id="urnLiveEmpty" class="section empty-state" style="display:none">Nessuna urna corrisponde alla ricerca.</section>' if cards else empty
        body=f'''<main class="wrap"><div class="titlebar"><div><h1>Catalogo Urne</h1><p class="sub">Catalogo e magazzino collegati alle pratiche.</p></div><a class="btn" href="/catalogo-urne/nuova?categoria={category_param}">{new_item_label}</a></div><nav class="calendar-tabs urn-tabs">{tabs_html}</nav><section class="urn-stats">{stat_html}</section><form class="section urn-filter no-advanced-collapse" method="get"><input type="hidden" name="categoria" value="{category_param}"><div class="fields"><div class="field full"><label>Cerca urna</label><input id="urnCatalogSearch" name="q" value="{esc(display_term)}" placeholder="Inizia a scrivere il nome dell urna" autocomplete="off"></div><div class="field"><label>Materiale</label><select name="materiale">{material_options}</select></div><div class="field"><label>Disponibilita</label><select name="disponibilita">{availability_options}</select></div></div><button class="btn" style="margin-top:12px">Filtra</button></form>{content}<script>(function(){{const input=document.getElementById("urnCatalogSearch"),grid=document.getElementById("urnCatalogGrid"),empty=document.getElementById("urnLiveEmpty");if(!input||!grid)return;const cards=[...grid.querySelectorAll(".urn-card")];input.addEventListener("input",()=>{{const words=normalizeUrnSearch(input.value).split(/\\s+/).filter(Boolean);let visible=0;cards.forEach(card=>{{const hay=normalizeUrnSearch(card.dataset.urnSearch);const show=words.every(word=>hay.includes(word));card.style.display=show?"":"none";if(show)visible++;}});if(empty)empty.style.display=visible?"none":"block";}});}})();</script></main>'''
        self.send_html(layout("Catalogo Urne",body,user))

