    def tag_controls(self,r):
        other_tags = [
            ("tag_assistita", "ASSISTITA", "tag-red"),
            ("tag_possibile_assistita", "POSSIBILE ASSISTITA", "tag-red"),
            ("tag_assistita_streaming", "ASSISTITA STREAMING", "tag-orange"),
            ("tag_possibile_assistita_streaming", "POSSIBILE ASSISTITA STREAMING", "tag-orange"),
            ("tag_saluto", "SALUTO", "tag-purple"),
            ("tag_calco", "CALCO", "tag-yellow"),
            ("tag_possibile_calco", "POSSIBILE CALCO", "tag-yellow"),
            ("tag_calco_urna", "CALCO PER URNA", "tag-yellow"),
            ("tag_calco_paw", "CALCO POLPASTRELLO", "tag-yellow"),
            ("tag_possibile_calco_paw", "POSSIBILE CALCO POLPASTRELLO", "tag-yellow"),
            ("tag_calco_nose", "CALCO NASO", "tag-yellow"),
            ("tag_possibile_calco_nose", "POSSIBILE CALCO NASO", "tag-yellow"),
            ("tag_avvisare", "AVVISARE", "tag-pink"),
            ("tag_da_richiamare", "DA RICHIAMARE", "tag-blue"),
        ]
        badges_html = ''.join(f'<span class="badge {cls}">{label}</span> ' for key,label,cls in other_tags if key in r.keys() and r[key])
        catalog_state = "sent" if ("catalog_sent" in r.keys() and r["catalog_sent"]=="Si") else "send" if ("send_catalog" in r.keys() and r["send_catalog"]=="Si") else ""
        estremi_state = "sent" if ("estremi_sent" in r.keys() and r["estremi_sent"]=="Si") else "send" if ("send_estremi" in r.keys() and r["send_estremi"]=="Si") else ""
        catalog_options=''.join(f'<option value="{v}" {"selected" if v==catalog_state else ""}>{esc(label)}</option>' for v,label in (("","Catalogo -"),("send","INVIARE CATALOGO"),("sent","CATALOGO INVIATO")))
        estremi_options=''.join(f'<option value="{v}" {"selected" if v==estremi_state else ""}>{esc(label)}</option>' for v,label in (("","Estremi -"),("send","INVIARE ESTREMI"),("sent","ESTREMI INVIATI")))
        tag_select_cls={"send":"tag-select-orange","sent":"tag-select-green"}
        catalog_cls=tag_select_cls.get(catalog_state,"")
        estremi_cls=tag_select_cls.get(estremi_state,"")
        return_to=esc(getattr(self,"path",""))
        controls=f'''<form class="inline-tag-form" onclick="event.stopPropagation()"><input type="hidden" name="return_to" value="{return_to}"><select class="inline-state-select {catalog_cls}" data-tag-endpoint="/pratiche/{r['id']}/catalogo-inviato" data-tag-field="catalog" data-saved-value="{catalog_state}" aria-label="Etichetta catalogo" onchange="saveTagState(this)">{catalog_options}</select><span class="inline-save-note" aria-live="polite"></span></form><form class="inline-tag-form" onclick="event.stopPropagation()"><input type="hidden" name="return_to" value="{return_to}"><select class="inline-state-select {estremi_cls}" data-tag-endpoint="/pratiche/{r['id']}/estremi-inviati" data-tag-field="estremi" data-saved-value="{estremi_state}" aria-label="Etichetta estremi" onchange="saveTagState(this)">{estremi_options}</select><span class="inline-save-note" aria-live="polite"></span></form>'''
        return f'{badges_html}<div class="inline-statuses">{controls}</div>'

    def status_badges(self,r):
        payment = r["payment_status"] if "payment_status" in r.keys() and r["payment_status"] else "Da saldare"
        pay_cls = {"Da saldare":"pay-yellow","Acconto":"pay-blue","Pagato":"pay-green"}.get(payment,"")
        status_cls=practice_status_class(r["status"])
        allowed_states=[state for state in STATES if state!="Smaltito" or r["service_type"]=="Cremazione collettiva"]
        state_options=''.join(f'<option value="{esc(state)}" {"selected" if state==r["status"] else ""}>{esc(state)}</option>' for state in allowed_states)
        modal_id=f'paymentPopover{r["id"]}'
        return_to=esc(getattr(self,"path",""))
        payment_full_amount=f"{effective_total(r):.2f}"
        payment_remaining_amount=f"{outstanding_amount(r):.2f}"
        payment_deposit_field="deposit_final" if uses_total_d(r) else "deposit"
        payment_deposit_amount=(r[payment_deposit_field] or r["payment_amount"] or "0.00") if payment_deposit_field in r.keys() else "0.00"
        payment_channel_value="D" if uses_total_d(r) else "W"
        with db() as c:
            acconto_movement,acconto_invoice=latest_movement_and_invoice(c,r["id"],"acconto")
            saldo_movement,saldo_invoice=latest_movement_and_invoice(c,r["id"],"saldo")
            extra_payments=c.execute("SELECT * FROM payment_movements WHERE practice_id=? AND is_extra=1 ORDER BY paid_at,id",(r["id"],)).fetchall()
            saldo_w_exists=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' AND payment_channel='W' LIMIT 1",(r["id"],)).fetchone())
            saldo_d_exists=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' AND payment_channel='D' LIMIT 1",(r["id"],)).fetchone())
        def macroarea_section(kind,label,movement,invoice,default_amount):
            date_value=str(movement["paid_at"] or "")[:10] if movement else ""
            amount_value=f'{money_value(movement["amount"]):.2f}' if movement else default_amount
            channel_value=(movement["payment_channel"] if movement and movement["payment_channel"] in ("W","D") else payment_channel_value)
            method_value=movement["payment_method"] if movement and movement["payment_method"] else ""
            invoice_number_value=invoice["invoice_number"] if invoice else ""
            invoice_total_value=invoice["invoice_total"] if invoice else amount_value
            invoice_date_value=invoice["invoice_date"] if invoice else ""
            method_options=''.join(f'<option value="{esc(m)}" {"selected" if m==method_value else ""}>{esc(m or "Metodo di pagamento")}</option>' for m in PAYMENT_METHODS)
            channel_options=''.join(f'<option value="{v}" {"selected" if v==channel_value else ""}>{v}</option>' for v in ("W","D"))
            invoice_hidden="" if channel_value=="W" else "hidden"
            lower=label.lower()
            remove_form=(
                f'''<form method="post" action="/pratiche/{r['id']}/pagamento-movimento/rimuovi" onsubmit="event.stopPropagation();return confirm('Rimuovere {label.lower()}? Verrà stornato anche nei Bilanci.')" style="display:inline"><input type="hidden" name="return_to" value="{return_to}"><input type="hidden" name="macroarea" value="{kind}"><button class="btn ghost" type="submit" style="margin-top:12px;margin-left:8px">Rimuovi {label.lower()}</button></form>'''
                if movement else ""
            )
            modalita_hidden="" if channel_value=="W" else "hidden"
            return f'''<section class="payment-macroarea" data-macroarea="{kind}"><h3>{label}</h3><form method="post" action="/pratiche/{r['id']}/pagamento-movimento" onsubmit="event.stopPropagation()"><input type="hidden" name="return_to" value="{return_to}"><input type="hidden" name="macroarea" value="{kind}"><input type="hidden" name="balance_idempotency_key" value="{secrets.token_urlsafe(16)}"><div class="fields"><div class="field"><label>Data {lower}</label><input type="date" name="{kind}_data" value="{esc(date_value)}" required></div><div class="field"><label>Totale {lower} €</label><input name="{kind}_totale" value="{esc(amount_value)}" inputmode="decimal" pattern="[0-9]+([,.][0-9]{{1,2}})?" title="Solo numeri, es. 120,00" required></div><div class="field"><label>Circuito {lower}</label><select name="{kind}_circuito" onchange="ppmSyncMacroareaInvoiceSection(this)">{channel_options}</select></div><div class="field" data-macroarea-modalita="{kind}" {modalita_hidden}><label>Modalità {lower}</label><select name="{kind}_modalita">{method_options}</select></div></div><div class="payment-invoice-section" data-macroarea-invoice="{kind}" {invoice_hidden}><div class="fields"><div class="field"><label>Importo fattura €</label><input name="{kind}_fattura_totale" value="{esc(invoice_total_value)}" inputmode="decimal" pattern="[0-9]+([,.][0-9]{{1,2}})?" title="Solo numeri, es. 120,00"></div><div class="field"><label>Data fattura</label><input type="date" name="{kind}_fattura_data" value="{esc(invoice_date_value)}"></div><div class="field full"><label>Numero fattura</label><input name="{kind}_fattura_numero" value="{esc(invoice_number_value)}"></div></div></div><button class="btn" style="margin-top:12px">Salva pagamento</button></form>{remove_form}</section>'''
        acconto_html=macroarea_section("acconto","Acconto",acconto_movement,acconto_invoice,payment_deposit_amount)
        saldo_html=macroarea_section("saldo","Saldo",saldo_movement,saldo_invoice,payment_remaining_amount)
        due_w=calculated_service_total(r)
        due_d=money_value(r["total_text"] if "total_text" in r.keys() else "")
        paid_w=money_value(r["deposit"] if "deposit" in r.keys() else "")
        paid_d=money_value(r["deposit_final"] if "deposit_final" in r.keys() else "")
        remaining_w=money_value(r["remaining_balance"] if "remaining_balance" in r.keys() else "")
        remaining_d=money_value(r["remaining_final"] if "remaining_final" in r.keys() else "")
        extras_note_w=(
            f'<div class="flash warning" style="margin-top:10px">Il totale è aumentato per l\'aggiunta di nuovi elementi. I pagamenti precedenti sono stati mantenuti e resta da pagare {money_it(remaining_w)} (circuito W).</div>'
            if saldo_w_exists and remaining_w>0.005 else ""
        )
        extras_note_d=(
            f'<div class="flash warning" style="margin-top:10px">Il totale è aumentato per l\'aggiunta di nuovi elementi. I pagamenti precedenti sono stati mantenuti e resta da pagare {money_it(remaining_d)} (circuito D).</div>'
            if saldo_d_exists and remaining_d>0.005 else ""
        )
        circuit_summary_html=f'''<div class="kvs" style="grid-template-columns:repeat(2,1fr);margin-bottom:14px"><div class="kv"><small>Circuito W</small><b>Totale {money_it(due_w)}</b><br><small>Già pagato {money_it(paid_w)} · Rimanenza {money_it(remaining_w)}</small></div><div class="kv"><small>Circuito D</small><b>Totale {money_it(due_d)}</b><br><small>Già pagato {money_it(paid_d)} · Rimanenza {money_it(remaining_d)}</small></div></div>{extras_note_w}{extras_note_d}'''
        extra_html=self.payment_extra_section_html(r["id"],extra_payments,return_to)
        return f'''<div class="inline-statuses" onclick="event.stopPropagation()">
        <form method="post" action="/pratiche/{r['id']}/stato-rapido" onsubmit="return savePracticeState(this,event)"><input type="hidden" name="return_to" value="{return_to}"><select class="inline-state-select practice-status {status_cls}" name="status" aria-label="Stato pratica" data-saved-value="{esc(r['status'])}" onchange="savePracticeState(this.form)">{state_options}</select><span class="inline-save-note" aria-live="polite"></span></form>
        <button type="button" class="inline-state-select {pay_cls}" aria-label="Stato pagamento" data-payment-popover="{modal_id}" onclick="openPaymentPopover(this)">{esc(payment)}</button>
        <div class="payment-popover" id="{modal_id}" hidden onclick="if(event.target===this)closePaymentPopover(this)"><div class="payment-dialog"><div class="titlebar"><div><h2>Pagamento · {esc(r['practice_number'])}</h2><p class="sub">Registra acconto e saldo in modo indipendente.</p></div><button class="btn ghost" type="button" onclick="closePaymentPopover(this)">Chiudi</button></div>{circuit_summary_html}{acconto_html}{saldo_html}{extra_html}</div></div></div>'''

    def payment_extra_section_html(self,pid,extras,return_to):
        # Riusato sia dal popup Pagamento (status_badges) sia dalla sezione
        # Pagamento della pratica (_fields_html): stessa identica logica,
        # mai duplicata. Un pagamento extra crea SEMPRE un nuovo movimento,
        # mai una correzione di quello base — l'unica azione ambigua che
        # aveva causato un bug reale in produzione.
        method_options=''.join(f'<option value="{esc(m)}">{esc(m) or "Seleziona metodo"}</option>' for m in PAYMENT_METHODS)
        channel_options=''.join(f'<option value="{v}">{v}</option>' for v in ("W","D"))
        rows_html=''.join(
            f'''<div class="payment-extra-row"><div><b>{esc(row["payment_channel"] or "")} · {money_it(money_value(row["amount"]))}</b><small>{date_it(str(row["paid_at"] or "")[:10])}</small></div><form method="post" action="/pratiche/{pid}/pagamento-extra/{row['id']}/rimuovi" onsubmit="event.stopPropagation();return confirm('Rimuovere questo pagamento extra? Verrà stornato anche nei Bilanci.')" style="display:inline"><input type="hidden" name="return_to" value="{esc(return_to)}"><button class="btn ghost" type="submit">Rimuovi</button></form></div>'''
            for row in extras
        ) or '<p class="sub">Nessun pagamento extra registrato.</p>'
        return f'''<section class="payment-macroarea" data-macroarea="extra"><h3>Aggiungi pagamento extra</h3><p class="sub">Crea sempre un nuovo movimento, indipendente da Acconto/Saldo.</p><form method="post" action="/pratiche/{pid}/pagamento-extra" onsubmit="event.stopPropagation()"><input type="hidden" name="return_to" value="{esc(return_to)}"><input type="hidden" name="balance_idempotency_key" value="{secrets.token_urlsafe(16)}"><div class="fields"><div class="field"><label>Circuito</label><select name="extra_circuito" onchange="ppmSyncMacroareaInvoiceSection(this)">{channel_options}</select></div><div class="field"><label>Data</label><input type="date" name="extra_data" required></div><div class="field"><label>Totale €</label><input name="extra_totale" inputmode="decimal" pattern="[0-9]+([,.][0-9]{{1,2}})?" title="Solo numeri, es. 120,00" required></div><div class="field" data-macroarea-modalita="extra"><label>Modalità</label><select name="extra_modalita">{method_options}</select></div></div><div class="payment-invoice-section" data-macroarea-invoice="extra"><div class="fields"><div class="field"><label>Importo fattura €</label><input name="extra_fattura_totale" inputmode="decimal" pattern="[0-9]+([,.][0-9]{{1,2}})?" title="Solo numeri, es. 120,00"></div><div class="field"><label>Data fattura</label><input type="date" name="extra_fattura_data"></div><div class="field full"><label>Numero fattura</label><input name="extra_fattura_numero"></div></div></div><button class="btn" style="margin-top:12px">Aggiungi pagamento extra</button></form>{rows_html}</section>'''

    def practice_rows(self,rows,show_financials=False):
        rows=list(rows)
        columns=19 if show_financials else 15
        if not rows:return f'<tr><td colspan="{columns}" class="sub">Nessuna pratica presente.</td></tr>'
        practice_ids=[row["id"] for row in rows]
        urn_items_by_practice={}
        if practice_ids:
            marks=','.join('?' for _ in practice_ids)
            with db() as c:
                for irow in c.execute(f"SELECT practice_id,label,price FROM practice_items WHERE practice_id IN ({marks}) AND category='urna' ORDER BY practice_id,sort_order",tuple(practice_ids)):
                    urn_items_by_practice.setdefault(irow["practice_id"],[]).append(irow)
        collaborator_ids={int(row["collaborator_id"]) for row in rows if "collaborator_id" in row.keys() and row["collaborator_id"]}
        collaborator_codes={}
        if collaborator_ids:
            marks=','.join('?' for _ in collaborator_ids)
            with db() as c:collaborator_codes={row["id"]:(row["code"] or "") for row in c.execute(f"SELECT id,code FROM collaborators WHERE id IN ({marks})",tuple(collaborator_ids))}
        html=[]
        for r in rows:
            code=str(r['practice_number'] or '')
            code_cls='practice-code-cr' if code.startswith('CR-') else 'practice-code-sm' if code.startswith('SM-') else ''
            collaborator_code=collaborator_codes.get(int(r["collaborator_id"])) if "collaborator_id" in r.keys() and r["collaborator_id"] else ""
            sigla_prefix=f"{esc(collaborator_code)} " if collaborator_code else ""
            avatar_emoji,avatar_cls=species_avatar(r["species"] if "species" in r.keys() else "")
            avatar_html=f'<span class="practice-row-avatar {avatar_cls}" aria-hidden="true">{avatar_emoji}</span>'
            if (r['service_type'] or '') == 'Cremazione collettiva':
                animal_copy=esc(r['species']) if r['species'] else '<span class="sub">-</span>'
            else:
                animal_meta=esc(r['species']) + ((' - '+esc(r['estimated_weight'])+' kg') if r['estimated_weight'] else '')
                animal_copy=f'{sigla_prefix}{esc(r["animal_name"] or "Da inserire")}<br><small>{animal_meta}</small>'
            animal_cell=f'<div class="practice-row-animal">{avatar_html}<div class="practice-row-animal-copy">{animal_copy}</div></div>'
            owner_name=((r['owner_first_name'] or '')+' '+(r['owner_last_name'] or '')).strip()
            if "collaborator_name" in r.keys() and r["collaborator_name"]:
                owner_name=r["collaborator_name"]
            owner=esc(owner_name)
            age_parts=[]
            if r["age_years"]: age_parts.append(f'{esc(r["age_years"])} anni')
            if r["age_months"]: age_parts.append(f'{esc(r["age_months"])} mesi')
            age_cell=' e '.join(age_parts) or '<span class="sub">-</span>'
            invoice_number=compact_text(r["invoice_number"]) if "invoice_number" in r.keys() else ""
            invoice_amount=compact_text(r["invoice_total"]) if "invoice_total" in r.keys() else ""
            invoice_amount_html=f'<br><small>{money_it(money_value(invoice_amount))}</small>' if invoice_amount else ''
            invoice_cell=f'''<div class="invoice-inline-cell" onclick="event.stopPropagation()"><input class="invoice-inline-input" type="text" value="{esc(invoice_number)}" placeholder="N. fattura" data-invoice-endpoint="/pratiche/{r['id']}/fattura-rapida" data-saved-value="{esc(invoice_number)}" onchange="saveInvoiceNumber(this)">{invoice_amount_html}</div>'''
            vet_label=esc(r['clinic_name'] if 'clinic_name' in r.keys() and r['clinic_name'] else '-')
            recovery_date=date_it(r['pickup_date'] if 'pickup_date' in r.keys() and r['pickup_date'] else r['created_at'])
            notes_preview=compact_text(r["notes"]) if "notes" in r.keys() else ""
            notes_cell=esc(notes_preview[:70])+("..." if len(notes_preview)>70 else "") if notes_preview else '<span class="sub">-</span>'
            urn_items=urn_items_by_practice.get(r["id"],[])
            urn_labels=[]
            for item in urn_items:
                label=compact_text(item["label"])
                if label and label not in urn_labels:urn_labels.append(label)
            urn_notes=" / ".join(urn_labels)
            urn_prices=[compact_text(item["price"]) for item in urn_items if item["price"]]
            urn_price=" + ".join(urn_prices)
            urn_cell='<br>'.join(x for x in [esc(urn_notes), f'<small>{esc(urn_price)} €</small>' if urn_price else ''] if x) or '<span class="sub">-</span>'
            channel=payment_channel(r)
            paid_total=received_amount(r)
            paid_cell=payment_amount_with_channel(r,paid_total) if paid_total>0 else f"€ 0,00 {channel}"
            financial_cells=''
            if show_financials:
                total_d=(r["total_text"] or "").strip() if "total_text" in r.keys() else ""
                deposit_label=f"Acconto {channel}"
                remaining_label="Saldo/Rimanenza W" if channel=="W" else f"Rimanenza {channel}"
                financial_cells=f'<td>{money_it(calculated_service_total(r))}</td><td>{money_it(money_value(total_d)) if total_d else "-"}</td><td><small>{deposit_label}</small><br>{money_it(channel_deposit(r))}</td><td><small>{remaining_label}</small><br>{money_it(channel_remaining(r))}</td>'
            practice_url=f'/pratiche/{r["id"]}?return_to={quote(self.path,safe="")}'
            provenance=esc(r["provenance"] if "provenance" in r.keys() and r["provenance"] else "-")
            delete_cell=f'''<form onclick="event.stopPropagation()" method="post" action="/pratiche/{r['id']}/elimina" onsubmit="return confirm('Spostare questa pratica nel Cestino? Potrai ripristinarla in seguito.')"><button class="btn danger-btn" type="submit">Elimina</button></form>'''
            html.append(f'<tr class="practice-row-link {avatar_cls}" {row_open_attrs(practice_url,f"Apri pratica {code}")}><td>{animal_cell}</td><td>{age_cell}</td><td>{owner}<br><small>{esc(r["owner_phone"])}</small></td><td>{esc(recovery_date)}</td><td><a href="{practice_url}"><b class="{code_cls}">{esc(code)}</b></a></td><td>{vet_label}</td><td><b>{provenance}</b></td><td>{esc(r["destination_branch"])}</td><td>{self.tag_controls(r)}</td><td>{notes_cell}</td><td>{urn_cell}</td><td><b>{paid_cell}</b></td><td>{invoice_cell}</td>{financial_cells}<td>{self.status_badges(r)}</td><td>{delete_cell}</td></tr>')
        return ''.join(html)

