    def quick_invoice(self,user,pid):
        f=self.form();invoice_number=f.get("invoice_number","").strip();ajax=f.get("ajax")=="1";stamp=now()
        with db() as c:
            current=c.execute("SELECT invoice_number,make_invoice FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not current:return self.send_json({"ok":False,"error":"Pratica non trovata"},404) if ajax else self.send_error(404)
            conflict=self.invoice_conflict(c,invoice_number,pid)
            if conflict:
                error=f'Numero fattura già usato nella pratica {conflict["practice_number"]}'
                return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
            new_make_invoice="Si" if invoice_number else (current["make_invoice"] or "")
            if (current["invoice_number"] or "")==invoice_number and (current["make_invoice"] or "")==new_make_invoice:
                if ajax:return self.send_json({"ok":True,"invoice_number":invoice_number,"make_invoice":new_make_invoice})
                return self.redirect(safe_return_path(f.get("practice_view"),f"/pratiche/{pid}"))
            c.execute("UPDATE practices SET invoice_number=?,make_invoice=?,updated_at=? WHERE id=?",(invoice_number,new_make_invoice,stamp,pid))
            c.execute("INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",(pid,"Numero fattura",current["invoice_number"] or "-",invoice_number or "-",user["id"],stamp))
        if ajax:return self.send_json({"ok":True,"invoice_number":invoice_number,"make_invoice":new_make_invoice})
        self.redirect(safe_return_path(f.get("practice_view"),f"/pratiche/{pid}"))

    def change_state(self,user,pid):
        f=self.form(); new=f.get("status",""); payment=f.get("payment_status","Da saldare"); requested_invoice=f.get("invoice_number"); no_whatsapp="Si" if f.get("no_whatsapp_message")=="Si" else ""
        if new not in STATES or payment not in PAYMENT_STATES:return self.practice(user,pid,error="Stato pratica o stato pagamento non validi.")
        with db() as c:
            old=c.execute("SELECT * FROM practices WHERE id=?",(pid,)).fetchone()
            if not old:return self.send_error(404)
            invoice=old["invoice_number"] if requested_invoice is None else requested_invoice.strip()
            conflict=self.invoice_conflict(c,invoice,pid)
            if conflict:return self.practice(user,pid,error=f'Numero fattura già usato nella pratica {conflict["practice_number"]}')
            if new=="Smaltito" and old["service_type"]!="Cremazione collettiva": return self.practice(user,pid,error="Smaltito è disponibile solo per la cremazione collettiva.")
            old_payment=old["payment_status"] or "Da saldare"
            if payment!=old_payment:
                return self.practice(user,pid,error="Registra il cambio di pagamento dalla finestra dedicata.")
            c.execute("UPDATE practices SET status=?,payment_status=?,invoice_number=?,no_whatsapp_message=?,updated_at=? WHERE id=?",(new,payment,invoice,no_whatsapp,now(),pid))
            new_value=f'{new} + {payment}' + (f' - Fattura {invoice}' if invoice else '') + (" - NO MESSAGGIO" if no_whatsapp else "")
            old_value=f'{old["status"]} + {old_payment}' + (f' - Fattura {old["invoice_number"]}' if old["invoice_number"] else '') + (" - NO MESSAGGIO" if old["no_whatsapp_message"]=="Si" else "")
            c.execute("INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",(pid,"Cambio stati",old_value,new_value,user["id"],now()))
            if no_whatsapp:
                self.cancel_whatsapp_scheduled(c,pid,user["id"],"NO MESSAGGIO selezionato")
            elif old["status"] == "Consegnato" and new != "Consegnato":
                self.cancel_whatsapp_scheduled(c,pid,user["id"],"Pratica spostata da Consegnato a un altro stato")
            elif old["status"] != "Consegnato" and new == "Consegnato":
                self.schedule_whatsapp_thanks(c,pid,user["id"])
            if old["status"]!=new and new=="Consegnato":
                delivered_owner=f'{(old["owner_first_name"] or "")} {(old["owner_last_name"] or "")}'.strip()
                emit_notification(c,"practice_delivered","Pratica consegnata",push_bullets(old["animal_name"] or old["practice_number"],delivered_owner or None),pid,user["id"],db_path=DB_PATH)
            if old_payment!=payment and payment=="Pagato":
                payment_owner=f'{(old["owner_first_name"] or "")} {(old["owner_last_name"] or "")}'.strip()
                emit_notification(c,"payment_received","Pagamento ricevuto",push_bullets(payment_owner or None,money_it(effective_total(old))),pid,user["id"],db_path=DB_PATH)
        self.redirect(safe_return_path(f.get("practice_view"),f"/pratiche/{pid}"))

    def save_payment_macroarea(self,user,pid):
        """Save one payment macroarea (acconto or saldo) independently of
        the other. Unlike the old quick_payment (a status-transition guard
        requiring an exact amount match), this is a movement-level upsert:
        each macroarea always has its own date/totale/circuito/modalita and
        its own W-only invoice fields, freely re-editable in any order."""
        form=self.form(); ajax=form.get("ajax")=="1"
        macroarea=form.get("macroarea","").strip()
        if macroarea not in ("acconto","saldo"):
            error="Macroarea di pagamento non valida."
            return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
        prefix=macroarea
        with db() as c:
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice:
                return self.send_json({"ok":False,"error":"Pratica non trovata"},404) if ajax else self.send_error(404)
            error=self.apply_payment_macroarea(
                c,user,pid,practice,macroarea,
                data_field=form.get(f"{prefix}_data","").strip(),
                totale_field=normalize_money_text(form.get(f"{prefix}_totale","")),
                channel=form.get(f"{prefix}_circuito","").strip().upper(),
                method=form.get(f"{prefix}_modalita","").strip(),
                invoice_number=form.get(f"{prefix}_fattura_numero","").strip(),
                invoice_total=normalize_money_text(form.get(f"{prefix}_fattura_totale","")),
                invoice_date=form.get(f"{prefix}_fattura_data","").strip(),
                balance_key=form.get("balance_idempotency_key","").strip(),
                # "Salva pagamento" corregge sempre l'ultimo movimento della
                # macroarea: un incasso genuinamente nuovo si registra solo
                # da "Aggiungi pagamento extra" (save_payment_extra).
            )
            if error:
                return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
            new_status=c.execute("SELECT payment_status FROM practices WHERE id=?",(pid,)).fetchone()["payment_status"]
        if ajax:return self.send_json({"ok":True,"payment_status":new_status,"macroarea":macroarea})
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def apply_payment_macroarea(self,c,user,pid,practice,macroarea,*,data_field,totale_field,channel,method,invoice_number,invoice_total,invoice_date,balance_key="",force_new=False,is_extra=False):
        """Core logic shared by the Pagamento popover (save_payment_macroarea)
        above and practice creation (create_practice): validates and
        persists one acconto/saldo entry for one circuito — the
        payment_movements row, the real balance_movements ledger entry, its
        W-only invoice, and the recomputed payment_status/deposit/remaining
        on the practice. Returns an error message, or None on success.
        Callers must pass an already-open connection and an already-fetched
        practice row (create_practice re-fetches it fresh between an acconto
        call and a saldo call in the same request, since deposit/remaining
        fallback values must reflect what the first call just wrote).

        force_new=True (only ever set by the explicit "Registra nuovo
        pagamento" action) always creates a brand new payment_movements +
        balance_movements row, even if one already exists for this
        macroarea/circuito — e.g. an extra item added to a practice whose W
        or D circuito was already fully paid needs a genuinely SECOND
        payment, never a correction of the first one's amount/date. Without
        force_new, an existing movement for the same macroarea is corrected
        in place (typo fix on what you just entered) exactly as before."""
        try:
            date.fromisoformat(data_field)
        except ValueError:
            return "Indica una data valida."
        amount=round(money_value(totale_field),2)
        if amount<=0:
            return "Indica un importo valido."
        if channel not in ("W","D"):
            return "Seleziona il circuito (W o D)."
        if method and method not in PAYMENT_METHODS:
            return "Seleziona il metodo di pagamento."
        if channel!="D" and not method:
            return "Seleziona il metodo di pagamento."
        if channel!="W":
            invoice_number=invoice_total=invoice_date=""
        if invoice_total and not re.fullmatch(r"\d+(?:\.\d{1,2})?",invoice_total):
            return "Totale fattura non valido."
        if invoice_date and not re.fullmatch(r"\d{4}-\d{2}-\d{2}",invoice_date):
            return "Data fattura non valida."
        existing_movement,existing_invoice=latest_movement_and_invoice(c,pid,macroarea)
        if invoice_number:
            conflict=self.invoice_conflict(c,invoice_number,exclude_movement_invoice_id=existing_invoice["id"] if existing_invoice else None)
            if conflict:
                return f'Numero fattura già usato nella pratica {conflict["practice_number"]}'
        is_collaborator=(practice["request_origin"] or "")=="Collaboratore" or bool(practice["collaborator_id"])
        category=classify_balance_category(has_total_d=(channel=="D"),is_collaborator=is_collaborator)
        has_acconto_row=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
        balance_type="Acconto" if macroarea=="acconto" else ("Saldo" if has_acconto_row else "Incasso completo")
        stamp=now()
        if existing_movement and not force_new:
            c.execute(
                "UPDATE payment_movements SET amount=?,paid_at=?,payment_channel=?,payment_method=?,movement_category=? WHERE id=?",
                (amount,data_field,channel,method,category,existing_movement["id"]),
            )
            movement_id=existing_movement["id"]
            old_paid_at=str(existing_movement["paid_at"] or "")[:10]
            corrected=correct_balance_movement_date(
                c,practice_id=pid,movement_type=balance_type,movement_date=data_field,
                idempotency_key=f"payment-macroarea-date:{pid}:{macroarea}:{old_paid_at or 'missing'}:{data_field}",
                created_by=user["id"],
            )
            if corrected is None:
                # correct_balance_movement_date looks up the existing ledger
                # row by movement_type ("Acconto"/"Saldo"/"Incasso completo")
                # — a label derived from has_acconto_row, which can change
                # over the life of a practice (e.g. an acconto gets added
                # later, flipping a settlement's expected label from
                # "Incasso completo" to "Saldo"). When that happens this
                # lookup finds nothing even though a real ledger row exists
                # under the old label, landing here. The key must still vary
                # with amount/date — a fixed key reused across every such
                # mismatch (regardless of amount) previously caused a real
                # IdempotencyConflictError in production once amounts
                # differed between attempts.
                create_balance_movement(
                    c,amount_cents=euros_to_cents(f"{amount:.2f}"),movement_date=data_field,category=category,
                    ledger_section="Entrata",movement_type=balance_type,
                    idempotency_key=f"payment-macroarea-bootstrap:{pid}:{macroarea}:{euros_to_cents(f'{amount:.2f}')}:{data_field}",
                    practice_id=pid,practice_number_snapshot=practice["practice_number"] or "",
                    payment_method=method,description="Pagamento registrato",source="practice_payment_macroarea",
                    collaborator_id=int(practice["collaborator_id"]) if practice["collaborator_id"] else None,
                    created_by=user["id"],
                )
            else:
                target_cents=euros_to_cents(f"{amount:.2f}")
                if corrected.amount_cents!=target_cents or corrected.category!=category:
                    correct_balance_movement_amount(
                        c,original_movement_id=corrected.id,new_amount_cents=target_cents,
                        idempotency_key=f"payment-macroarea-amount:{pid}:{macroarea}:{corrected.amount_cents}:{target_cents}",
                        category=category,created_by=user["id"],reason="Correzione pagamento",
                    )
        else:
            idempotency_key=f'practice-movement:{pid}:{macroarea}:{balance_key or secrets.token_urlsafe(8)}'
            # A double-tap/retry on this exact still-open form resubmits the
            # same idempotency_key (it's a fixed hidden field, only
            # regenerated when the popover is re-rendered), so if a
            # balance_movements row with this key already exists, this call
            # is a replay of one we already fully processed — skip creating
            # a second payment_movements detail row for it (create_balance_movement
            # itself already no-ops on the ledger side for a matching payload).
            is_retry=bool(c.execute("SELECT 1 FROM balance_movements WHERE idempotency_key=? LIMIT 1",(idempotency_key,)).fetchone())
            movement_description="Pagamento extra registrato" if is_extra else "Pagamento registrato"
            movement_source="practice_payment_extra" if is_extra else "practice_payment_macroarea"
            create_balance_movement(
                c,amount_cents=euros_to_cents(f"{amount:.2f}"),movement_date=data_field,category=category,
                ledger_section="Entrata",movement_type=balance_type,idempotency_key=idempotency_key,
                practice_id=pid,practice_number_snapshot=practice["practice_number"] or "",
                payment_method=method,description=movement_description,source=movement_source,
                collaborator_id=int(practice["collaborator_id"]) if practice["collaborator_id"] else None,
                created_by=user["id"],
            )
            if not is_retry:
                self.add_payment_movement(c,pid,macroarea,category,amount,user["id"],movement_description,data_field,payment_method=method,movement_category=category,is_extra=is_extra)
            movement=c.execute("SELECT id FROM payment_movements WHERE practice_id=? AND payment_type LIKE ? ORDER BY id DESC LIMIT 1",(pid,f"{macroarea}%")).fetchone()
            movement_id=movement["id"] if movement else None
        if channel=="W" and movement_id:
            self.save_movement_invoice(c,pid,movement_id,invoice_number,invoice_date,invoice_total or f"{amount:.2f}",method,channel,user["id"])
        old_status=practice["payment_status"] or "Da saldare"
        has_acconto=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
        has_saldo=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' LIMIT 1",(pid,)).fetchone())
        new_status="Pagato" if has_saldo else ("Acconto" if has_acconto else "Da saldare")
        deposit,remaining_balance,deposit_final,remaining_final=recompute_practice_channel_balances(c,pid,practice)
        date_field="deposit_paid_at" if macroarea=="acconto" else "paid_at"
        c.execute(
            f"UPDATE practices SET payment_status=?,payment_method=?,payment_amount=?,deposit=?,remaining_balance=?,deposit_final=?,remaining_final=?,{date_field}=?,updated_at=? WHERE id=?",
            (new_status,method,f"{amount:.2f}",deposit,remaining_balance,deposit_final,remaining_final,data_field,stamp,pid),
        )
        if old_status!=new_status:
            c.execute(
                "INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",
                (pid,"Pagamento",old_status,f'{new_status} · {money_it(amount)}',user["id"],stamp),
            )
        if new_status=="Pagato" and old_status!="Pagato":
            owner=f'{practice["owner_first_name"] or ""} {practice["owner_last_name"] or ""}'.strip()
            emit_notification(c,"payment_received","Pagamento ricevuto",push_bullets(owner or None,money_it(money_value(amount))),pid,user["id"],db_path=DB_PATH)
        return None

    def remove_payment_macroarea(self,user,pid):
        """Undo a previously saved macroarea (acconto or saldo): deletes its
        payment_movements row, stornos the matching real balance_movements
        entry (subtracting it from Bilanci), drops its movement invoice if
        it has no other links, and re-derives payment_status/deposit/
        remaining_balance from whatever movements remain — lets the status
        go backward (Pagato->Acconto->Da saldare) symmetrically to how
        save_payment_macroarea moves it forward."""
        form=self.form(); ajax=form.get("ajax")=="1"
        macroarea=form.get("macroarea","").strip()
        if macroarea not in ("acconto","saldo"):
            error="Macroarea di pagamento non valida."
            return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
        with db() as c:
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice:
                return self.send_json({"ok":False,"error":"Pratica non trovata"},404) if ajax else self.send_error(404)
            existing_movement,_=latest_movement_and_invoice(c,pid,macroarea)
            old_status=practice["payment_status"] or "Da saldare"
            if not existing_movement:
                if ajax:return self.send_json({"ok":True,"payment_status":old_status})
                return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))
            has_acconto_row=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
            balance_type="Acconto" if macroarea=="acconto" else ("Saldo" if has_acconto_row else "Incasso completo")
            stamp=now()
            target=c.execute(
                """SELECT b.* FROM balance_movements b
                   WHERE b.practice_id=? AND b.ledger_section='Entrata' AND b.movement_type=? AND b.amount_cents>0
                     AND NOT EXISTS(SELECT 1 FROM balance_movements r WHERE r.related_movement_id=b.id AND r.movement_type='Storno')
                   ORDER BY b.id DESC LIMIT 1""",
                (pid,balance_type),
            ).fetchone()
            if target:
                try:
                    create_balance_reversal(
                        c,original_movement_id=target["id"],movement_date=stamp[:10],
                        idempotency_key=f"payment-macroarea-remove:{pid}:{macroarea}:{target['id']}",
                        description=f"Rimozione {macroarea} dalla finestra Pagamento",
                        source="manual_void",created_by=user["id"],
                    )
                except MovementAlreadyReversedError:
                    pass
            invoice_link=c.execute("SELECT invoice_id FROM movement_invoice_links WHERE payment_movement_id=?",(existing_movement["id"],)).fetchone()
            c.execute("DELETE FROM movement_invoice_links WHERE payment_movement_id=?",(existing_movement["id"],))
            if invoice_link:
                remaining_links=c.execute("SELECT COUNT(*) n FROM movement_invoice_links WHERE invoice_id=?",(invoice_link["invoice_id"],)).fetchone()["n"]
                if remaining_links==0:
                    c.execute("DELETE FROM movement_invoices WHERE id=?",(invoice_link["invoice_id"],))
            c.execute("DELETE FROM payment_movements WHERE id=?",(existing_movement["id"],))
            has_acconto=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
            has_saldo=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' LIMIT 1",(pid,)).fetchone())
            new_status="Pagato" if has_saldo else ("Acconto" if has_acconto else "Da saldare")
            deposit,remaining_balance,deposit_final,remaining_final=recompute_practice_channel_balances(c,pid,practice)
            date_field="deposit_paid_at" if macroarea=="acconto" else "paid_at"
            c.execute(
                f"UPDATE practices SET payment_status=?,deposit=?,remaining_balance=?,deposit_final=?,remaining_final=?,{date_field}=?,updated_at=? WHERE id=?",
                (new_status,deposit,remaining_balance,deposit_final,remaining_final,"",stamp,pid),
            )
            if old_status!=new_status:
                c.execute(
                    "INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",
                    (pid,"Pagamento",old_status,f"{new_status} · {macroarea} rimosso",user["id"],stamp),
                )
        if ajax:return self.send_json({"ok":True,"payment_status":new_status})
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def save_payment_extra(self,user,pid):
        """Unico modo per registrare un incasso genuinamente nuovo (mai una
        correzione): riusa apply_payment_macroarea con force_new=True e
        is_extra=True, cosi' il movimento creato e' sempre distinto da
        quello base e riconoscibile in Bilanci (source/description
        differenti). macroarea="saldo" e' solo l'etichetta usata dal
        ledger (Acconto non ha senso per un extra)."""
        form=self.form()
        with db() as c:
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice:
                return self.send_error(404)
            error=self.apply_payment_macroarea(
                c,user,pid,practice,"saldo",
                data_field=form.get("extra_data","").strip(),
                totale_field=normalize_money_text(form.get("extra_totale","")),
                channel=form.get("extra_circuito","").strip().upper(),
                method=form.get("extra_modalita","").strip(),
                invoice_number=form.get("extra_fattura_numero","").strip(),
                invoice_total=normalize_money_text(form.get("extra_fattura_totale","")),
                invoice_date=form.get("extra_fattura_data","").strip(),
                balance_key=form.get("balance_idempotency_key","").strip(),
                force_new=True,is_extra=True,
            )
            if error:
                return self.practice(user,pid,error=error)
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def remove_payment_extra(self,user,pid,movement_id):
        """Rimuove UNA riga specifica di pagamento extra (mai 'l'ultima
        della macroarea', a differenza di remove_payment_macroarea — con
        piu' extra possibili serve puntare esattamente a quella scelta),
        senza mai toccare il movimento base ne' altri extra."""
        form=self.form()
        with db() as c:
            practice=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not practice:
                return self.send_error(404)
            existing_movement=c.execute("SELECT * FROM payment_movements WHERE id=? AND practice_id=? AND is_extra=1",(movement_id,pid)).fetchone()
            if not existing_movement:
                return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))
            old_status=practice["payment_status"] or "Da saldare"
            stamp=now()
            amount_cents=euros_to_cents(f"{money_value(existing_movement['amount']):.2f}")
            paid_at_date=str(existing_movement["paid_at"] or "")[:10]
            # Nessuna chiave esterna diretta tra payment_movements e
            # balance_movements: la riga ledger corrispondente si ritrova
            # per pratica+source+importo+data, non ancora stornata — stesso
            # limite gia' presente in remove_payment_macroarea (che punta
            # "l'ultimo movimento non stornato di quel tipo"), qui ristretto
            # pero' ai soli pagamenti extra cosi' non intercetta mai quello
            # base.
            target=c.execute(
                """SELECT b.* FROM balance_movements b
                   WHERE b.practice_id=? AND b.ledger_section='Entrata' AND b.source='practice_payment_extra'
                     AND b.amount_cents=? AND b.movement_date=? AND b.amount_cents>0
                     AND NOT EXISTS(SELECT 1 FROM balance_movements r WHERE r.related_movement_id=b.id AND r.movement_type='Storno')
                   ORDER BY b.id DESC LIMIT 1""",
                (pid,amount_cents,paid_at_date),
            ).fetchone()
            if target:
                try:
                    create_balance_reversal(
                        c,original_movement_id=target["id"],movement_date=stamp[:10],
                        idempotency_key=f"payment-extra-remove:{pid}:{movement_id}",
                        description="Rimozione pagamento extra",
                        source="manual_void",created_by=user["id"],
                    )
                except MovementAlreadyReversedError:
                    pass
            invoice_link=c.execute("SELECT invoice_id FROM movement_invoice_links WHERE payment_movement_id=?",(existing_movement["id"],)).fetchone()
            c.execute("DELETE FROM movement_invoice_links WHERE payment_movement_id=?",(existing_movement["id"],))
            if invoice_link:
                remaining_links=c.execute("SELECT COUNT(*) n FROM movement_invoice_links WHERE invoice_id=?",(invoice_link["invoice_id"],)).fetchone()["n"]
                if remaining_links==0:
                    c.execute("DELETE FROM movement_invoices WHERE id=?",(invoice_link["invoice_id"],))
            c.execute("DELETE FROM payment_movements WHERE id=?",(existing_movement["id"],))
            has_acconto=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'acconto%' LIMIT 1",(pid,)).fetchone())
            has_saldo=bool(c.execute("SELECT 1 FROM payment_movements WHERE practice_id=? AND payment_type LIKE 'saldo%' LIMIT 1",(pid,)).fetchone())
            new_status="Pagato" if has_saldo else ("Acconto" if has_acconto else "Da saldare")
            deposit,remaining_balance,deposit_final,remaining_final=recompute_practice_channel_balances(c,pid,practice)
            c.execute(
                "UPDATE practices SET payment_status=?,deposit=?,remaining_balance=?,deposit_final=?,remaining_final=?,updated_at=? WHERE id=?",
                (new_status,deposit,remaining_balance,deposit_final,remaining_final,stamp,pid),
            )
            if old_status!=new_status:
                c.execute(
                    "INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",
                    (pid,"Pagamento",old_status,f"{new_status} · pagamento extra rimosso",user["id"],stamp),
                )
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def quick_payment(self,user,pid):
        form=self.form(); payment=form.get("payment_status","Da saldare"); amount=normalize_money_text(form.get("payment_amount","")); method=form.get("payment_method","").strip(); economic_at=form.get("economic_at","").strip(); ajax=form.get("ajax")=="1"; channel=form.get("payment_channel","").strip().upper() or None
        movement_type_prefix="acconto" if payment=="Acconto" else "saldo" if payment=="Pagato" else ""
        active_invoice_number=(form.get(f"{movement_type_prefix}_invoice_number","") if movement_type_prefix else "").strip()
        active_invoice_total=normalize_money_text(form.get(f"{movement_type_prefix}_invoice_total","")) if movement_type_prefix else ""
        active_invoice_date=(form.get(f"{movement_type_prefix}_invoice_date","") if movement_type_prefix else "").strip()
        if payment not in PAYMENT_STATES or method not in PAYMENT_METHODS or (amount and not re.fullmatch(r"\d+(?:\.\d{1,2})?",amount)) or (active_invoice_total and not re.fullmatch(r"\d+(?:\.\d{1,2})?",active_invoice_total)) or (active_invoice_date and not re.fullmatch(r"\d{4}-\d{2}-\d{2}",active_invoice_date)):
            error="Dati del pagamento non validi: controlla importo, totale fattura e data (usa solo numeri e il formato data AAAA-MM-GG)."
            return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
        if payment in ("Acconto","Pagato"):
            try:
                date.fromisoformat(economic_at)
            except ValueError:
                error="La data pagamento/acconto è obbligatoria e deve essere valida."
                return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
        with db() as c:
            row=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not row:return self.send_json({"ok":False,"error":"Pratica non trovata"},404) if ajax else self.send_error(404)
            old=row["payment_status"] or "Da saldare"
            existing_movement,existing_invoice=(
                latest_movement_and_invoice(c,pid,movement_type_prefix)
                if movement_type_prefix and old==payment else (None,None)
            )
            if active_invoice_number:
                conflict=self.invoice_conflict(c,active_invoice_number,exclude_movement_invoice_id=existing_invoice["id"] if existing_invoice else None)
                if conflict:
                    error=f'Numero fattura già usato nella pratica {conflict["practice_number"]}'
                    return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
            stamp=now()
            if old==payment:
                error=self.correct_practice_payment_date(
                    c,row,payment,economic_at,user["id"]
                )
            else:
                error=self.record_payment_transition(c,row,old,payment,amount,method,economic_at,user["id"],"Pagamento registrato",f'practice-payment:{form.get("balance_idempotency_key","").strip() or f"{pid}:{old}:{payment}:{amount}"}',channel=channel)
            if error:
                return self.send_json({"ok":False,"error":error},400) if ajax else self.practice(user,pid,error=error)
            deposit,remaining_balance,deposit_final,remaining_final=recompute_practice_channel_balances(c,pid,row)
            c.execute("UPDATE practices SET payment_status=?,payment_method=?,payment_amount=?,deposit=?,remaining_balance=?,deposit_final=?,remaining_final=?,updated_at=? WHERE id=?",(payment,method,amount,deposit,remaining_balance,deposit_final,remaining_final,stamp,pid))
            if movement_type_prefix:
                movement=c.execute("SELECT id FROM payment_movements WHERE practice_id=? AND payment_type LIKE ? ORDER BY id DESC LIMIT 1",(pid,f"{movement_type_prefix}%")).fetchone()
                if movement:
                    self.save_movement_invoice(c,pid,movement["id"],active_invoice_number,active_invoice_date,active_invoice_total,method,channel or payment_channel(row),user["id"])
            if old!=payment or method!=(row["payment_method"] or ""):
                c.execute("INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",(pid,"Pagamento rapido",old,f'{payment}' + (f' · {money_it(money_value(amount))}' if old!=payment and amount else ''),user["id"],stamp))
            if payment=="Pagato" and old!="Pagato":
                owner=f'{row["owner_first_name"] or ""} {row["owner_last_name"] or ""}'.strip()
                emit_notification(c,"payment_received","Pagamento ricevuto",push_bullets(owner or None,money_it(money_value(amount))),pid,user["id"],db_path=DB_PATH)
        if ajax:return self.send_json({"ok":True,"payment_method":method,"payment_status":payment})
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def save_movement_invoice(self,c,practice_id,movement_id,invoice_number,invoice_date,invoice_total,payment_method,payment_channel_value,user_id):
        """Create or update the single invoice linked to one payment movement.
        Leaves an already-saved invoice untouched if invoice_number is submitted blank,
        so clearing the field never silently deletes real invoice data."""
        existing=c.execute(
            """SELECT mi.* FROM movement_invoices mi JOIN movement_invoice_links mil ON mil.invoice_id=mi.id
               WHERE mil.payment_movement_id=? ORDER BY mi.id DESC LIMIT 1""",
            (movement_id,),
        ).fetchone()
        if not invoice_number:
            return existing["id"] if existing else None
        if existing:
            c.execute(
                "UPDATE movement_invoices SET invoice_number=?,invoice_date=?,invoice_total=?,payment_method=?,payment_channel=? WHERE id=?",
                (invoice_number,invoice_date,invoice_total,payment_method,payment_channel_value,existing["id"]),
            )
            return existing["id"]
        stamp=now()
        cur=c.execute(
            "INSERT INTO movement_invoices(practice_id,invoice_number,invoice_date,invoice_total,payment_method,payment_channel,created_at,created_by) VALUES(?,?,?,?,?,?,?,?)",
            (practice_id,invoice_number,invoice_date,invoice_total,payment_method,payment_channel_value,stamp,user_id),
        )
        invoice_id=cur.lastrowid
        c.execute("INSERT INTO movement_invoice_links(invoice_id,payment_movement_id) VALUES(?,?)",(invoice_id,movement_id))
        return invoice_id

    def quick_state(self,user,pid):
        form=self.form(); new=form.get("status",""); ajax=form.get("ajax")=="1"
        if new not in STATES:return self.send_json({"ok":False,"error":"Stato pratica non valido"},400) if ajax else self.practice(user,pid,error="Stato pratica non valido.")
        with db() as c:
            old=c.execute("SELECT * FROM practices WHERE id=? AND (deleted_at IS NULL OR deleted_at='')",(pid,)).fetchone()
            if not old:return self.send_json({"ok":False,"error":"Pratica non trovata"},404) if ajax else self.send_error(404)
            if new=="Smaltito" and old["service_type"]!="Cremazione collettiva":return self.send_json({"ok":False,"error":"Smaltito è disponibile solo per la cremazione collettiva"},400) if ajax else self.practice(user,pid,error="Smaltito è disponibile solo per la cremazione collettiva.")
            if old["status"]!=new:
                stamp=now();c.execute("UPDATE practices SET status=?,updated_at=? WHERE id=?",(new,stamp,pid))
                c.execute("INSERT INTO practice_history(practice_id,event_type,old_value,new_value,user_id,created_at) VALUES(?,?,?,?,?,?)",(pid,"Cambio stato rapido",old["status"],new,user["id"],stamp))
                if old["status"]=="Consegnato" and new!="Consegnato":self.cancel_whatsapp_scheduled(c,pid,user["id"],"Pratica spostata da Consegnato")
                elif old["status"]!="Consegnato" and new=="Consegnato":self.schedule_whatsapp_thanks(c,pid,user["id"])
                if new=="Consegnato":emit_notification(c,"practice_delivered","Pratica consegnata",old["animal_name"] or old["practice_number"],pid,user["id"],db_path=DB_PATH)
        if ajax:return self.send_json({"ok":True,"status":new,"practice_id":pid})
        return self.redirect(safe_return_path(form.get("return_to") or self.headers.get("Referer"),"/"))

    def resend_whatsapp(self,user,pid):
        if user["role"] != "admin":
            return self.send_error(403)
        f=self.form()
        if f.get("confirm_send") != "SI":
            return self.whatsapp_confirm_page(user,pid,error="Devi confermare l'invio prima di procedere.")
        with db() as c:
            p=c.execute("SELECT * FROM practices WHERE id=?",(pid,)).fetchone()
            if not p: return self.send_error(404)
            active=c.execute("SELECT * FROM whatsapp_messages WHERE practice_id=? AND message_type='ringraziamento' AND status IN ('programmato','in_invio') ORDER BY created_at DESC LIMIT 1",(pid,)).fetchone()
            if active:
                msg_id=active["id"]
                c.execute("UPDATE whatsapp_messages SET status='in_invio', manual=1, updated_at=? WHERE id=?",(now(),msg_id))
            else:
                payload=self.whatsapp_payload_for_practice(p)
                stamp=now()
                cur=c.execute("""INSERT INTO whatsapp_messages(practice_id,scheduled_at,status,attempts,template_name,language_code,recipient_phone,payload_json,manual,message_type,created_at,updated_at)
                                 VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",(pid,stamp,"in_invio",0,payload["template"]["name"],payload["template"]["language"]["code"],payload["to"],json.dumps(payload,ensure_ascii=False),1,"ringraziamento",stamp,stamp))
                msg_id=cur.lastrowid
        # connection released before the network call, same reason as in
        # process_whatsapp_queue: never hold a database lock during it.
        ok,msg=self.send_whatsapp_message(msg_id,manual=True,user_id=user["id"])
        with db() as c:
            c.execute("INSERT INTO practice_history(practice_id,event_type,new_value,user_id,created_at) VALUES(?,?,?,?,?)",(pid,"Invio WhatsApp manuale",msg,user["id"],now()))
        self.redirect(f"/pratiche/{pid}")

